def resource_path(relative_path):
    """PyInstaller 번들과 일반 실행 모두에서 작동하는 리소스 경로 반환
    
    Args:
        relative_path (str): 상대 파일 경로
        
    Returns:
        str: 절대 경로 (PyInstaller 번들 및 일반 실행 모두 지원)
    """
    try:
        # PyInstaller 번들인 경우
        base_path = sys._MEIPASS
    except Exception:
        # 일반 Python 실행인 경우
        base_path = os.path.dirname(os.path.abspath(__file__))
    
    # Windows에서 경로 구분자 통일
    relative_path = relative_path.replace('/', os.sep).replace('\\', os.sep)
    full_path = os.path.join(base_path, relative_path)
    
    return full_path

def check_ball_speed_safety():
    """공 속도 안전성 확인 및 제한"""
    global ball_vel
    import math
    
    current_speed = math.hypot(ball_vel[0], ball_vel[1])
    max_safe_speed = BALL_BASE_SPEED * 2.0  # 기본 속도의 2배가 안전 상한
    
    if current_speed > max_safe_speed:
        # 속도 제한 적용
        scale = max_safe_speed / current_speed
        ball_vel[0] *= scale
        ball_vel[1] *= scale
        print(f"⚠️ 속도 안전 제한 적용: {current_speed:.2f} → {max_safe_speed:.2f}")
        return True
    return False


