def consume_special_gauge(amount):
    global special_gauge
    special_gauge = max(0, special_gauge - amount)

def play_sound_with_volume(sound, volume=None):
    """효과음을 지정된 볼륨으로 재생"""
    global sfx_volume
    if volume is None:
        volume = sfx_volume
    sound.set_volume(volume)
    return sound.play()

def play_dash_sound():
    #  버스트업 스킬이 있으면 bustup.wav 재생
    if acceleration_skill_level > 0:  # 버스트업 스킬 레벨이 1 이상이면
        try:
            play_sound_with_volume(SOUND_BURST_UP)
        except:
            play_sound_with_volume(SOUND_DASH)  # bustup.wav가 없으면 기본 대쉬 사운드 재생
    else:
        play_sound_with_volume(SOUND_DASH)

#  사운드 재생 헬퍼 함수들 (중복 제거용)
def play_active_item_sound():
    """아이템 사용 사운드 재생"""
    play_sound_with_volume(SOUND_ACTIVE_ITEM)

def play_serve_sound():
    """서브 사운드 재생"""
    play_sound_with_volume(SOUND_SERVE)

def play_wall_sound():
    """벽 충돌 사운드 재생"""
    play_sound_with_volume(SOUND_WALL)

def play_paddle_sound():
    """패들 충돌 사운드 재생"""
    play_sound_with_volume(SOUND_PADDLE)

def play_button_hover_sound():
    """버튼 호버 사운드 재생"""
    global sfx_volume
    SOUND_BUTTON_HOVER.set_volume(sfx_volume)
    play_sound_with_volume(SOUND_BUTTON_HOVER)

def play_button_click_sound():
    """버튼 클릭 사운드 재생"""
    global sfx_volume
    SOUND_BUTTON_CLICK.set_volume(sfx_volume)
    play_sound_with_volume(SOUND_BUTTON_CLICK)

def play_ragnarok_shot_sound():
    """라그나로크 스턴볼 발사 사운드 재생"""
    try:
        play_sound_with_volume(SOUND_RAGNAROK_SHOT)
    except:
        pass  # 사운드 파일이 없으면 무시

def play_ragnarok_boom_sound():
    """라그나로크 보스 반격 사운드 재생"""
    try:
        play_sound_with_volume(SOUND_RAGNAROK_BOOM)
    except:
        pass  # 사운드 파일이 없으면 무시

def play_ragnarok_shock_sound():
    """라그나로크 전기 감전 사운드 재생 (루프)"""
    try:
        # -1은 무한 루프를 의미
        SOUND_RAGNAROK_SHOCK.play(-1)
    except:
        pass  # 사운드 파일이 없으면 무시

def stop_ragnarok_shock_sound():
    """라그나로크 전기 감전 사운드 중지"""
    try:
        SOUND_RAGNAROK_SHOCK.stop()
    except:
        pass  # 사운드 파일이 없으면 무시

#  파티클 생성 헬퍼 함수들 (중복 제거용)
def create_energy_particle(x, y, particle_list, speed_range=(0.5, 2), life=25):
    """에너지 파티클 생성"""
    angle = random.uniform(0, 2 * math.pi)
    speed = random.uniform(*speed_range)
    particle_list.append({
        'x': x + random.randint(-5, 5),
        'y': y + random.randint(-5, 5),
        'vx': math.cos(angle) * speed,
        'vy': math.sin(angle) * speed,
        'life': life,
        'color': random.choice([(100, 150, 255), (150, 200, 255), (200, 220, 255)]),
        'type': 'energy'
    })

def create_spark_particle(x, y, particle_list, speed_range=(2, 4), life=15):
    """전기 스파크 파티클 생성"""
    angle = random.uniform(0, 2 * math.pi)
    speed = random.uniform(*speed_range)
    particle_list.append({
        'x': x + random.randint(-3, 3),
        'y': y + random.randint(-3, 3),
        'vx': math.cos(angle) * speed,
        'vy': math.sin(angle) * speed,
        'life': life,
        'color': (255, 255, 100),
        'type': 'spark'
    })

def create_neon_particle(x, y, particle_list, color=None, speed_range=(1, 3)):
    """네온 파티클 생성"""
    angle = random.uniform(0, 2 * math.pi)
    speed = random.uniform(*speed_range)
    if color is None:
        color = random.choice([(255, 100, 200), (100, 255, 200), (200, 100, 255)])
    particle_list.append({
        'x': x,
        'y': y,
        'vx': math.cos(angle) * speed,
        'vy': math.sin(angle) * speed,
        'life': 30,
        'alpha': 255,
        'color': color,
        'size': random.randint(2, 5)
    })

def create_shadow_particle(x, y, particle_list, life=10):
    """그림자 파티클 생성"""
    particle_list.append({
        'x': x,
        'y': y,
        'life': life,
        'alpha': 100,
        'color': (50, 50, 50)
    })

dash = dash_manager.init_dash_manager(
    academy.get_skill_bonus,
    get_special_gauge, 
    consume_special_gauge,
    play_dash_sound
)
