def handle_new_boss_skills_timer():
    """새로운 보스들의 스킬 타이머 처리"""
    global lightning_strike_active, lightning_strike_timer
    global ice_barrier_active, ice_barrier_timer
    global fire_charge_active, fire_charge_timer
    global wind_burst_active, wind_burst_timer
    global ball_vel
    if not new_boss_mode_active:
        return
    # 라이트닝 마스터 스킬 타이머 - 번개 충격 활성화 시 공 속도 증가
    if lightning_strike_active and lightning_strike_timer > 0:
        lightning_strike_timer -= 1
        # 번개 충격 효과: 공 속도 증가
        if ball_vel[1] < 0:  # 공이 위로 향할 때만 (하단에서 상단으로)
            ball_vel[0] *= 1.02  # X축 속도 증가
            ball_vel[1] *= 1.02  # Y축 속도 증가
            # 번개 효과로 공에 약간의 랜덤성 추가
            if lightning_strike_timer % 15 == 0:  # 15프레임마다
                thunder_force_x = random.uniform(-0.5, 0.5)
                thunder_force_y = random.uniform(-0.3, 0.3)
                ball_vel[0] += thunder_force_x
                ball_vel[1] += thunder_force_y
            # 속도 안전성 검사
            check_ball_speed_safety()
        if lightning_strike_timer <= 0:
            lightning_strike_active = False
            print("!")
    # 아이스 퀸 스킬 타이머 - 얼음 방벽 활성화 시 공 속도 50% 감소
    if ice_barrier_active and ice_barrier_timer > 0:
        ice_barrier_timer -= 1
        # 얼음 방벽 효과: 공 속도 감소
        if ball_vel[1] < 0:  # 공이 위로 향할 때만 (상단 보스에게 향할 때)
            ball_vel[0] *= 0.98  # X축 속도 감소
            ball_vel[1] *= 0.98  # Y축 속도 감소
        if ice_barrier_timer <= 0:
            ice_barrier_active = False
            print("!")
    # 파이어 나이트 스킬 타이머
    if fire_charge_active and fire_charge_timer > 0:
        fire_charge_timer -= 1
        if fire_charge_timer <= 0:
            fire_charge_active = False
            print("!")
    # 윈드 스피릿 스킬 타이머 - 바람 폭발 시 공을 랜덤하게 튕겨냄
    if wind_burst_active and wind_burst_timer > 0:
        wind_burst_timer -= 1
        # 바람 폭발 효과: 공에 랜덤한 힘 적용
        if wind_burst_timer == wind_burst_duration - 1:  # 스킬 발동 직후 한 번만
            wind_force_x = random.uniform(-3, 3)
            wind_force_y = random.uniform(-2, 2)
            ball_vel[0] += wind_force_x
            ball_vel[1] += wind_force_y
            print(f"  !    : ({wind_force_x:.1f}, {wind_force_y:.1f})")
        if wind_burst_timer <= 0:
            wind_burst_active = False
            print("!")

def fire_soldier_bullet():
    """군인 캐릭터가 총알을 발사하는 함수"""
    global soldier_bullets, soldier_gun_cooldown, soldier_control_lock_timer, soldier_gun_drawn
    
    if soldier_gun_cooldown > 0:
        return  # 쿨타임 중이면 발사 불가
    
    # 총을 꺼내고 통제불능 시작
    soldier_gun_drawn = True
    soldier_control_lock_timer = SOLDIER_CONTROL_LOCK_TIME
    soldier_gun_cooldown = SOLDIER_GUN_COOLDOWN
    
    # 플레이어 위치에서 보스 방향으로 총알 발사
    player_center_x = PLAYER.centerx
    player_center_y = PLAYER.centery
    boss_center_x = BOSS.centerx
    boss_center_y = BOSS.centery
    
    # 방향 벡터 계산
    dx = boss_center_x - player_center_x
    dy = boss_center_y - player_center_y
    distance = math.sqrt(dx**2 + dy**2)
    
    if distance > 0:
        # 정규화된 방향 벡터
        dx_norm = dx / distance
        dy_norm = dy / distance
        
        # 총알 생성
        bullet = {
            "x": player_center_x,
            "y": player_center_y - 20,  # 패들 위쪽에서 발사
            "vel_x": dx_norm * SOLDIER_BULLET_SPEED,
            "vel_y": dy_norm * SOLDIER_BULLET_SPEED,
            "active": True
        }
        soldier_bullets.append(bullet)
        
        # 총 발사 효과음 재생
        try:
            gun_sound = pygame.mixer.Sound(resource_path("sounds/gun_shot.wav"))
            gun_sound.set_volume(0.5)
            gun_sound.play()
        except:
            pass
        
        print(f"🔫 총알 발사! 방향: ({dx_norm:.2f}, {dy_norm:.2f})")

def update_soldier_bullets():
    """군인 총알 업데이트"""
    global soldier_bullets
    
    # 비활성 총알 제거
    soldier_bullets = [b for b in soldier_bullets if b["active"]]
    
    # 각 총알 업데이트
    for bullet in soldier_bullets:
        if bullet["active"]:
            # 위치 업데이트
            bullet["x"] += bullet["vel_x"]
            bullet["y"] += bullet["vel_y"]
            
            # 화면 밖으로 나가면 비활성화
            if (bullet["x"] < -50 or bullet["x"] > WIDTH + 50 or 
                bullet["y"] < -50 or bullet["y"] > HEIGHT + 50):
                bullet["active"] = False
            
            # 보스와의 충돌 검사
            bullet_rect = pygame.Rect(bullet["x"] - SOLDIER_BULLET_SIZE, 
                                     bullet["y"] - SOLDIER_BULLET_SIZE,
                                     SOLDIER_BULLET_SIZE * 2, 
                                     SOLDIER_BULLET_SIZE * 2)
            
            if bullet_rect.colliderect(BOSS):
                bullet["active"] = False
                # 보스 스턴 효과 (0.5초)
                global boss_stun_timer
                boss_stun_timer = 30  # 0.5초 스턴
                
                # 타격 효과음
                try:
                    hit_sound = pygame.mixer.Sound(resource_path("sounds/bullet_hit.wav"))
                    hit_sound.set_volume(0.6)
                    hit_sound.play()
                except:
                    pass
                
                # 타격 이펙트 생성
                for _ in range(10):
                    impact_particles.append({
                        "x": bullet["x"],
                        "y": bullet["y"],
                        "vx": random.uniform(-5, 5),
                        "vy": random.uniform(-5, 5),
                        "size": random.uniform(3, 6),
                        "alpha": 255,
                        "color": SOLDIER_BULLET_COLOR,
                        "life": 30
                    })
                
                print("💥 총알이 보스에게 명중! 보스 스턴!")

def draw_soldier_bullets(screen):
    """군인 총알 그리기"""
    for bullet in soldier_bullets:
        if bullet["active"]:
            # 총알 본체
            pygame.draw.circle(screen, SOLDIER_BULLET_COLOR, 
                             (int(bullet["x"]), int(bullet["y"])), 
                             SOLDIER_BULLET_SIZE)
            
            # 총알 광택 효과
            pygame.draw.circle(screen, (255, 255, 200), 
                             (int(bullet["x"] - 2), int(bullet["y"] - 2)), 
                             SOLDIER_BULLET_SIZE // 2)

