def activate_emotional_overdrive():
    global emotional_overdrive_active, emotional_overdrive_timer
    global overdrive_flash_timer, overdrive_trails
    emotional_overdrive_active = True
    emotional_overdrive_timer = 300  # 약 5초간 지속 (60fps 기준)
    overdrive_flash_timer = HALF_SECOND_FRAMES  # 0.5초마다 반짝임
    overdrive_trails.clear()
    
    # 사이코볼 사운드 재생 (루프)
    try:
        psycho_sound = pygame.mixer.Sound(resource_path("sounds/psychoball.wav"))
        channel = psycho_sound.play(-1)  # -1 = 무한 루프
        channel.set_volume(0.5)
        # 채널을 저장해서 나중에 중지할 수 있도록
        globals()['psycho_sound_channel'] = channel
    except:
        print(": sounds/psychoball.wav")
def handle_emotional_overdrive():
    global emotional_overdrive_active, emotional_overdrive_timer
    global overdrive_flash_timer, overdrive_trails, ball_vel
    global psycho_bg_timer  #  배경 깜빡임 타이머
    global smoke_zones, BALL  # 연막탄 체크용
    if not emotional_overdrive_active:
        return
    
    #  Stage 3: 연막탄 연기에 공이 닿으면 사이코볼 강제 종료
    if current_stage == 3:
        for smoke_zone in smoke_zones:
            if smoke_zone["opacity"] > 50:  # 연막이 충분히 진할 때만
                # 공과 연막 중심 사이의 타원형 거리 계산
                dx = BALL.centerx - smoke_zone["x"]
                dy = BALL.centery - smoke_zone["y"]
                radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
                radius_y = smoke_zone["radius"]
                # 타원 방정식: (x/a)^2 + (y/b)^2 <= 1
                if radius_x > 0 and radius_y > 0:
                    ellipse_distance = (dx / radius_x) ** 2 + (dy / radius_y) ** 2
                else:
                    ellipse_distance = float('inf')
                if ellipse_distance <= 1:
                    # 사이코볼 즉시 종료
                    print("!")
                    emotional_overdrive_active = False
                    emotional_overdrive_timer = 0
                    overdrive_trails.clear()
                    psycho_bg_timer = 0
                    
                    # 사이코볼 사운드 중지
                    if 'psycho_sound_channel' in globals() and psycho_sound_channel:
                        psycho_sound_channel.stop()
                    
                    # 공을 보스 방향으로 보내기
                    # 보스 패들 중심 위치 계산
                    boss_center_x = BOSS.centerx if BOSS else WIDTH // 2
                    boss_center_y = BOSS.centery if BOSS else 100
                    
                    # 공에서 보스로의 방향 벡터 계산
                    dx = boss_center_x - BALL.centerx
                    dy = boss_center_y - BALL.centery
                    distance = math.sqrt(dx**2 + dy**2)
                    
                    # 방향 정규화 후 적절한 속도 적용 (플레이어가 대응 가능한 수준)
                    if distance > 0:
                        ball_vel[0] = (dx / distance) * 10  # 속도 10으로 설정
                        ball_vel[1] = (dy / distance) * 10
                    else:
                        # 거리가 0이면 위로 발사
                        ball_vel[0] = 0
                        ball_vel[1] = -10
                    
                    print(f"    ! : ({ball_vel[0]:.1f}, {ball_vel[1]:.1f})")
                    
                    # 무효화 시각 효과 - 보라색 파티클 폭발
                    for i in range(20):
                        angle = random.uniform(0, 2 * math.pi)
                        speed = random.uniform(2, 8)
                        particle = {
                            'x': BALL.centerx,
                            'y': BALL.centery,
                            'vx': math.cos(angle) * speed,
                            'vy': math.sin(angle) * speed,
                            'life': 30,
                            'color': (random.randint(150, 200), 0, random.randint(150, 255))  # 보라색 계열
                        }
                        if 'neutralize_particles' not in globals():
                            global neutralize_particles
                            neutralize_particles = []
                        neutralize_particles.append(particle)
                    
                    # 시각적/청각적 피드백
                    try:
                        # 연막 효과음 재생
                        smoke_sound = pygame.mixer.Sound(resource_path("sounds/smoke_neutralize.wav"))
                        smoke_sound.set_volume(0.7)
                        play_sound_with_volume(smoke_sound)
                    except:
                        # 효과음 없으면 기본 사운드
                        try:
                            play_paddle_sound()
                        except:
                            pass
                    return
    
    emotional_overdrive_timer -= 1
    if emotional_overdrive_timer <= 0:
        emotional_overdrive_active = False
        overdrive_trails.clear()
        psycho_bg_timer = 0  #  배경 깜빡임 타이머 초기화
        
        # 사이코볼 사운드 중지
        if 'psycho_sound_channel' in globals() and psycho_sound_channel:
            psycho_sound_channel.stop()
        
        return
    # 1. 공 곡선 이동
    time_now = pygame.time.get_ticks()
    curve = math.sin(time_now / 80) * 3
    ball_vel[0] += curve * random.uniform(0.5, 1.2)
    # 2. 공 순간이동 (랜덤 확률)
    if random.random() < 0.01:
        BALL.centerx = random.randint(50, WIDTH - 50)
        BALL.centery = random.randint(150, HEIGHT - 150)
    # 3. 보스 잔상 추가
    overdrive_trails.append((BOSS.centerx, BOSS.centery, 200))
    overdrive_trails = [(x, y, a - 10) for x, y, a in overdrive_trails if a > 10][:15]
    # 4. 보스 반짝임 타이머
    overdrive_flash_timer -= 1
    if overdrive_flash_timer <= 0:
        overdrive_flash_timer = HALF_SECOND_FRAMES
    # 5. 배경 깜빡임 타이머 증가 (draw_field에서 사용됨)
    psycho_bg_timer += 1
def handle_aipill():
    """AI 필 효과 처리 함수 - 게이지 기반 지속시간"""
    global aipill_active
    # 게이지 기반으로 처리되므로 타이머는 사용하지 않음
    # 공 충돌 시 게이지 감소 및 종료 처리는 handle_player에서 처리됨
    pass
def is_player_in_smoke():
    """플레이어가 연막 안에 있는지 확인하는 함수"""
    global smoke_zones, PLAYER
    
    # 기존 연막탄 연기 체크
    for smoke_zone in smoke_zones:
        if smoke_zone["opacity"] > 50:  # 연막이 충분히 진할 때만
            # 플레이어와 연막 중심 사이의 타원형 거리 계산
            dx = PLAYER.centerx - smoke_zone["x"]
            dy = PLAYER.centery - smoke_zone["y"]
            radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
            radius_y = smoke_zone["radius"]
            # 타원 방정식: (x/a)^2 + (y/b)^2 <= 1
            if radius_x > 0 and radius_y > 0:
                ellipse_distance = (dx / radius_x) ** 2 + (dy / radius_y) ** 2
            else:
                ellipse_distance = float('inf')
            if ellipse_distance <= 1:
                return True
    
    # 테크니컬조끼 연막 체크
    if check_technical_vest_smoke_collision(PLAYER.centerx, PLAYER.centery):
        return True
    
    return False
def handle_wall():
    """벽돌 설치 및 관리 함수"""
    global walls, wall_installing, wall_install_timer, wall_install_gauge_visible
    global boss_stunned_timer, boss_knockback_vel, explosion_zones, grenades
    global boss_confused_timer, flares, flare_zones, last_hit_by
    global boss_current_health, boss_max_health  #  체력형 보스 체력 변수
    global boss_fire_hit_count, boss_fire_hit_timer  #  보스 화염 타격 카운터
    # 설치 중인 경우
    if wall_installing:
        wall_install_timer -= 1
        if wall_install_timer <= 0:
            wall_installing = False
            wall_install_gauge_visible = False  # 설치 게이지 숨기기
            print("!    .")
    # 파괴된 벽돌들 제거 (부서지는 이펙트 생성)
    destroyed_walls = [wall for wall in walls if wall["hit_count"] >= 2]
    for wall in destroyed_walls:
        # 벽돌 부서지는 파티클 이펙트 생성
        create_brick_destruction_effect(wall["rect"])
    walls = [wall for wall in walls if wall["hit_count"] < 2]
    # 수류탄 업데이트
    global grenade_shake_timer, boss_stunned_timer, boss_knockback_vel, explosion_zones
    for grenade in grenades[:]:
        # 중력 적용
        if grenade["gravity"] > 0:
            grenade["vel_y"] += grenade["gravity"]
        grenade["x"] += grenade["vel_x"]
        grenade["y"] += grenade["vel_y"]
        grenade["rotation"] += 15  # 회전 (화염병보다 빠름)
        # 목표 지점에 도달했는지 체크
        if abs(grenade["x"] - grenade["target_x"]) < 30 and abs(grenade["y"] - grenade["target_y"]) < 30:
            # 폭발 효과 - 화염병보다 넓은 범위
            import items
            # 코만도암 효과: 폭발 범위 10% 증가
            base_radius = 150  # 폭발 반경 (120에서 150으로 증가)
            if items.commando_arm_obtained:
                explosion_radius = int(base_radius * 1.1)  # 10% 증가
                print(f"  !   : {explosion_radius} (: {base_radius})")
            else:
                explosion_radius = base_radius
            
            explosion_zone = {
                "x": grenade["x"],
                "y": grenade["y"],
                "radius": explosion_radius,  # 코만도암 효과 적용된 폭발 반경
                "duration": 15,  # 폭발 효과 지속 시간 (짧음)
                "active": True
            }
            # 화면 흔들림 효과 시작 (폭발하면 무조건 흔들림)
            grenade_shake_timer = 40  # 40프레임 동안 흔들림 (2배로 증가)
            play_sound_with_volume(SOUND_GRENADE)  #  수류탄 폭발 사운드 재생
            print(f"  !   : {grenade_shake_timer}")
            # 보스가 폭발 범위 내에 있는지 체크
            boss_center_x = BOSS.centerx
            boss_center_y = BOSS.centery
            distance = calculate_distance((boss_center_x, boss_center_y), (grenade["x"], grenade["y"]))
            if distance < explosion_zone["radius"]:
                # 보스 스턴 및 넉백 효과
                boss_stunned_timer = 120  # 2초 스턴
                # 화염병처럼 넉백 효과 (튕겨나가는 느낌)
                knockback_power = 40  # 넉백 강도 조정
                if grenade["x"] < WIDTH / 2:
                    # 수류탄이 왼쪽에서 터지면 보스를 오른쪽으로 넉백
                    boss_knockback_vel = knockback_power
                else:
                    # 수류탄이 오른쪽에서 터지면 보스를 왼쪽으로 넉백
                    boss_knockback_vel = -knockback_power
                #  체력형 보스 수류탄 데미지 적용
                if current_stage in boss_health_stages:
                    boss_current_health = max(0, boss_current_health - 3)  # 수류탄 데미지 3
                    print(f"  !   -{3} (: {boss_current_health}/{boss_max_health})")
                else:
                    print(f"  !")
                
                #  Stage 5 홍련 수류탄 피격 효과 - 100% 확률
                if current_stage == 5:
                    stage5_boss_hurt_active = True
                    stage5_boss_hurt_timer = 18  # 0.3초 (60 FPS 기준)
                    
                    # 피격 사운드 재생 (3개 중 랜덤)
                    if SOUND_STAGE5_HURTS:
                        play_sound_with_volume(random.choice(SOUND_STAGE5_HURTS))
                    
                    #  트레이드 별 2개 드롭
                    for i in range(2):
                        trade_point_system.spawn_star(
                            BOSS.centerx + random.randint(-50, 50),
                            BOSS.centery + random.randint(-20, 20),
                            source_type="hongryun_grenade"
                        )
                    
                    print(f" Stage 5   ! (100% )   2 !")
            
            #  폭발 범위 내의 바위들 파괴 (스테이지 2)
            if current_stage == 2 and animated_bg_stage2 is not None:
                rocks_to_destroy = []
                for rock in animated_bg_stage2.crisis_rocks:
                    if not rock['falling']:  # 떨어진 바위만 체크
                        rock_center_x = rock['x']
                        rock_center_y = rock['y']
                        rock_distance = calculate_distance((rock_center_x, rock_center_y), (grenade["x"], grenade["y"]))
                        if rock_distance < explosion_zone["radius"]:
                            rocks_to_destroy.append(rock)
                
                # 폭발 범위 내의 모든 바위 파괴
                for rock in rocks_to_destroy:
                    # 황금 바위인 경우 Trade Point 별 생성
                    if rock.get('is_golden', False):
                        trade_point_system.spawn_star(rock['x'], rock['y'], "golden_rock")
                        print(f"    ! Trade Point  !")
                    
                    animated_bg_stage2.destroy_rock(rock)
                    animated_bg_stage2.crisis_rocks.remove(rock)
                    
                if rocks_to_destroy:
                    print(f"    {len(rocks_to_destroy)} !")
            
            #  폭발 범위 내의 까마귀들 파괴 (스테이지 4)
            if current_stage == 4 and animated_bg_stage4 is not None:
                crow_positions = animated_bg_stage4.get_crow_positions()
                crows_to_destroy = []
                
                for crow_data in crow_positions:
                    crow_distance = calculate_distance((crow_data['x'], crow_data['y']), (grenade["x"], grenade["y"]))
                    if crow_distance < explosion_zone["radius"]:
                        crows_to_destroy.append(crow_data)
                
                # 폭발 범위 내의 모든 까마귀 파괴 및 Trade Point 별 생성
                for crow_data in sorted(crows_to_destroy, key=lambda x: x['index'], reverse=True):  # 역순으로 제거
                    if animated_bg_stage4.catch_crow(crow_data['index']):
                        # Trade Point 별 생성
                        trade_point_system.spawn_star(crow_data['x'], crow_data['y'], "crow")
                        print(f"    ! Trade Point  !")
                
                if crows_to_destroy:
                    print(f"    {len(crows_to_destroy)} !")
            
            # 현실감 있는 수류탄 폭발 효과
            # 1. 폭발 파편 효과 (다양한 크기와 속도)
            for _ in range(50):  # 파편 수 증가
                angle = random.uniform(0, FULL_ROTATION)
                speed = random.uniform(5.0, 15.0)  # 더 빠른 파편
                vx = math.cos(math.radians(angle)) * speed
                vy = math.sin(math.radians(angle)) * speed
                tear_particles.append([
                    grenade["x"] + random.uniform(-10, 10),
                    grenade["y"] + random.uniform(-10, 10),
                    vx, vy,
                    255,  # alpha
                    random.randint(3, 8)  # 다양한 크기의 파편
                ])
            # 2. 연기 효과 (회색 파티클)
            for _ in range(TILE_SIZE):
                angle = random.uniform(0, FULL_ROTATION)
                speed = random.uniform(1.0, 4.0)  # 느린 연기
                vx = math.cos(math.radians(angle)) * speed
                vy = math.sin(math.radians(angle)) * speed - 0.5  # 위로 올라가는 연기
                tear_particles.append([
                    grenade["x"] + random.uniform(-30, 30),
                    grenade["y"] + random.uniform(-30, 30),
                    vx, vy,
                    180,  # alpha
                    random.randint(15, 25)  # 큰 연기 입자
                ])
            # 3. 폭발 섬광 효과 (노란색/주황색 불꽃)
            for _ in range(20):
                angle = random.uniform(0, FULL_ROTATION)
                speed = random.uniform(8.0, 12.0)
                vx = math.cos(math.radians(angle)) * speed
                vy = math.sin(math.radians(angle)) * speed
                tear_particles.append([
                    grenade["x"],
                    grenade["y"],
                    vx, vy,
                    255,  # alpha
                    random.randint(10, 15)  # 섬광 크기
                ])
            explosion_zones.append(explosion_zone)
            grenades.remove(grenade)
            # 폭발 효과음
            try:
                play_wall_sound()
            except:
                pass
            print(f"  ! : X={explosion_zone['x']:.1f}, Y={explosion_zone['y']:.1f}, : {explosion_zone['radius']}")
    # 폭발 지역 업데이트 (지속시간 감소)
    explosion_zones = [zone for zone in explosion_zones if zone["duration"] > 0]
    for zone in explosion_zones:
        zone["duration"] -= 1
    # 연막탄 업데이트
    for smoke_grenade in smoke_grenades[:]:
        if not smoke_grenade["arrived"]:
            # 포물선 궤적으로 비행
            smoke_grenade["vel_y"] += smoke_grenade["gravity"]  # 중력 적용
            smoke_grenade["x"] += smoke_grenade["vel_x"]
            smoke_grenade["y"] += smoke_grenade["vel_y"]
            smoke_grenade["rotation"] += 15  # 더 빠른 회전
            # 궤적 추가 (흔적 효과)
            if len(smoke_grenade["trail"]) > 10:
                smoke_grenade["trail"].pop(0)
            smoke_grenade["trail"].append((smoke_grenade["x"], smoke_grenade["y"]))
            # 목표 지점 도달 체크 (바닥에 닿으면)
            if smoke_grenade["y"] >= smoke_grenade["target_y"]:
                smoke_grenade["arrived"] = True
                smoke_grenade["y"] = smoke_grenade["target_y"]
                print(f"  ! 1")
                # 착지 효과음
                try:
                    play_paddle_sound()
                except:
                    pass
        elif smoke_grenade["timer"] < 60:  # 1초 대기
            smoke_grenade["timer"] += 1
            # 1초 후 연막 생성
            if smoke_grenade["timer"] >= 60:
                # 연막 지역 생성
                import items
                # 코만도암 효과: 연막탄 지속시간 50% 증가
                base_duration = 600  # 10초 지속 (9초 + 1초 페이드아웃)
                if items.commando_arm_obtained:
                    smoke_duration = int(base_duration * 1.5)  # 50% 증가 (15초)
                    print(f"  !  : {smoke_duration/60:.1f} (: {base_duration/60:.1f})")
                else:
                    smoke_duration = base_duration
                
                smoke_zone = {
                    "x": smoke_grenade["x"],
                    "y": smoke_grenade["target_y"],
                    "radius": 0,  # 초기 반경 0에서 시작
                    "max_radius": 180,  # 최대 세로 반경
                    "radius_x": 0,  # 가로 반경 (별도 관리)
                    "max_radius_x": 240,  # 최대 가로 반경 (240픽셀)
                    "duration": smoke_duration,  # 코만도암 효과 적용된 지속시간
                    "particles": [],  # 연막 파티클들
                    "opacity": 0,  # 초기 투명도
                    "expansion_rate": 5,  # 세로 확장 속도
                    "expansion_rate_x": 6.7  # 가로 확장 속도 (240/36 프레임)
                }
                # 화로 연막탄인 경우 플래그 전달
                if 'is_brazier_smoke' in smoke_grenade:
                    smoke_zone['is_brazier_smoke'] = True
                # 초기 연막 파티클 생성 (중앙에서 시작, 가로로 더 넓게)
                for i in range(40):  # 파티클 수 증가
                    angle = random.uniform(0, 2 * math.pi)
                    dist = random.uniform(0, 10)
                    particle = {
                        "x": smoke_zone["x"] + math.cos(angle) * dist * 2,  # 가로로 2배
                        "y": smoke_zone["y"] + math.sin(angle) * dist,
                        "size": random.uniform(20, 40),  # 더 큰 파티클
                        "vel_x": math.cos(angle) * random.uniform(1.0, 3.0),  # 가로로 더 빠르게 퍼짐
                        "vel_y": random.uniform(-0.5, -0.2),
                        "lifetime": random.uniform(80, 150)
                    }
                    smoke_zone["particles"].append(particle)
                smoke_zones.append(smoke_zone)
                smoke_grenades.remove(smoke_grenade)
                # 연막 분출 효과음 (이미 사용 시 재생했으므로 제거)
                # 연막이 생성되는 시각적 효과만 표시
                print(f"  ! 9 .")
    # 연막 지역 업데이트
    for smoke_zone in smoke_zones[:]:
        smoke_zone["duration"] -= 1
        # 연막 반경 점진적 확대 (타원형)
        if smoke_zone["radius"] < smoke_zone["max_radius"]:
            smoke_zone["radius"] = min(smoke_zone["max_radius"], 
                                      smoke_zone["radius"] + smoke_zone["expansion_rate"])
        if "radius_x" in smoke_zone and smoke_zone["radius_x"] < smoke_zone["max_radius_x"]:
            smoke_zone["radius_x"] = min(smoke_zone["max_radius_x"], 
                                        smoke_zone["radius_x"] + smoke_zone["expansion_rate_x"])
        
        # Stage 4에서 화로 점화 체크 (연막이 확장되면서 화로에 닿는지 확인)
        if (current_stage == 4 and animated_bg_stage4 and 
            smoke_zone.get('is_brazier_smoke', False) and 
            not smoke_zone.get('brazier_checked', False)):
            # 연막이 충분히 확장되었을 때 화로 점화 체크
            if smoke_zone["radius"] >= 50:  # 어느 정도 확장된 후 체크
                # 디버그: 화로 위치와 연막 위치 출력
                brazier_x, brazier_y = animated_bg_stage4.get_brazier_position()
                distance = math.sqrt((smoke_zone["x"] - brazier_x)**2 + (smoke_zone["y"] - brazier_y)**2)
                print(f"   - :({smoke_zone['x']:.0f},{smoke_zone['y']:.0f}),"
                      f"화로위치:({brazier_x},{brazier_y}), 연막반경:{smoke_zone['radius']:.0f}, "
                      f"거리:{distance:.1f}")
                
                lit = animated_bg_stage4.check_smoke_touches_brazier(
                    smoke_zone["x"], smoke_zone["y"], smoke_zone["radius"])
                if lit:
                    print(f"     !")
                    smoke_zone['has_lit_brazier'] = True
                else:
                    print(f"    -")
                smoke_zone['brazier_checked'] = True  # 중복 체크 방지
        # 투명도 조절 (서서히 나타났다가 사라짐)
        if smoke_zone["duration"] > 540:  # 처음 1초: 페이드인
            smoke_zone["opacity"] = min(150, smoke_zone["opacity"] + 5)
        elif smoke_zone["duration"] > 60:  # 중간 8초: 유지
            smoke_zone["opacity"] = 150
        else:  # 마지막 1초: 페이드아웃
            smoke_zone["opacity"] = max(0, smoke_zone["opacity"] - 3)
        # 파티클 추가 생성 (지속적인 연기 효과, 타원형)
        if smoke_zone["duration"] > 60 and len(smoke_zone["particles"]) < 60:  # 파티클 수 증가
            if random.random() < 0.5:  # 50% 확률로 새 파티클
                angle = random.uniform(0, 2 * math.pi)
                # 타원형 분포
                radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
                radius_y = smoke_zone["radius"]
                dist_x = random.uniform(0, radius_x * 0.7)
                dist_y = random.uniform(0, radius_y * 0.7)
                particle = {
                    "x": smoke_zone["x"] + math.cos(angle) * dist_x,
                    "y": smoke_zone["y"] + math.sin(angle) * dist_y,
                    "size": random.uniform(30, 50),  # 더 큰 파티클
                    "vel_x": math.cos(angle) * random.uniform(0.3, 1.2),  # 가로로 더 활발한 움직임
                    "vel_y": random.uniform(-0.2, -0.05),
                    "lifetime": random.uniform(40, 80)
                }
                smoke_zone["particles"].append(particle)
        # 파티클 업데이트
        for particle in smoke_zone["particles"][:]:
            particle["x"] += particle["vel_x"]
            particle["y"] += particle["vel_y"]
            particle["lifetime"] -= 1
            particle["size"] *= 0.99  # 서서히 작아짐
            if particle["lifetime"] <= 0 or particle["size"] < 5:
                smoke_zone["particles"].remove(particle)
        # 공이 연막 안에 있는지 체크 (타원형)
        dx = BALL.centerx - smoke_zone["x"]
        dy = BALL.centery - smoke_zone["y"]
        radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
        radius_y = smoke_zone["radius"]
        # 타원 방정식: (x/a)^2 + (y/b)^2 <= 1
        if radius_x > 0 and radius_y > 0:
            ellipse_distance = (dx / radius_x) ** 2 + (dy / radius_y) ** 2
        else:
            ellipse_distance = float('inf')
        if ellipse_distance <= 1 and smoke_zone["opacity"] > 50:
            # 보스가 친 공만 연막 효과 적용 (플레이어가 친 공은 무시)
            if last_hit_by == "boss":
                # 현재 공 속도 계산
                current_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                
                # 공속이 25 이상일 때만 연막 효과 적용
                if current_speed >= 25:
                    # 처음 진입 시 원래 속도 저장 및 즉시 60%로 감속
                    if not hasattr(smoke_zone, "affecting_ball"):
                        smoke_zone["affecting_ball"] = True
                        smoke_zone["original_speed"] = current_speed  # 원래 속도 저장
                        
                        # 즉시 60%로 감속 (40% 감소)
                        speed_factor = 0.6
                        ball_vel[0] *= speed_factor
                        ball_vel[1] *= speed_factor
                        
                        new_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                        print(f"     !  60% ! ({current_speed:.1f} → {new_speed:.1f})")
                    # 이미 연막 안에 있는 경우 60% 속도 유지
                    else:
                        # 60% 속도 유지 (더 이상 감속하지 않음)
                        pass
                elif current_speed > 15.0:
                    # 15~25 구간은 기존 점진적 감속 유지
                    speed_reduction = 0.97  # 매 프레임마다 3% 감속
                    ball_vel[0] *= speed_reduction
                    ball_vel[1] *= speed_reduction
                    # 최소 속도 보장
                    min_speed = 2.0
                    current_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                    if current_speed < min_speed and current_speed > 0:
                        speed_factor = min_speed / current_speed
                        ball_vel[0] *= speed_factor
                        ball_vel[1] *= speed_factor
                    # 처음 진입 시에만 메시지 출력
                    if not hasattr(smoke_zone, "affecting_ball"):
                        smoke_zone["affecting_ball"] = True
                        print(f"     !   ... ( : {current_speed:.1f})")
                else:
                    # 느린 공은 디버프 적용 안함
                    if not hasattr(smoke_zone, "slow_ball_ignored"):
                        smoke_zone["slow_ball_ignored"] = True
                        print(f"     ! ( : {current_speed:.1f} <= 15.0)")
            else:
                # 플레이어가 친 공은 연막 효과 무시
                if not hasattr(smoke_zone, "player_ball_ignored"):
                    smoke_zone["player_ball_ignored"] = True
                    print(f"      !")
        else:
            # 연막을 벗어나면 플래그 제거
            if hasattr(smoke_zone, "affecting_ball"):
                del smoke_zone["affecting_ball"]
                print(f"")
            if hasattr(smoke_zone, "original_speed"):
                del smoke_zone["original_speed"]
            if hasattr(smoke_zone, "slow_ball_ignored"):
                del smoke_zone["slow_ball_ignored"]
            if hasattr(smoke_zone, "player_ball_ignored"):
                del smoke_zone["player_ball_ignored"]
        # 지속시간 종료 체크
        if smoke_zone["duration"] <= 0:
            # Stage 4에서 화로를 통해 소환된 몽크가 있으면 30초 후 귀환 타이머 시작
            if current_stage == 4 and animated_bg_stage4 and smoke_zone.get('has_lit_brazier', False):
                animated_bg_stage4.trigger_smoke_grenade_monk_return()
                print(f"  !  30   .")
            smoke_zones.remove(smoke_zone)
    # 조명탄 업데이트
    for flare in flares[:]:
        if not flare["arrived"]:
            # 아직 날아가는 중이면 이동
            flare["x"] += flare["vel_x"]
            flare["y"] += flare["vel_y"]
            flare["rotation"] += 12  # 회전
            # 목표 지점에 도달했는지 체크 (거리 기반으로 체크)
            dist_to_target = math.sqrt((flare["x"] - flare["target_x"])**2 + 
                                      (flare["y"] - flare["target_y"])**2)
            if dist_to_target < 10:  # 목표 지점에 충분히 가까워졌을 때
                flare["arrived"] = True
                flare["x"] = flare["target_x"]  # 정확한 위치에 고정
                flare["y"] = flare["target_y"]
                print(f"  ! 1.5  .")
        elif not flare["exploded"]:
            # 도착 후 타이머 증가
            flare["timer"] += 1
            # 1.5초(90프레임) 후 폭발
            if flare["timer"] >= 90:
                flare["exploded"] = True
                #  조명탄 폭발 사운드 재생
                try:
                    play_sound_with_volume(SOUND_FLASHBOMB)
                except:
                    pass  # 사운드 재생 실패 시 무시
                # 섬광 효과 생성 (0.15초 = 9프레임)
                import items
                # 코만도암 효과: 폭발 범위 10% 증가
                base_radius = 180  # 조명 반경
                if items.commando_arm_obtained:
                    flare_radius = int(base_radius * 1.1)  # 10% 증가
                    print(f"  !   : {flare_radius} (: {base_radius})")
                else:
                    flare_radius = base_radius
                
                flare_zone = {
                    "x": flare["x"],
                    "y": flare["y"],
                    "radius": flare_radius,  # 코만도암 효과 적용된 조명 반경
                    "duration": 9,  # 0.15초 섬광 (60fps * 0.15)
                    "intensity": 1.0,
                    "flash": True  # 섬광 효과 플래그
                }
                flare_zones.append(flare_zone)
                # 보스가 폭발 범위 내에 있는지 체크
                boss_distance = calculate_distance(get_center_pos(BOSS), (flare["x"], flare["y"]))
                if boss_distance <= flare_radius:  # 폭발 반경 내에 있으면
                    boss_confused_timer = THREE_SECONDS_FRAMES  # 3초간 보스 혼란
                    print(f"  !  3  !")
                else:
                    print(f"  ! : {boss_distance:.0f}")
                flares.remove(flare)
                # 효과음
                try:
                    play_wall_sound()
                except:
                    pass
                print(f"  !  5  !")
    # 조명 지대 업데이트 (섬광 효과)
    for zone in flare_zones[:]:
        zone["duration"] -= 1
        if zone.get("flash", False):
            # 섬광 효과: 빠르게 깜빡임 (0.15초 = 9프레임)
            if zone["duration"] > 6:  # 처음 0.05초는 최대 밝기
                zone["intensity"] = 1.0
            elif zone["duration"] > 3:  # 다음 0.05초는 어두워짐
                zone["intensity"] = 0.3
            else:  # 마지막 0.05초는 다시 밝아짐
                zone["intensity"] = 0.8
        else:
            zone["intensity"] = zone["duration"] / 9.0  # 일반 페이드 아웃
        if zone["duration"] <= 0:
            flare_zones.remove(zone)
    # 보스 혼란 타이머 감소
    if boss_confused_timer > 0:
        boss_confused_timer -= 1
    # 화염병 업데이트
    if molotovs and random.random() < 0.1:  # 10% 확률로 디버그 출력
        import pygame
        print(f"[DEBUG]   : {len(molotovs)}, : {pygame.time.get_ticks()}ms")
    for molotov in molotovs[:]:
        # 중력 적용 (gravity가 0이면 적용 안함)
        if molotov["gravity"] > 0:
            molotov["vel_y"] += molotov["gravity"]
        molotov["x"] += molotov["vel_x"]
        molotov["y"] += molotov["vel_y"]
        molotov["rotation"] += 10  # 회전
        # 목표 지점에 도달했는지 체크 (화염병이 목표 Y좌표에 도달하면 폭발)
        if molotov["y"] <= molotov["target_y"]:
            # 폭발 효과 - 불길이 번지는 효과
            import items
            # 코만도암 효과: 폭발 범위 10% 증가
            base_width = 150  # 화염 지대 너비
            base_height = 60  # 화염 지대 높이
            if items.commando_arm_obtained:
                fire_width = int(base_width * 1.1)  # 10% 증가
                fire_height = int(base_height * 1.1)  # 10% 증가
                print(f"  !   : {fire_width}x{fire_height} (: {base_width}x{base_height})")
            else:
                fire_width = base_width
                fire_height = base_height
            
            fire_zone = {
                "x": molotov["x"],
                "y": molotov["target_y"],  # 목표 지점에 생성
                "width": fire_width,  # 코만도암 효과 적용된 화염 지대 너비
                "height": fire_height,  # 코만도암 효과 적용된 화염 지대 높이
                "duration": 150,  # 2.5초 (60fps * 2.5)
                "flames": [],  # 개별 불꽃 파티클들
                "spread_timer": 0  # 불길 번짐 타이머
            }
            # 초기 불꽃 파티클 생성 (불길이 번지는 효과)
            for i in range(15):
                flame = {
                    "x": molotov["x"] + random.uniform(-30, 30),
                    "y": molotov["target_y"] + random.uniform(-10, 10),
                    "size": random.uniform(8, 20),
                    "lifetime": random.uniform(20, 40),
                    "color_phase": random.uniform(0, 1)
                }
                fire_zone["flames"].append(flame)
            fire_zones.append(fire_zone)
            molotovs.remove(molotov)
            # 폭발 효과음
            try:
                play_sound_with_volume(SOUND_FIREBOMB)  #  화염병 폭발 사운드 재생
                # 화염 지속 효과음 재생
                try:
                    flame_channel = pygame.mixer.find_channel()
                    if flame_channel:
                        flame_channel.set_volume(sfx_volume * 0.3)  # 화염 효과음은 작게
                        flame_channel.play(SOUND_FLAME, loops=-1)  # 루프 재생
                        fire_zone_sounds[id(fire_zone)] = flame_channel  # 채널 저장
                        print(f"화염 효과음 재생 시작 - Zone ID: {id(fire_zone)}")
                except Exception as e:
                    print(f"화염 효과음 재생 실패: {e}")
            except:
                pass
            print(f"  !    : X={fire_zone['x']:.1f}, Y={fire_zone['y']:.1f}")
    # 화염 지대 업데이트
    for fire_zone in fire_zones[:]:
        fire_zone["duration"] -= 1
        fire_zone["spread_timer"] += 1
        # push_timer가 없으면 초기화
        if "push_timer" not in fire_zone:
            fire_zone["push_timer"] = 0
        fire_zone["push_timer"] += 1

        # 화염 효과음을 1초 일찍 정지 (90프레임 = 1.5초 남음)
        if fire_zone["duration"] == 90:
            zone_id = id(fire_zone)
            if zone_id in fire_zone_sounds:
                try:
                    channel = fire_zone_sounds[zone_id]
                    if channel and channel.get_busy():
                        channel.stop()  # 1초 일찍 정지
                        print(f"화염 효과음 조기 정지 (1초 전) - Zone ID: {zone_id}")
                    del fire_zone_sounds[zone_id]  # 채널 정보 삭제
                except Exception as e:
                    print(f"화염 효과음 조기 정지 실패: {e}")
        # 불길 번짐 효과 - 지속적으로 새 불꽃 추가
        if fire_zone["spread_timer"] % 5 == 0 and len(fire_zone["flames"]) < 30:
            for i in range(3):
                flame = {
                    "x": fire_zone["x"] + random.uniform(-fire_zone["width"]/2, fire_zone["width"]/2),
                    "y": fire_zone["y"] + random.uniform(-fire_zone["height"]/2, fire_zone["height"]/2),
                    "size": random.uniform(10, 25),
                    "lifetime": random.uniform(15, 30),
                    "color_phase": random.uniform(0, 1)
                }
                fire_zone["flames"].append(flame)
        # 불꽃 파티클 업데이트
        for flame in fire_zone["flames"][:]:
            flame["lifetime"] -= 1
            flame["size"] *= 0.97  # 서서히 작아짐
            flame["y"] -= random.uniform(0.1, 0.5)  # 위로 살짝 올라감
            flame["x"] += random.uniform(-0.5, 0.5)  # 좌우로 흔들림
            if flame["lifetime"] <= 0 or flame["size"] < 2:
                fire_zone["flames"].remove(flame)
        # 보스가 화염 지대 안에 있는지 체크 (이동속도 감소용)
        boss_center_x = BOSS.centerx
        boss_center_y = BOSS.centery
        # 사각형 영역 체크 (불길이 번진 영역 + 패들 크기 고려) - 범위 50% 축소
        # X축 거리 체크 - 보스가 화염 지대 폭 안에 있는지
        x_in_range = abs(boss_center_x - fire_zone["x"]) < (fire_zone["width"]/4 + PADDLE_WIDTH/2)  # width/2 → width/4로 축소
        # Y축 거리 체크 - 보스와 화염 지대 사이 거리
        y_distance = abs(boss_center_y - fire_zone["y"])
        # 보스가 화염 지대 근처에 있으면 (Y축으로 60픽셀 이내)  # 120 → 60으로 축소
        y_in_range = y_distance < 60
        in_fire_zone = x_in_range and y_in_range
        #  화염 지대 내 보스 이동속도 50% 감소 효과 설정
        #  Stage 5 홍련은 화염병에 면역
        if in_fire_zone:
            if current_stage != 5:  # Stage 5 홍련은 화염병 속도 감소에 면역
                # 전역 변수로 보스 속도 감소 플래그 설정 (handle_boss에서 참조)
                fire_zone["boss_in_fire"] = True
                global boss_speed_reduction_active, boss_speed_reduction_factor
                boss_speed_reduction_active = True
                boss_speed_reduction_factor = 0.5  # 50% 감소 = 50%만 유지
            else:
                # Stage 5 홍련은 화염병 효과에 면역
                fire_zone["boss_in_fire"] = False
        else:
            # 보스가 화염 지대를 벗어났을 때
            fire_zone["boss_in_fire"] = False
        # 0.5초마다 보스를 화염 지대 밖으로 밀어내기 (스턴 없이 튕김)
        #  Stage 5 홍련은 화염병 넉백에도 면역
        if fire_zone["push_timer"] >= 30:  # 30프레임 = 0.5초 (9프레임에서 변경)
            fire_zone["push_timer"] = 0
            if in_fire_zone and current_stage != 5:  # Stage 5 홍련은 넉백에 면역
                # 스턴 없이 즉시 밀어내기 - 화염 지대 중심으로부터 반대 방향으로
                push_force = 60  # 매우 강한 밀어내기 힘 (35에서 60으로 대폭 증가)
                # 화염 지대 중심으로부터의 방향에 따라 밀어내기
                if boss_center_x < fire_zone["x"]:
                    # 보스가 화염 지대 왼쪽에 있으면 왼쪽으로 밀기
                    BOSS.x -= push_force
                else:
                    # 보스가 화염 지대 오른쪽에 있으면 오른쪽으로 밀기
                    BOSS.x += push_force
                # 화면 경계 체크
                BOSS.x = max(0, min(WIDTH - PADDLE_WIDTH, BOSS.x))
                #  체력형 보스 화염 데미지 적용 (1초마다 1회씩만 카운트, 3회마다 체력 감소)
                if current_stage in boss_health_stages and boss_fire_hit_timer <= 0:
                    boss_fire_hit_count += 1
                    boss_fire_hit_timer = FPS  # 1초 쿨다운 (60프레임)
                    if boss_fire_hit_count >= 3:
                        boss_current_health = max(0, boss_current_health - 1)  # 3회마다 체력 1 감소
                        boss_fire_hit_count = 0  # 카운터 리셋
                        print(f"  !   -1 (: {boss_current_health}/{boss_max_health})")
                    else:
                        print(f"   {boss_fire_hit_count}/3")
                # 시각적 피드백용 작은 흔들림 효과
                if random.random() < 0.3:  # 30% 확률로 작은 흔들림
                    BOSS.x += random.randint(-3, 3)
                    BOSS.x = max(0, min(WIDTH - PADDLE_WIDTH, BOSS.x))
        # 지속시간 종료 체크
        if fire_zone["duration"] <= 0:
            # 화염 효과음이 이미 정지되었을 수 있음 (0.5초 전에 정지됨)
            zone_id = id(fire_zone)
            if zone_id in fire_zone_sounds:
                try:
                    channel = fire_zone_sounds[zone_id]
                    if channel and channel.get_busy():
                        channel.stop()  # 아직 재생 중이면 정지
                        print(f"화염 효과음 정지 (종료 시점) - Zone ID: {zone_id}")
                    del fire_zone_sounds[zone_id]  # 채널 정보 삭제
                except Exception as e:
                    print(f"화염 효과음 정지 실패: {e}")
            # 이미 0.5초 전에 정지되었으므로 경고 메시지 제거
            fire_zones.remove(fire_zone)
    #  모든 화염 지대를 체크한 후, 보스가 어떤 화염 지대에도 없으면 속도 감소 효과 리셋
    if len(fire_zones) == 0 or not any(zone.get("boss_in_fire", False) for zone in fire_zones):
        boss_speed_reduction_active = False
        boss_speed_reduction_factor = 1.0  # 정상 속도로 복구
def activate_whip():
    global whip_active, whip_timer, whip_wave_phase, whip_original_ball_speed, whip_wave_particles
    print(f"[DEBUG] 상모돌리기 활성화 시작!")
    print(f"  - 현재 공 속도: X={ball_vel[0]:.2f}, Y={ball_vel[1]:.2f}")
    print(f"  - 현재 공 위치: X={BALL.centerx}, Y={BALL.centery}")
    print(f"  - 파워스매싱 상태: freeze={power_smashing_freeze_active}, parabola={power_smashing_parabola_active}")
    
    whip_active = True
    whip_timer = whip_duration
    whip_wave_phase = 0  # 사인 파형 초기화
    #  상모돌리기 발동 전 공 속도 저장 (Y축만 원래 속도 유지)
    whip_original_ball_speed = [0, ball_vel[1]]  # X축은 0으로 설정
    print(f"  !   : {whip_original_ball_speed}")
    
    #  파동 파티클 초기화 - 보스에서 플레이어를 향해 나아가는 파동
    whip_wave_particles = []
    
    # 효과음이 처음 발동될 때만 플레이
    whip_sound.play(loops=-1, maxtime=whip_duration * MILLISECONDS_PER_SECOND)  # 효과음이 지속되는 시간 설정
    
    #  X축 속도를 거의 0으로 설정 (일직선 아래로)
    ball_vel[0] = 0
    
    # Y축 속도 조정 (적당한 속도로 아래로)
    ball_vel[1] = abs(ball_vel[1]) * 0.75
    
    #  공이 무조건 플레이어 쪽(아래)으로 향하도록 Y 속도 보정
    if ball_vel[1] < 0:  # 공이 위쪽으로 가고 있다면
        ball_vel[1] = abs(ball_vel[1])  # 아래쪽으로 방향 전환
    # 최소 Y 속도 보장 (너무 수평으로 가지 않도록)
    if abs(ball_vel[1]) < 8:
        ball_vel[1] = 8
def handle_whip():
    global whip_active, whip_timer, whip_wave_phase, whip_hit_by_player, whip_wave_particles
    global whip_deactivation_active, whip_deactivation_timer, whip_rotation_speed
    global boss_stunned_after_whip, boss_stunned_after_whip_timer
    
    # 보스 통제불능 상태 처리 (회전 종료 후)
    if boss_stunned_after_whip:
        if boss_stunned_after_whip_timer > 0:
            boss_stunned_after_whip_timer -= 1
        else:
            boss_stunned_after_whip = False
    
    # 강제 해제 모션 처리
    if whip_deactivation_active:
        # 강제 해제 시작 시 사운드 즉시 중지
        if whip_deactivation_timer == whip_deactivation_duration:
            whip_sound.stop()
            
        if whip_deactivation_timer > 0:
            whip_deactivation_timer -= 1
            # 회전 속도를 점차 감소 (이징 효과 적용)
            progress = 1.0 - (whip_deactivation_timer / whip_deactivation_duration)
            # 이징 함수 (ease-out cubic)
            eased_progress = 1.0 - pow(1.0 - progress, 3)
            whip_rotation_speed = (1.0 - eased_progress) * 20.0  # 20에서 0으로 감소 (더 빠른 회전)
            
            # 남은 파동 파티클 업데이트 (점차 사라짐)
            for particle in whip_wave_particles[:]:
                particle['alpha'] -= 8  # 천천히 사라짐 (1.2초 동안)
                particle['radius'] += 3
                if particle['alpha'] <= 0:
                    whip_wave_particles.remove(particle)
        else:
            # 강제 해제 모션 완료 - 통제불능 상태 시작
            whip_deactivation_active = False
            whip_rotation_speed = 0.0
            whip_wave_particles.clear()
            
            # 0.5초 통제불능 상태 시작
            boss_stunned_after_whip = True
            boss_stunned_after_whip_timer = 30  # 0.5초
    
    if whip_active:
        if whip_timer > 0:
            whip_timer -= 1  # 타이머 감소 (효과음의 지속시간)
            whip_wave_phase += 0.3  # 사인 함수로 진폭 파형 진행
            # 진폭 계산 (사인 함수에 의해 -1에서 1 사이의 값을 가짐)
            wave = math.sin(whip_wave_phase) * 15  # 진폭을 15로 감소 (좌우 흔들림 최소화)
            # 볼륨 조정: -1에서 1 사이의 값을 0.0에서 1.0으로 변환
            volume = (math.sin(whip_wave_phase) + 1) / 2  # 0.0 ~ 1.0 범위로 변환
            whip_sound.set_volume(volume)  # 효과음 볼륨 설정
            # 공의 속도에 진폭 적용 (X축만 약간 물결치도록)
            # 파워스매싱이 활성화되어 있지 않을 때만 상모돌리기 효과 적용
            if not power_smashing_parabola_active and not power_smashing_freeze_active:
                old_vel_x = ball_vel[0]
                ball_vel[0] = wave  # 원래 속도 무시하고 파동만 적용 (중앙 기준)
                if whip_timer % 30 == 0:  # 0.5초마다 디버그 출력
                    print(f"[DEBUG] 상모돌리기 파동 적용: X속도 {old_vel_x:.2f} → {ball_vel[0]:.2f}")
            else:
                if whip_timer % 30 == 0:  # 0.5초마다 디버그 출력
                    print(f"[DEBUG] 상모돌리기 파동 스킵 (파워스매싱 활성화): freeze={power_smashing_freeze_active}, parabola={power_smashing_parabola_active}")
            
            #  파동 파티클 생성 (10프레임마다)
            if whip_timer % 10 == 0:
                # 보스 위치에서 플레이어 방향으로 파동 생성
                whip_wave_particles.append({
                    'x': BOSS.centerx,
                    'y': BOSS.centery,
                    'radius': 10,
                    'alpha': 255,
                    'speed': 8  # 파동이 퍼지는 속도
                })
            
            # 파동 파티클 업데이트
            for particle in whip_wave_particles[:]:
                # 파동이 플레이어 패들 방향으로 이동
                direction_to_player_y = PLAYER.centery - particle['y']
                direction_to_player_x = PLAYER.centerx - particle['x']
                distance = math.sqrt(direction_to_player_x**2 + direction_to_player_y**2)
                
                if distance > 0:
                    # 정규화된 방향 벡터
                    dir_x = direction_to_player_x / distance
                    dir_y = direction_to_player_y / distance
                    
                    # 파동 이동
                    particle['y'] += dir_y * particle['speed']
                    particle['x'] += dir_x * particle['speed'] * 0.3  # X축은 덜 움직임
                    particle['radius'] += 2  # 파동이 퍼짐
                    particle['alpha'] -= 8  # 점점 투명해짐
                    
                    # 알파값이 0이 되면 제거
                    if particle['alpha'] <= 0:
                        whip_wave_particles.remove(particle)
            
            #  플레이어가 반격한 경우와 아닌 경우를 구분
            if not whip_hit_by_player:
                # 플레이어가 아직 반격하지 않은 경우: 공은 아래쪽(플레이어 방향)으로
                if ball_vel[1] < 0:  # 만약 공이 위로 가려고 하면
                    ball_vel[1] = abs(whip_original_ball_speed[1]) if whip_original_ball_speed[1] != 0 else 10
                # 최소 Y 속도 보장 (너무 수평으로 가지 않도록)
                if abs(ball_vel[1]) < 5:
                    ball_vel[1] = 5
            else:
                # 플레이어가 반격한 경우: 공은 위쪽(보스 방향)으로 유지
                if ball_vel[1] > 0:  # 만약 공이 아래로 가려고 하면
                    ball_vel[1] = -abs(ball_vel[1])  # 위쪽으로 유지
                # 최소 Y 속도 보장
                if abs(ball_vel[1]) < 8:
                    ball_vel[1] = -8
        else:
            # 효과음 정지
            whip_active = False  # 효과음 종료
            whip_sound.stop()  # 타이머가 0이 되면 효과음 정지
            whip_wave_particles.clear()  # 파동 파티클도 제거
def activate_balloon():
    """풍선 스킬 활성화"""
    global balloon_active, balloon_timer, balloons, balloon_used_this_round
    balloon_active = True
    balloon_timer = -1  # -1은 라운드 끝까지 지속
    balloons = []  # 풍선 리스트 초기화
    balloon_used_this_round = True  # 이번 라운드에 사용됨 표시
    # 화면에 3-5개의 풍선 생성
    balloon_colors = [
        (255, 100, 100),  # 빨간색
        (100, 255, 100),  # 초록색
        (100, 100, 255),  # 파란색
        (255, 255, 100),  # 노란색
        (255, 100, 255),  # 마젠타
        (100, 255, 255),  # 시안
    ]
    for i in range(random.randint(3, 5)):
        x = random.randint(100, WIDTH-100)
        y = random.randint(100, HEIGHT-100)
        radius = random.randint(25, 35)
        color = random.choice(balloon_colors)
        # 랜덤한 방향과 속도 설정
        speed = random.uniform(1.5, 3.0)
        angle = random.uniform(0, 2 * math.pi)
        vx = math.cos(angle) * speed
        vy = math.sin(angle) * speed
        balloons.append({
            "x": x, 
            "y": y, 
            "radius": radius, 
            "color": color,
            "vx": vx,
            "vy": vy,
            "bounce": 0  # 튀는 애니메이션용
        })
    show_speech("풍선 놀이!", duration=60)
def handle_balloon():
    """풍선 스킬 처리"""
    global balloon_active, balloon_timer, balloons
    if balloon_active:
        # 타이머가 -1이면 라운드 끝까지 지속
        if balloon_timer > 0:
            balloon_timer -= 1
        elif balloon_timer == 0:
            # 풍선 스킬 종료
            # balloon_active = False  # Stage 1 보스 풍선파티 스킬 제거됨
            balloons.clear()
            return
        # 풍선 움직임과 벽 충돌 처리
        for balloon in balloons:
            # 풍선 위치 업데이트
            balloon["x"] += balloon["vx"]
            balloon["y"] += balloon["vy"]
            # 튀는 애니메이션
            balloon["bounce"] += 0.2
            balloon["y"] += int(math.sin(balloon["bounce"]) * 1)
            # 벽 충돌 감지 및 튕김 처리
            if balloon["x"] - balloon["radius"] <= 0:  # 왼쪽 벽
                balloon["x"] = balloon["radius"]
                balloon["vx"] = abs(balloon["vx"])  # 오른쪽으로 튕김
            elif balloon["x"] + balloon["radius"] >= WIDTH:  # 오른쪽 벽
                balloon["x"] = WIDTH - balloon["radius"]
                balloon["vx"] = -abs(balloon["vx"])  # 왼쪽으로 튕김
            if balloon["y"] - balloon["radius"] <= 0:  # 위쪽 벽
                balloon["y"] = balloon["radius"]
                balloon["vy"] = abs(balloon["vy"])  # 아래쪽으로 튕김
            elif balloon["y"] + balloon["radius"] >= HEIGHT:  # 아래쪽 벽
                balloon["y"] = HEIGHT - balloon["radius"]
                balloon["vy"] = -abs(balloon["vy"])  # 위쪽으로 튕김
def draw_balloons():
    """풍선 그리기"""
    if not balloon_active:
        return
    for balloon in balloons:
        x, y = balloon["x"], balloon["y"]
        radius = balloon["radius"]
        color = balloon["color"]
        # 풍선 몸체
        draw.circle(color, (int(x), int(y)), radius)
        # 풍선 테두리
        draw.circle(WHITE, (int(x), int(y)), radius, 2)
        # 풍선 줄 (위쪽으로)
        line_start = (int(x), int(y - radius))
        line_end = (int(x), int(y - radius - DEFAULT_RADIUS))
        draw.line((100, 100, 100), line_start, line_end, 2)
        # 풍선 하이라이트 (반짝이는 효과)
        highlight_x = int(x - radius // 3)
        highlight_y = int(y - radius // 3)
        draw.circle(WHITE, (highlight_x, highlight_y), radius // 4)
        # 풍선 움직임 방향 표시 (작은 화살표)
        arrow_length = 8
        arrow_x = int(x + balloon["vx"] * arrow_length)
        arrow_y = int(y + balloon["vy"] * arrow_length)
        draw.line(WHITE, (int(x), int(y)), (arrow_x, arrow_y), 2)
def check_balloon_collisions():
    """풍선과 공의 충돌 감지"""
    if not balloon_active or not balloons:
        return
    for balloon in balloons[:]:  # 복사본으로 순회
        # 풍선의 중심점과 공의 중심점 사이의 거리 계산
        dx = BALL.centerx - balloon["x"]
        dy = BALL.centery - balloon["y"]
        distance = math.sqrt(dx*dx + dy*dy)
        # 충돌 감지 (공 반지름 + 풍선 반지름)
        collision_distance = BALL_RADIUS + balloon["radius"]
        if distance <= collision_distance:
            print(f"  !  : 30")
            #  풍선 터지는 효과음 재생
            play_sound_with_volume(SOUND_BALLOON_BOOM)
            # 풍선 터뜨리기 효과
            effects_manager.create_balloon_pop_effect(balloon["x"], balloon["y"], balloon["color"])
            # 풍선 제거
            balloons.remove(balloon)
            # 현재 공의 각도 계산
            current_angle = math.atan2(ball_vel[1], ball_vel[0])
            # 30도(약 0.524 라디안) 랜덤하게 휘어지기
            angle_change = random.uniform(-0.524, 0.524)  # -30도 ~ +30도
            new_angle = current_angle + angle_change
            # 새로운 속도 계산 (현재 속도 유지)
            speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
            ball_vel[0] = math.cos(new_angle) * speed
            ball_vel[1] = math.sin(new_angle) * speed
            # 속도 정규화 제거 - 현재 속도 그대로 유지
            # 충돌 후 즉시 반환 (한 번에 하나의 풍선만 처리)
            return

def activate_spinning_top():
    """Stage 1 보스 팽이치기 스킬 활성화"""
    global spinning_top_active, spinning_top_timer, spinning_tops, spinning_top_used_this_round, whip_animation_timer
    
    spinning_top_active = True
    spinning_top_timer = spinning_top_duration
    spinning_top_used_this_round = True
    whip_animation_timer = 36  # 0.6초 채찍 애니메이션
    
    # 2개의 팽이 생성
    spinning_tops = []
    for i in range(2):
        offset_x = -30 if i == 0 else 30  # 좌우로 약간 떨어뜨려서 생성
        # 15% 확률로 황금 팽이 생성 (각각 독립적으로)
        is_golden = random.random() < 0.15
        spinning_tops.append({
            "x": BOSS.centerx + offset_x,
            "y": BOSS.centery + 40,  # 보스 아래쪽
            "vx": random.uniform(-0.5, 0.5),  # 초기 좌우 속도
            "vy": 0.4,  # 천천히 아래로
            "rotation": random.uniform(0, 360),  # 랜덤 시작 회전
            "rotation_speed": 20,  # 회전 속도
            "tilt": 0,  # 기울기
            "alpha": 255,  # 투명도
            "whip_phase": "preparing",  # 채찍 애니메이션 단계
            "zigzag_timer": i * 10,  # 서로 다른 지그재그 타이밍
            "speed_boost": 0,  # 충돌 시 속도 부스트
            "boost_timer": 0,  # 부스트 지속 시간
            "is_golden": is_golden,  # 황금 팽이 여부
            "star_spawned": False  # 별을 이미 생성했는지 여부
        })
        if is_golden:
            print(f"   ! ( {i+1})")
    
    # 채찍 효과음 재생
    whip_sound.play(maxtime=600)  # 0.6초 재생
    
    print(f"  ! 2  !")

def handle_spinning_top():
    """팽이 업데이트 처리"""
    global spinning_top_active, spinning_top_timer, spinning_tops, whip_animation_timer, top_collision_cooldown, golden_top_star_cooldown
    
    if not spinning_top_active or not spinning_tops:
        return
    
    # 충돌 쿨다운 감소
    if top_collision_cooldown > 0:
        top_collision_cooldown -= 1
    
    # 황금 팽이 별 생성 쿨다운 감소
    if golden_top_star_cooldown > 0:
        golden_top_star_cooldown -= 1
    
    if spinning_top_timer > 0:
        spinning_top_timer -= 1
        
        # 채찍 애니메이션 단계 (처음 0.6초)
        if whip_animation_timer > 0:
            whip_animation_timer -= 1
            if whip_animation_timer == 18:  # 0.3초 시점에 팽이 회전 시작
                for top in spinning_tops:
                    top["whip_phase"] = "spinning"
            return  # 채찍 애니메이션 중에는 팽이가 움직이지 않음
        
        # 팽이끼리 충돌 체크
        if len(spinning_tops) == 2 and top_collision_cooldown <= 0:
            top1, top2 = spinning_tops[0], spinning_tops[1]
            dx = top1["x"] - top2["x"]
            dy = top1["y"] - top2["y"]
            distance = math.sqrt(dx*dx + dy*dy)
            
            # 충돌 판정 (두 팽이가 가까워졌을 때)
            if distance < 40:  # 충돌 거리
                # 충돌 효과
                create_impact_effect(
                    (top1["x"] + top2["x"]) / 2,
                    (top1["y"] + top2["y"]) / 2,
                    [0, 0], is_player=False
                )
                
                # 효과음
                play_sound_with_volume(SOUND_PADDLE)
                
                # 400% 속도 부스트 (0.3초)
                angle = math.atan2(dy, dx)
                boost_speed = 8.0  # 400% 속도
                
                # 서로 반대 방향으로 튕겨나감
                top1["vx"] = math.cos(angle) * boost_speed
                top1["vy"] = math.sin(angle) * boost_speed * 0.3  # y축은 약하게
                top1["speed_boost"] = 4.0
                top1["boost_timer"] = 18  # 0.3초
                
                top2["vx"] = -math.cos(angle) * boost_speed
                top2["vy"] = -math.sin(angle) * boost_speed * 0.3
                top2["speed_boost"] = 4.0
                top2["boost_timer"] = 18
                
                # 충돌 쿨다운 설정
                top_collision_cooldown = 60  # 1초 쿨다운
                
                # 황금 팽이 충돌 시 트레이드 별 생성
                if golden_top_star_cooldown <= 0:
                    # 둘 중 하나라도 황금 팽이면 별 생성
                    if (top1.get("is_golden", False) and not top1.get("star_spawned", False)) or \
                       (top2.get("is_golden", False) and not top2.get("star_spawned", False)):
                        if trade_point_system:
                            # 충돌 지점의 중간 위치에 별 생성
                            star_x = (top1["x"] + top2["x"]) / 2
                            star_y = (top1["y"] + top2["y"]) / 2
                            trade_point_system.spawn_star(star_x, star_y, "golden_top")
                            
                            # 황금 팽이 표시 업데이트
                            if top1.get("is_golden", False):
                                top1["star_spawned"] = True
                            if top2.get("is_golden", False):
                                top2["star_spawned"] = True
                            
                            golden_top_star_cooldown = 30  # 0.5초 쿨타임
                            print(f"   !   !")
                
                print(f"  !   !")
        
        # 각 팽이 업데이트
        for i, top in enumerate(spinning_tops):
            if spinning_top_timer > 30:  # 쓰러지기 전까지
                # 부스트 타이머 처리
                if top["boost_timer"] > 0:
                    top["boost_timer"] -= 1
                    if top["boost_timer"] == 0:
                        # 원래 속도로 복귀
                        top["speed_boost"] = 0
                        top["vx"] *= 0.25  # 원래 속도로
                        top["vy"] = 0.6  # 원래 하강 속도
                
                # 회전
                top["rotation"] += top["rotation_speed"]
                
                # 지그재그 움직임 타이머 증가
                top["zigzag_timer"] += 1
                
                # 부스트 상태가 아닐 때만 일반 움직임
                if top["boost_timer"] <= 0:
                    # 예측불가능한 좌우 움직임
                    if top["zigzag_timer"] % random.randint(20, 40) == 0:
                        top["vx"] = random.uniform(-2.0, 2.0)
                    
                    # 부드러운 좌우 움직임을 위한 사인파
                    wave_x = math.sin(top["zigzag_timer"] * 0.1) * 0.5
                    top["x"] += top["vx"] + wave_x
                    top["y"] += top["vy"]
                else:
                    # 부스트 중일 때는 빠른 속도로 이동
                    top["x"] += top["vx"]
                    top["y"] += top["vy"]
                
                # 화면 경계 체크
                if top["x"] < 40 or top["x"] > WIDTH - 40:
                    top["vx"] *= -1  # 방향 반전
                    top["x"] = max(40, min(WIDTH - 40, top["x"]))
                
                # 천천히 하강 (부스트 상태가 아닐 때)
                if top["y"] < HEIGHT - 100 and top["boost_timer"] <= 0:
                    top["vy"] = 0.6  # 일정한 하강 속도
                
            elif spinning_top_timer > 0:  # 마지막 0.5초 - 쓰러지는 애니메이션
                # 회전 속도 감소
                top["rotation_speed"] *= 0.92
                
                # 기울어짐
                top["tilt"] = 90 * (1 - spinning_top_timer / 30)  # 0도에서 90도로
                
                # 페이드아웃
                top["alpha"] = int(255 * (spinning_top_timer / 30))
    else:
        # 스킬 종료
        spinning_top_active = False
        spinning_tops = []
        print("!")

def check_spinning_top_collision():
    """팽이와 공의 충돌 체크"""
    global ball_vel, golden_top_star_cooldown, trade_point_system
    
    if not spinning_top_active or not spinning_tops:
        return False
    
    # 채찍 애니메이션 중에도 충돌 체크를 해야 함 (삭제)
    
    # 각 팽이와 공의 충돌 체크
    for top in spinning_tops:
        # 쓰러진 상태에서는 충돌 없음
        if top.get("tilt", 0) > 45:
            continue
        
        # 팽이 히트박스 (원형)
        top_radius = 20  # 줄어든 크기에 맞춰 히트박스도 감소
        ball_center = (BALL.centerx, BALL.centery)
        top_center = (top["x"], top["y"])
        
        # 거리 계산
        dx = ball_center[0] - top_center[0]
        dy = ball_center[1] - top_center[1]
        distance = math.sqrt(dx*dx + dy*dy)
        
        # 충돌 판정
        if distance < top_radius + BALL_RADIUS:
            # 황금 팽이인 경우 트레이드 별 생성 (쿨타임 체크)
            if top.get("is_golden", False) and not top.get("star_spawned", False) and golden_top_star_cooldown <= 0:
                if trade_point_system:
                    # 팽이 위치에서 트레이드 별 생성
                    trade_point_system.spawn_star(top["x"], top["y"], "golden_top")
                    top["star_spawned"] = True  # 이 팽이에서 별 생성 완료
                    golden_top_star_cooldown = 30  # 0.5초 쿨타임 (60 FPS)
                    print(f"   !   !")
            
            # 무작위 방향으로 반사
            random_angle = random.uniform(0, 2 * math.pi)
            speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
            
            ball_vel[0] = math.cos(random_angle) * speed
            ball_vel[1] = math.sin(random_angle) * speed
            
            # 팽이에 튕김 효과 추가 (하프 대쉬 정도의 거리)
            # 충돌 반대 방향으로 밀려남
            if distance > 0:  # 0으로 나누기 방지
                push_angle = math.atan2(-dy, -dx)  # 공의 반대 방향
            else:
                push_angle = random.uniform(0, 2 * math.pi)
            
            # 하프 대쉬 거리 정도의 순간 가속 (약 30-40픽셀)
            push_speed = 12.0  # 순간적으로 빠른 속도
            top["vx"] = math.cos(push_angle) * push_speed
            top["vy"] = math.sin(push_angle) * push_speed * 0.5  # y축은 약간 약하게
            top["speed_boost"] = 3.0  # 속도 부스트 상태
            top["boost_timer"] = 12  # 0.2초간 지속 (짧게)
            
            # 충돌 효과 생성
            create_impact_effect(top_center[0], top_center[1], [0, 0], is_player=False)
            
            # 효과음 재생
            play_sound_with_volume(SOUND_PADDLE)
            
            print(f"  !  !  : {math.degrees(random_angle):.0f}°")
            return True
    
    return False

def draw_whip_waves(screen):
    """상모돌리기 파동 효과 그리기"""
    global whip_wave_particles
    
    if not whip_active or not whip_wave_particles:
        return
    
    # 파동 그리기
    for particle in whip_wave_particles:
        # 파동 색상 (보라색 계열)
        color = (180, 100, 255)
        alpha = particle['alpha']
        
        if alpha > 0:
            # 파동 원 그리기
            wave_surface = pygame.Surface((particle['radius'] * 2, particle['radius'] * 2), pygame.SRCALPHA)
            pygame.draw.circle(wave_surface, (*color, alpha // 2), 
                             (particle['radius'], particle['radius']), 
                             particle['radius'], 3)
            
            # 내부 원 (더 밝게)
            if particle['radius'] > 5:
                pygame.draw.circle(wave_surface, (*color, alpha), 
                                 (particle['radius'], particle['radius']), 
                                 max(1, particle['radius'] - 5), 2)
            
            screen.blit(wave_surface, 
                       (particle['x'] - particle['radius'], 
                        particle['y'] - particle['radius']))

def draw_spinning_top(screen):
    """팽이 그리기"""
    if not spinning_top_active or not spinning_tops:
        return
    
    # 채찍 애니메이션 그리기 (처음 0.6초)
    if whip_animation_timer > 0:
        # 각 팽이에 대한 채찍 그리기
        for top in spinning_tops:
            whip_start = (BOSS.centerx, BOSS.centery)
            whip_end = (top["x"], top["y"])
        
            # 채찍 곡선 효과
            control_x = (whip_start[0] + whip_end[0]) / 2 + math.sin(whip_animation_timer * 0.5) * 30
            control_y = (whip_start[1] + whip_end[1]) / 2 - 20
            
            # 채찍 그리기 (베지어 곡선처럼)
            for i in range(10):
                t = i / 10
                x1 = whip_start[0] * (1-t)**2 + control_x * 2*t*(1-t) + whip_end[0] * t**2
                y1 = whip_start[1] * (1-t)**2 + control_y * 2*t*(1-t) + whip_end[1] * t**2
                t2 = (i+1) / 10
                x2 = whip_start[0] * (1-t2)**2 + control_x * 2*t2*(1-t2) + whip_end[0] * t2**2
                y2 = whip_start[1] * (1-t2)**2 + control_y * 2*t2*(1-t2) + whip_end[1] * t2**2
                
                thickness = 3 - int(i * 0.3)  # 끝으로 갈수록 얇아짐
                pygame.draw.line(screen, (139, 69, 19), (x1, y1), (x2, y2), thickness)
    
    # 각 팽이 그리기
    for top in spinning_tops:
        # 황금 팽이 은은한 빛 효과
        if top.get("is_golden", False):
            # 시간에 따라 부드럽게 변하는 빛 효과
            glow_time = pygame.time.get_ticks() / 1000.0
            glow_intensity = (math.sin(glow_time * 2) + 1) * 0.3 + 0.4  # 0.4 ~ 1.0 사이에서 부드럽게 변화
            
            # 외부 광원 효과 (가장 큰 원)
            glow_surface = pygame.Surface((120, 120), pygame.SRCALPHA)
            glow_center = (60, 60)
            for i in range(20):
                alpha = int(15 * (1 - i/20) * glow_intensity)  # 매우 투명하게
                radius = 60 - i * 2
                if radius > 0 and alpha > 0:
                    pygame.draw.circle(glow_surface, (255, 215, 0, alpha), glow_center, radius)
            screen.blit(glow_surface, (top["x"] - 60, top["y"] - 60))
            
            # 중간 광원 효과
            mid_glow_surface = pygame.Surface((80, 80), pygame.SRCALPHA)
            mid_glow_center = (40, 40)
            for i in range(15):
                alpha = int(25 * (1 - i/15) * glow_intensity)  # 조금 더 진하게
                radius = 40 - i * 2
                if radius > 0 and alpha > 0:
                    pygame.draw.circle(mid_glow_surface, (255, 223, 0, alpha), mid_glow_center, radius)
            screen.blit(mid_glow_surface, (top["x"] - 40, top["y"] - 40))
            
            # 작은 반짝임 파티클 효과
            if random.random() < 0.3:  # 30% 확률로 반짝임 생성
                for _ in range(2):
                    particle_offset_x = random.randint(-30, 30)
                    particle_offset_y = random.randint(-30, 30)
                    particle_size = random.randint(1, 3)
                    particle_alpha = int(random.uniform(100, 200) * glow_intensity)
                    particle_color = (255, random.randint(200, 255), 0, particle_alpha)
                    
                    particle_surface = pygame.Surface((particle_size * 4, particle_size * 4), pygame.SRCALPHA)
                    pygame.draw.circle(particle_surface, particle_color, 
                                     (particle_size * 2, particle_size * 2), particle_size)
                    screen.blit(particle_surface, 
                              (top["x"] + particle_offset_x - particle_size * 2, 
                               top["y"] + particle_offset_y - particle_size * 2))
        
        # 팽이 표면 생성 (작은 크기)
        size = 50  # 팽이 크기
        top_surface = pygame.Surface((size, size), pygame.SRCALPHA)
        center = size // 2
        
        # 팽이 회전 변환 준비
        if top.get("tilt", 0) > 0:
            # 쓰러지는 효과를 위한 변형
            tilt_factor = top["tilt"] / 90
            height_scale = 1 - tilt_factor * 0.5
        else:
            height_scale = 1
    
        # 팽이 몸체 (둥근 모양)
        # 아래쪽 (나무 부분 - 원뿔 형태)
        wood_color = (160, 82, 45, top["alpha"])  # 나무색
        for i in range(10):
            y_offset = center + i * height_scale
            if y_offset < size - 3:
                width = 18 - i * 1.5
                if width > 0:
                    pygame.draw.circle(top_surface, wood_color, 
                                     (center, int(y_offset)), int(width))
        
        # 윗쪽 (회전하는 색상 패턴 - 둥근 원판)
        if top.get("is_golden", False):
            # 황금 팽이는 금색 계열로
            pattern_colors = [
                (255, 215, 0, top["alpha"]),    # 금색
                (255, 223, 0, top["alpha"]),    # 밝은 금색
                (218, 165, 32, top["alpha"]),   # 골든로드
            ]
        else:
            # 일반 팽이
            pattern_colors = [
                (100, 200, 200, top["alpha"]),  # 청록색
                (220, 100, 100, top["alpha"]),  # 빨간색
                (255, 200, 50, top["alpha"]),   # 노란색
            ]
        
        # 부스트 상태일 때 색상 변화
        if top.get("boost_timer", 0) > 0:
            # 부스트 중일 때 밝게 빛나는 효과
            boost_glow = int(128 * (top["boost_timer"] / 18))
            pattern_colors = [
                (min(255, c[0] + boost_glow), 
                 min(255, c[1] + boost_glow), 
                 min(255, c[2] + boost_glow), 
                 c[3]) for c in pattern_colors
            ]
        
        # 회전 효과를 위한 색상 블렌딩
        rotation_phase = (top["rotation"] / 10) % 3
        color_index = int(rotation_phase)
        next_color_index = (color_index + 1) % 3
        blend_factor = rotation_phase - color_index
        
        # 색상 보간
        current_color = pattern_colors[color_index]
        next_color = pattern_colors[next_color_index]
        blended_color = (
            int(current_color[0] * (1 - blend_factor) + next_color[0] * blend_factor),
            int(current_color[1] * (1 - blend_factor) + next_color[1] * blend_factor),
            int(current_color[2] * (1 - blend_factor) + next_color[2] * blend_factor),
            top["alpha"]
        )
        
        # 팽이 상단 원판 (둥근 모양)
        pygame.draw.circle(top_surface, blended_color, 
                          (center, int(center * height_scale - 5)), 18)
        pygame.draw.circle(top_surface, pattern_colors[(color_index + 2) % 3], 
                          (center, int(center * height_scale - 5)), 12)
        pygame.draw.circle(top_surface, pattern_colors[color_index], 
                          (center, int(center * height_scale - 5)), 6)
        
        # 팽이 축 (중심 막대)
        axis_color = (60, 30, 15, top["alpha"])  # 진한 나무색
        pygame.draw.line(top_surface, axis_color, 
                        (center, center * height_scale - 5), 
                        (center, center + 30 * height_scale), 3)
        
        # 화면에 그리기
        screen.blit(top_surface, 
                    (top["x"] - center, top["y"] - center))
        
        # 그림자 효과
        shadow_size = 30 + int(top.get("tilt", 0) / 4)
        shadow_surface = pygame.Surface((shadow_size, 12), pygame.SRCALPHA)
        shadow_alpha = top["alpha"] // 4
        if top.get("tilt", 0) > 0:  # 쓰러질 때 그림자 옅어짐
            shadow_alpha = shadow_alpha * (1 - top["tilt"] / 90)
        shadow_color = (0, 0, 0, int(shadow_alpha))
        pygame.draw.ellipse(shadow_surface, shadow_color, shadow_surface.get_rect())
        screen.blit(shadow_surface, 
                    (top["x"] - shadow_size // 2, top["y"] + 25))

def apply_red_overlay(surface, intensity):
    """
    투명하지 않은 픽셀에만 붉은 효과를 적용하는 함수 (최적화 버전)
    :param surface: pygame.Surface (RGBA)
    :param intensity: 0~255 사이의 붉은 정도
    """
    #  성능 최적화: 매우 큰 표면에서는 효과 비활성화
    if surface.get_width() > 300 or surface.get_height() > 300:
        return
    #  성능 최적화: 블렌딩 모드를 사용한 효율적인 색상 적용
    # 임시 표면을 생성하고 블렌딩 모드 사용
    overlay = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    # 빨간색 오버레이 색상 계산
    red_factor = min(255, 255 + int(intensity * 0.8))
    green_factor = max(0, 255 - int(intensity * 0.2))
    blue_factor = max(0, 255 - int(intensity * 0.2))
    overlay.fill((red_factor, green_factor, blue_factor, 90))  # 투명도 90
    #  블렌드 모드를 사용하여 효율적으로 색상 적용
    surface.blit(overlay, (0, 0), special_flags=pygame.BLEND_MULT)
def apply_blue_overlay(surface, intensity):
    """
    투명하지 않은 픽셀에만 파란색 효과를 적용하는 함수 (최적화 버전)
    :param surface: pygame.Surface (RGBA)
    :param intensity: 0~255 사이의 파란색 정도
    """
    #  성능 최적화: 매우 큰 표면에서는 효과 비활성화
    if surface.get_width() > 300 or surface.get_height() > 300:
        return
    #  성능 최적화: 블렌딩 모드를 사용한 효율적인 색상 적용
    # 임시 표면을 생성하고 블렌딩 모드 사용
    overlay = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    # 파란색 오버레이 색상 계산
    blue_factor = min(255, int(intensity * 0.5))
    red_factor = max(0, 255 - int(intensity * 0.3))
    green_factor = max(0, 255 - int(intensity * 0.1))
    overlay.fill((red_factor, green_factor, blue_factor, 80))  # 투명도 80
    #  블렌드 모드를 사용하여 효율적으로 색상 적용
    surface.blit(overlay, (0, 0), special_flags=pygame.BLEND_MULT)
def update_water_trail():
    """물자국 업데이트 함수"""
    global water_trail_positions, water_trail_timer
    # 디버프가 활성화되어 있을 때만 물자국 생성
    if player_slow_timer > 0:
        water_trail_timer += 1
        # 일정 간격으로 물자국 생성 (패들 바닥 중앙)
        if water_trail_timer >= 10:  # 10프레임마다 생성
            water_trail_positions.append((PLAYER.centerx, PLAYER.bottom + 5, 100))  # 초기 투명도 100
            water_trail_timer = 0
    # 물자국 점점 사라지게 하기 (시간이 지나면 투명도 감소)
    water_trail_positions = [(x, y, alpha - 3) for x, y, alpha in water_trail_positions if alpha > 0]
def draw_water_trail():
    """물자국 그리기 함수"""
    for x, y, alpha in water_trail_positions:
        if alpha > 0:
            # 물자국 크기와 색상
            size = random.randint(8, 15)
            color = (100, DEFAULT_ALPHA, 255, min(alpha, 100))  # 푸른 물빛, 최대 투명도 100
            # 물자국 그리기 (타원형)
            water_surface = pygame.Surface((size, size//2), pygame.SRCALPHA)
            pygame.draw.ellipse(water_surface, color, (0, 0, size, size//2))
            SCREEN.blit(water_surface, (x - size//2, y - size//4))
def draw_pachinko():
    """라스베가스 스타일 슬롯머신 그리기 함수"""
    if not pachinko_active:
        return
    # 라스베가스 스타일 배경 (화려한 그라데이션)
    for y in range(HEIGHT):
        ratio = y / HEIGHT
        r = int(20 + ratio * 30)
        g = int(10 + ratio * 20)
        b = int(40 + ratio * 50)
        draw.line((r, g, b), (0, y), (WIDTH, y))
    # 메인 컨테이너 (라스베가스 카지노 스타일)
    container_width = 500
    container_height = 600
    container_x = (WIDTH - container_width) // 2
    container_y = (HEIGHT - container_height) // 2 - 20
    # 컨테이너 글로우 효과 (골드)
    for i in range(10):
        glow_alpha = 60 - i * 6
        glow_surface = pygame.Surface((container_width + i*6, container_height + i*6), pygame.SRCALPHA)
        glow_surface.fill((255, 215, 0, glow_alpha))
        SCREEN.blit(glow_surface, (container_x - i*3, container_y - i*3))
    # 메인 컨테이너
    main_container = pygame.Rect(container_x, container_y, container_width, container_height)
    draw.rect((25, 15, 5), main_container)
    draw.rect((255, 215, 0), main_container, 4)
    # 내부 컨테이너
    inner_container = pygame.Rect(container_x + 20, container_y + 20, container_width - 40, container_height - 40)
    draw.rect((15, 10, 5), inner_container)
    draw.rect((255, 200, 0), inner_container, 3)
    # 제목 영역
    title_area = pygame.Rect(container_x + 30, container_y + 30, container_width - 60, 80)
    draw.rect((30, 20, 10), title_area)
    draw.rect((255, 215, 0), title_area, 3)
    # 제목 텍스트
    # 픽셀 폰트 타이틀
    title_font = FontStyle.title()  # 48pt 픽셀 폰트
    title_text = title_font.render(" 슬롯머신", True, (255, 215, 0))
    title_rect = title_text.get_rect(center=(container_x + container_width // 2, container_y + 70))
    SCREEN.blit(title_text, title_rect)
    # 슬롯 영역
    slot_area_x = container_x + 50
    slot_area_y = container_y + 150
    slot_area_width = container_width - 100
    slot_area_height = 300
    # 슬롯 배경
    slot_bg_rect = pygame.Rect(slot_area_x - 10, slot_area_y - 10, slot_area_width + 20, slot_area_height + 20)
    draw.rect((20, 15, 10), slot_bg_rect)
    draw.rect((255, 215, 0), slot_bg_rect, 3)
    # 3개 슬롯 그리기
    slot_width = (slot_area_width - 40) // 3
    slot_height = slot_area_height
    for reel_idx in range(3):
        reel_x = slot_area_x + reel_idx * (slot_width + 20)
        reel_y = slot_area_y
        # 릴 배경
        reel_rect = pygame.Rect(reel_x, reel_y, slot_width, slot_height)
        draw.rect((10, 8, 5), reel_rect)
        draw.rect((255, 200, 0), reel_rect, 2)
        # 릴 내부 아이템들 그리기 (세로 스크롤)
        item_size = 60
        visible_items = 5  # 한 번에 보이는 아이템 개수
        for i in range(visible_items):
            item_y = reel_y + i * (slot_height // visible_items) + 10
            item_y -= slot_positions[reel_idx]  # 스크롤 적용
            # 화면 안에 있는 아이템만 그리기
            if item_y + item_size > reel_y and item_y < reel_y + slot_height:
                # 아이템 인덱스 계산
                item_idx = (int(slot_positions[reel_idx] // 8) + i) % 30
                if item_idx < len(slot_reels[reel_idx]):
                    item = slot_reels[reel_idx][item_idx]
                    # 아이템 배경
                    item_rect = pygame.Rect(reel_x + 5, item_y, item_size, item_size)
                    draw.rect((25, 20, 15), item_rect)
                    draw.rect((255, 180, 0), item_rect, 2)
                    # 아이템 아이콘
                    if "icon" in item and item["icon"]:
                        icon = pygame.transform.scale(item["icon"], (50, 50))
                        icon_x = reel_x + 8
                        icon_y = item_y + 5
                        SCREEN.blit(icon, (icon_x, icon_y))
                    else:
                        # 아이콘이 없으면 원으로 그리기
                        center_x = reel_x + slot_width // 2
                        center_y = item_y + item_size // 2
                        draw.circle(item["color"], (center_x, center_y), 20)
        # 중앙 선택 표시 (골드 글로우)
        center_y = reel_y + slot_height // 2
        center_rect = pygame.Rect(reel_x - 5, center_y - 35, slot_width + 10, 70)
        # 글로우 효과
        for i in range(3):
            glow_alpha = 100 - i * 30
            glow_surface = pygame.Surface((slot_width + 10 + i*4, 70 + i*4), pygame.SRCALPHA)
            glow_surface.fill((255, 215, 0, glow_alpha))
            glow_x = reel_x - 5 - i*2
            glow_y = center_y - 35 - i*2
            SCREEN.blit(glow_surface, (glow_x, glow_y))
        draw.rect((255, 215, 0), center_rect, 4)
    # 결과 표시
    if pachinko_phase == 3 and slot_final_result:
        # 당첨 애니메이션
        global slot_win_animation
        slot_win_animation += 1
        # 결과 영역
        result_width = 400
        result_height = 120
        result_x = (WIDTH - result_width) // 2
        result_y = container_y + container_height + 20
        # 화려한 배경
        for i in range(result_height):
            ratio = i / result_height
            r = int(50 + ratio * 100)
            g = int(30 + ratio * 80)
            b = int(10 + ratio * 40)
            draw.line((r, g, b), (result_x, result_y + i), (result_x + result_width, result_y + i))
        draw.rect((255, 215, 0), (result_x, result_y, result_width, result_height), 4)
        # 당첨 아이템 표시
        if "icon" in slot_final_result and slot_final_result["icon"]:
            icon = pygame.transform.scale(slot_final_result["icon"], (80, 80))
            icon_x = result_x + 30
            icon_y = result_y + 20
            SCREEN.blit(icon, (icon_x, icon_y))
        # 당첨 메시지
        item_name = get_item_name_korean(slot_final_result['name'])
        # 픽셀 폰트
        result_font = FontStyle.subtitle()  # 32pt 픽셀 폰트
        result_text = f" JACKPOT! {item_name} "
        text = result_font.render(result_text, True, WHITE)
        text_rect = text.get_rect(center=(result_x + result_width // 2, result_y + 60))
        SCREEN.blit(text, text_rect)
        # 계속하기 안내
        continue_font = FontStyle.body()  # 24pt 픽셀 폰트
        continue_text = " SPACE를 눌러 계속... "
        text_small = continue_font.render(continue_text, True, WHITE)
        text_small_rect = text_small.get_rect(center=(result_x + result_width // 2, result_y + 100))
        SCREEN.blit(text_small, text_small_rect)
    elif pachinko_phase == 3 and not slot_final_result:
        # 꽝 결과
        result_width = 400
        result_height = 120
        result_x = (WIDTH - result_width) // 2
        result_y = container_y + container_height + 20
        # 어두운 배경
        draw.rect((30, 20, 10), (result_x, result_y, result_width, result_height))
        draw.rect((100, 100, 100), (result_x, result_y, result_width, result_height), 3)
        # 꽝 메시지
        # 픽셀 폰트
        result_font = FontStyle.subtitle()  # 36pt 픽셀 폰트
        result_text = " 아쉽게도 꽝입니다... "
        text = result_font.render(result_text, True, (200, 200, 200))
        text_rect = text.get_rect(center=(result_x + result_width // 2, result_y + 60))
        SCREEN.blit(text, text_rect)
        # 계속하기 안내
        continue_font = FontStyle.body()  # 24pt 픽셀 폰트
        continue_text = " SPACE를 눌러 계속... "
        text_small = continue_font.render(continue_text, True, (200, 200, 200))
        text_small_rect = text_small.get_rect(center=(result_x + result_width // 2, result_y + 100))
        SCREEN.blit(text_small, text_small_rect)
    # 안내 텍스트
    if pachinko_phase == 0:
        # 픽셀 폰트
        guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
        guide_text = " SPACE를 눌러 슬롯머신 시작! "
        text = guide_font.render(guide_text, True, (255, 215, 0))
        text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
        SCREEN.blit(text, text_rect)
    elif slot_spinning and not slot_slowdown_mode:
        # 픽셀 폰트
        guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
        guide_text = " SPACE를 눌러 첫 번째 릴 멈추기! "
        text = guide_font.render(guide_text, True, (255, 215, 0))
        text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
        SCREEN.blit(text, text_rect)
    elif slot_slowdown_mode:
        if slot_stop_order == 0:
            # 픽셀 폰트
            guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
            guide_text = " SPACE를 눌러 두 번째 릴 멈추기! "
            text = guide_font.render(guide_text, True, (255, 215, 0))
            text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
            SCREEN.blit(text, text_rect)
        elif slot_stop_order == 1:
            # 픽셀 폰트
            guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
            guide_text = " SPACE를 눌러 세 번째 릴 멈추기! "
            text = guide_font.render(guide_text, True, (255, 215, 0))
            text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
            SCREEN.blit(text, text_rect)
        else:
            # 픽셀 폰트
            guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
            guide_text = " 슬롯이 멈춥니다... "
            text = guide_font.render(guide_text, True, (255, 215, 0))
            text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
            SCREEN.blit(text, text_rect)
def update_red_intensity():
    global red_intensity
    if special_active:
        red_intensity = 0
        return
    # 게이지 비율 기반(0.0~1.0)
    ratio = special_gauge / special_gauge_max  #  수정
    target = ratio * 180  # 최대값 180
    # 서서히 변화
    if red_intensity < target:
        red_intensity += (target - red_intensity) * 0.1
    else:
        red_intensity -= (red_intensity - target) * 0.1
    red_intensity = min(180, max(0, red_intensity))
def update_gauge_animation():
    """게이지 부드러운 애니메이션 업데이트"""
    global displayed_gauge, gauge_animation_speed
    global displayed_boss_gauge, boss_gauge_animation_speed
    # 플레이어 게이지 애니메이션
    # 목표 게이지까지 부드럽게 이동
    if displayed_gauge < special_gauge:
        displayed_gauge += (special_gauge - displayed_gauge) * gauge_animation_speed
        # 정확히 목표값에 도달하도록 보정
        if displayed_gauge > special_gauge - 1:
            displayed_gauge = special_gauge
    elif displayed_gauge > special_gauge:
        displayed_gauge -= (displayed_gauge - special_gauge) * gauge_animation_speed
        # 정확히 목표값에 도달하도록 보정
        if displayed_gauge < special_gauge + 1:
            displayed_gauge = special_gauge
    # 보스 게이지 애니메이션 (스테이지 1, 3)
    if current_stage in [1, 3]:
        if displayed_boss_gauge < boss_special_gauge:
            displayed_boss_gauge += (boss_special_gauge - displayed_boss_gauge) * boss_gauge_animation_speed
            # 정확히 목표값에 도달하도록 보정
            if displayed_boss_gauge > boss_special_gauge - 1:
                displayed_boss_gauge = boss_special_gauge
        elif displayed_boss_gauge > boss_special_gauge:
            displayed_boss_gauge -= (displayed_boss_gauge - boss_special_gauge) * boss_gauge_animation_speed
            # 정확히 목표값에 도달하도록 보정
            if displayed_boss_gauge < boss_special_gauge + 1:
                displayed_boss_gauge = boss_special_gauge
def show_item_obtained_effect(item_data, item_x=None, item_y=None):
    """아이템 획득 효과 표시"""
    global item_obtained_effect
    # 아이템 타입 확인
    item_name = item_data.get("name", "")
    is_passive = item_name in ["speedboots", "speedgear", "battery", "slot_add", "revival", "master", "cooltime", "chargebag", "spikeboots", "dashgear", "bulkup", "sensor", "dashholder", "dowsing_pendulum", "commando_arm", "technical_vest", "fuel_pouch", "bluetooth_ring", "smartphone", "knee_pads", "gravitybelt"]
    # 시작 위치 (아이템이 있던 위치 또는 화면 중앙)
    if item_x is not None and item_y is not None:
        start_x = item_x
        start_y = item_y
    else:
        start_x = WIDTH // 2
        start_y = HEIGHT // 2 - LARGE_SIZE
    # 목표 위치 (모든 아이템이 플레이어 쪽으로 이동)
    target_x = 100  # 플레이어 쪽
    target_y = HEIGHT // 2
    # 풍선 터지는 효과 생성 (아이템 색상으로) - 모든 아이템에 적용
    item_color = item_data.get("color", WHITE)
    effects_manager.create_balloon_pop_effect(start_x, start_y, item_color)
    item_obtained_effect = {
        "icon": item_data.get("icon"),
        "name": item_data.get("name"),
        "timer": item_effect_duration,
        "alpha": 180,  # 더 투명하게 (255 -> 180)
        "type": "passive" if is_passive else "active",
        "x": start_x,
        "y": start_y,
        "target_x": target_x,
        "target_y": target_y,
        "start_x": start_x,
        "start_y": start_y
    }
def update_item_obtained_effect():
    """아이템 획득 효과 업데이트"""
    global item_obtained_effect
    if item_obtained_effect:
        item_obtained_effect["timer"] -= 1
        # 위치 업데이트 (모든 아이템이 플레이어 쪽으로 이동)
        progress = 1 - (item_obtained_effect["timer"] / item_effect_duration)
        # 부드러운 이동 (easing)
        ease_progress = 1 - (1 - progress) ** 2
        item_obtained_effect["x"] = item_obtained_effect["start_x"] + (item_obtained_effect["target_x"] - item_obtained_effect["start_x"]) * ease_progress
        item_obtained_effect["y"] = item_obtained_effect["start_y"] + (item_obtained_effect["target_y"] - item_obtained_effect["start_y"]) * ease_progress
        # 페이드 아웃 효과
        if item_obtained_effect["timer"] < 60:  # 마지막 1초
            fade_ratio = item_obtained_effect["timer"] / 60
            item_obtained_effect["alpha"] = int(255 * fade_ratio)
        if item_obtained_effect["timer"] <= 0:
            item_obtained_effect = None
def draw_item_obtained_effect():
    """아이템 획득 효과 그리기"""
    if not item_obtained_effect:
        return
    effect_x = int(item_obtained_effect["x"])
    effect_y = int(item_obtained_effect["y"])
    # 배경 원 (글로우 효과) - 크기 50% 감소
    glow_radius = 40  # 80 -> 40
    glow_surface = pygame.Surface((glow_radius * 2, glow_radius * 2), pygame.SRCALPHA)
    for i in range(glow_radius):
        alpha = int(30 * (1 - i / glow_radius) * (item_obtained_effect["alpha"] / 255))  # 더 투명하게
        pygame.draw.circle(glow_surface, (255, 255, 255, alpha), (glow_radius, glow_radius), glow_radius - i)
    SCREEN.blit(glow_surface, (effect_x - glow_radius, effect_y - glow_radius))
    # 메인 원형 배경 - 크기 50% 감소
    draw.circle((30, 40, 60, 150), (effect_x, effect_y), 30)  # 더 투명하게
    draw.circle((100, 150, 255, 150), (effect_x, effect_y), 30, 2)  # 더 투명하게
    # 아이템 아이콘 - 크기 50% 감소
    if item_obtained_effect["icon"]:
        icon = pygame.transform.scale(item_obtained_effect["icon"], (40, 40))  # 80 -> 40
        icon.set_alpha(item_obtained_effect["alpha"])
        icon_rect = icon.get_rect(center=(effect_x, effect_y))
        SCREEN.blit(icon, icon_rect.topleft)
    # 아이템 이름 (한글) - 크기 50% 감소
    item_name = get_item_name_korean(item_obtained_effect["name"])
    # 픽셀 폰트 (아이템 이름)
    name_font = FontStyle.item_name()  # 14pt 픽셀 폰트
    # 시너지 효과일 때 보라색으로 표시
    if item_obtained_effect["name"] == "gravitybelt":
        name_color = (128, 0, 128)  # 보라색
    else:
        name_color = WHITE  # 흰색
    name_text = name_font.render(item_name, True, name_color)
    name_text.set_alpha(item_obtained_effect["alpha"])
    name_rect = name_text.get_rect(center=(effect_x, effect_y + 50))  # 100 -> 50
    SCREEN.blit(name_text, name_rect)
    # 획득 메시지 - 크기 50% 감소
    obtain_font = FontStyle.item_obtain()  # 11pt 픽셀 폰트
    obtain_text = obtain_font.render("획득!", True, (255, 215, 0))
    obtain_text.set_alpha(item_obtained_effect["alpha"])
    obtain_rect = obtain_text.get_rect(center=(effect_x, effect_y + 65))  # 130 -> 65
    SCREEN.blit(obtain_text, obtain_rect)
def apply_white_glow(surface, intensity=60):
    """
    픽셀 단위로 반짝임 효과를 입히는 함수 (최적화 버전)
    :param surface: pygame.Surface (RGBA)
    :param intensity: 반짝임 밝기 (기본 60)
    """
    # 성능 최적화: 너무 큰 표면에서는 효과 비활성화 (크기 제한을 늘림)
    if surface.get_width() > 400 or surface.get_height() > 400:
        return  # 매우 큰 표면에서만 효과 비활성화
    # 성능 최적화: 픽셀 단위 대신 간격을 두고 처리
    step = 2  # 2픽셀마다 처리
    for x in range(0, surface.get_width(), step):
        for y in range(0, surface.get_height(), step):
            pixel = surface.get_at((x, y))
            if pixel.a != 0:  # 기체 부분에만 적용
                glow_r = min(255, max(0, pixel.r + intensity))
                glow_g = min(255, max(0, pixel.g + intensity))
                glow_b = min(255, max(0, pixel.b + intensity))
                try:
                    surface.set_at((x, y), pygame.Color(glow_r, glow_g, glow_b, pixel.a))
                except ValueError:
                    # 색상 값이 잘못된 경우 기본값 사용
                    surface.set_at((x, y), pygame.Color(255, 255, 255, pixel.a))
def draw_stage1_boss_gauge_bar():
    """스테이지 1 보스 필살기 게이지바 - 조선시대 궁궐 스타일"""
    global current_stage, boss_special_gauge, displayed_boss_gauge
    
    if current_stage != 1:
        return
    
    # 보스 필살기 게이지 표시
    max_gauge = 500  # 최대 게이지
    current_gauge = displayed_boss_gauge  # 부드러운 애니메이션을 위해 displayed_boss_gauge 사용
    
    # 게이지바 위치 - 플레이어 게이지바와 같은 크기 (14x100)
    bar_x = WIDTH - 45  # 살짝 왼쪽으로 이동
    bar_y = 50
    bar_width = 14  # 플레이어와 같은 크기
    bar_height = 100  # 플레이어와 같은 크기
    
    # 시간 기반 애니메이션
    time_offset = pygame.time.get_ticks() * 0.001
    
    # 한국 전통 태극문양 상단 (회전 애니메이션)
    taegeuk_x = bar_x + bar_width // 2
    taegeuk_y = bar_y - 20
    taegeuk_radius = 12
    
    # 태극 회전 각도
    rotation_angle = time_offset * 2  # 회전 속도
    
    # 태극 원형 배경 (검은 테두리)
    pygame.draw.circle(SCREEN, (40, 40, 40), (taegeuk_x, taegeuk_y), taegeuk_radius + 1)
    pygame.draw.circle(SCREEN, (240, 240, 240), (taegeuk_x, taegeuk_y), taegeuk_radius)
    
    # 태극 빨간색 반원 (양)
    red_points = []
    for angle in range(0, 181, 5):  # 상반부 반원
        rad = math.radians(angle + math.degrees(rotation_angle))
        x = taegeuk_x + (taegeuk_radius - 1) * math.cos(rad)
        y = taegeuk_y + (taegeuk_radius - 1) * math.sin(rad)
        red_points.append((x, y))
    
    # S자 곡선을 위한 중간점들 추가
    for angle in range(0, 181, 5):
        rad = math.radians(angle + math.degrees(rotation_angle))
        curve_radius = (taegeuk_radius - 1) * (0.3 + 0.4 * math.sin(math.radians(angle)))
        x = taegeuk_x - curve_radius * math.cos(rad)
        y = taegeuk_y + curve_radius * math.sin(rad)
        red_points.append((x, y))
    
    if len(red_points) > 2:
        pygame.draw.polygon(SCREEN, (220, 50, 50), red_points)
    
    # 태극 파란색 반원 (음)
    blue_points = []
    for angle in range(181, 361, 5):  # 하반부 반원
        rad = math.radians(angle + math.degrees(rotation_angle))
        x = taegeuk_x + (taegeuk_radius - 1) * math.cos(rad)
        y = taegeuk_y + (taegeuk_radius - 1) * math.sin(rad)
        blue_points.append((x, y))
    
    # S자 곡선을 위한 중간점들 추가
    for angle in range(181, 361, 5):
        rad = math.radians(angle + math.degrees(rotation_angle))
        curve_radius = (taegeuk_radius - 1) * (0.3 + 0.4 * math.sin(math.radians(angle)))
        x = taegeuk_x - curve_radius * math.cos(rad)
        y = taegeuk_y + curve_radius * math.sin(rad)
        blue_points.append((x, y))
    
    if len(blue_points) > 2:
        pygame.draw.polygon(SCREEN, (50, 50, 220), blue_points)
    
    # 작은 원점들 (양음 표시)
    small_circle_radius = 3
    yang_x = taegeuk_x + int(4 * math.cos(rotation_angle + math.pi/2))
    yang_y = taegeuk_y + int(4 * math.sin(rotation_angle + math.pi/2))
    yin_x = taegeuk_x - int(4 * math.cos(rotation_angle + math.pi/2))
    yin_y = taegeuk_y - int(4 * math.sin(rotation_angle + math.pi/2))
    
    pygame.draw.circle(SCREEN, (50, 50, 220), (yang_x, yang_y), small_circle_radius)  # 양에 음점
    pygame.draw.circle(SCREEN, (220, 50, 50), (yin_x, yin_y), small_circle_radius)   # 음에 양점
    
    # 태극 외곽 흰색 원형 테두리
    pygame.draw.circle(SCREEN, (255, 255, 255), (taegeuk_x, taegeuk_y), taegeuk_radius + 1, 2)
    
    # 조선 궁궐 기둥 스타일 프레임
    # 기둥 상단 (공포)
    pillar_top = [
        (bar_x - 4, bar_y - 2),
        (bar_x + bar_width + 4, bar_y - 2),
        (bar_x + bar_width + 6, bar_y + 5),
        (bar_x + bar_width + 2, bar_y + 8),
        (bar_x - 2, bar_y + 8),
        (bar_x - 6, bar_y + 5)
    ]
    pygame.draw.polygon(SCREEN, (160, 100, 40), pillar_top)
    pygame.draw.polygon(SCREEN, (100, 60, 20), pillar_top, 2)
    
    # 기둥 하단 (공포)
    pillar_bottom = [
        (bar_x - 2, bar_y + bar_height - 8),
        (bar_x + bar_width + 2, bar_y + bar_height - 8),
        (bar_x + bar_width + 6, bar_y + bar_height - 5),
        (bar_x + bar_width + 4, bar_y + bar_height + 2),
        (bar_x - 4, bar_y + bar_height + 2),
        (bar_x - 6, bar_y + bar_height - 5)
    ]
    pygame.draw.polygon(SCREEN, (160, 100, 40), pillar_bottom)
    pygame.draw.polygon(SCREEN, (100, 60, 20), pillar_bottom, 2)
    
    # 메인 기둥 몸체 (검은색 배경 - 깔끔한 단색)
    main_pillar = pygame.Rect(bar_x, bar_y, bar_width, bar_height)
    pygame.draw.rect(SCREEN, (25, 25, 25), main_pillar)  # 검은색 배경
    pygame.draw.rect(SCREEN, (140, 100, 60), main_pillar, 1)  # 황금 테두리
    
    # 필살기 게이지 채우기 (깔끔한 황금 스타일)
    if current_gauge > 0:
        gauge_ratio = min(current_gauge / max_gauge, 1.0)
        filled_height = int(bar_height * gauge_ratio)
        
        # 깔끔한 황금 색상 (단순화)
        if gauge_ratio > 0.8:
            gauge_color = (240, 200, 80)    # 밝은 황금
        elif gauge_ratio > 0.6:
            gauge_color = (220, 180, 60)    # 중간 황금
        elif gauge_ratio > 0.3:
            gauge_color = (200, 160, 40)    # 어두운 황금
        else:
            gauge_color = (180, 140, 30)    # 갈색 황금
        
        # 게이지 채우기 (아래에서 위로, 깔끔한 단색)
        gauge_start_y = bar_y + bar_height - filled_height
        gauge_rect = pygame.Rect(bar_x + 1, gauge_start_y, bar_width - 2, filled_height)
        pygame.draw.rect(SCREEN, gauge_color, gauge_rect)
        
        # 부드러운 상단 그라데이션 (3픽셀만)
        if filled_height > 3:
            for i in range(3):
                brightness = 1.0 + (0.3 * (2 - i) / 2)  # 위로 갈수록 밝게
                bright_color = tuple(min(255, int(c * brightness)) for c in gauge_color)
                pygame.draw.line(SCREEN, bright_color, 
                               (bar_x + 1, gauge_start_y + i), 
                               (bar_x + bar_width - 1, gauge_start_y + i))
        
        # 상단 하이라이트 (펄스 효과 최소화)
        if filled_height > 1:
            glow_intensity = abs(math.sin(time_offset * 2)) * 0.2 + 0.8
            highlight_color = tuple(min(255, int(c * glow_intensity)) for c in (255, 240, 150))
            pygame.draw.line(SCREEN, highlight_color, 
                           (bar_x + 1, gauge_start_y), 
                           (bar_x + bar_width - 1, gauge_start_y), 1)
        
        # 충전 중일 때 반짝임 효과 (부드러운 애니메이션)
        if boss_special_gauge > displayed_boss_gauge:  # 충전 중
            charge_intensity = min((boss_special_gauge - displayed_boss_gauge) / 50, 1.0)
            sparkle_count = int(charge_intensity * 2) + 1
            
            for i in range(sparkle_count):
                # 범위 검사를 통해 빈 범위 오류 방지
                min_y = gauge_start_y
                max_y = bar_y + bar_height - 2
                if max_y <= min_y:
                    sparkle_y = min_y  # 범위가 없을 때는 시작점 사용
                else:
                    sparkle_y = random.randint(min_y, max_y)
                
                # X축도 동일하게 범위 검사
                if bar_width <= 4:
                    sparkle_x = bar_x + bar_width // 2  # 너비가 너무 작을 때는 중앙 사용
                else:
                    sparkle_x = bar_x + random.randint(2, bar_width - 2)
                
                sparkle_alpha = int(charge_intensity * 150)
                pygame.draw.circle(SCREEN, (255, 255, 200), (sparkle_x, sparkle_y), 1)
        
        # 웨이브 애니메이션 효과 (상단)
        if filled_height > 5:
            wave_offset = math.sin(time_offset * 4) * 1.5
            wave_y = gauge_start_y + int(wave_offset)
            
            # 부드러운 웨이브 라인
            wave_brightness = abs(math.sin(time_offset * 3)) * 0.3 + 0.7
            wave_color = tuple(min(255, int(c * wave_brightness * 1.2)) for c in gauge_color)
            
            pygame.draw.line(SCREEN, wave_color, 
                           (bar_x + 1, wave_y), 
                           (bar_x + bar_width - 1, wave_y), 1)
    
    # 조선 전통 장식 요소
    # 좌우 단청 장식선
    for offset in [-3, bar_width + 3]:
        x_pos = bar_x + offset
        # 빨강 장식선
        pygame.draw.line(SCREEN, (180, 60, 40), 
                        (x_pos, bar_y + 10), (x_pos, bar_y + 30), 2)
        # 파랑 장식선  
        pygame.draw.line(SCREEN, (40, 80, 160), 
                        (x_pos, bar_y + 35), (x_pos, bar_y + 55), 2)
        # 초록 장식선
        pygame.draw.line(SCREEN, (60, 140, 80), 
                        (x_pos, bar_y + 60), (x_pos, bar_y + 80), 2)
    
    # 왕실 문양 하단 (봉황 깃털)
    feather_x = bar_x + bar_width // 2
    feather_y = bar_y + bar_height + 15
    feather_colors = [(220, 180, 50), (180, 60, 40), (40, 80, 160)]
    
    for i, color in enumerate(feather_colors):
        feather_offset = int(3 * math.sin(time_offset * 2 + i))
        pygame.draw.line(SCREEN, color, 
                        (feather_x + i * 2 - 2, feather_y), 
                        (feather_x + i * 2 - 2 + feather_offset, feather_y - 6), 2)
    
    
    # 게이지 수치 표시 (한문 느낌)
    gauge_font = FontStyle.tiny()
    gauge_text = f"{int(current_gauge)}/{max_gauge}"
    gauge_surface = gauge_font.render(gauge_text, True, (100, 60, 20))
    gauge_rect = gauge_surface.get_rect(centerx=bar_x + bar_width // 2, top=bar_y + bar_height + 25)
    SCREEN.blit(gauge_surface, gauge_rect)
    

def draw_player_gauge():
    """플레이어 게이지바를 오른쪽 하단에 세로로 표시 - 고급스러운 버전"""
    global special_gauge, special_gauge_max, special_ready, aipill_active
    global long_boost_active, long_boost_timer
    global wall_installing, wall_install_timer, wall_install_gauge_visible
    global rolling_charges, rolling_cooldown  #  대쉬 토큰 표시용
    global gauge_charge_animation_timer, gauge_charge_animation_amount  # 충전 애니메이션
    global selected_character_type  # 캐릭터 타입 확인용
    # 필살기 게이지바 위치와 크기 - 엣지있는 주인공 스타일
    gauge_x = WIDTH - 40  # 오른쪽에서 40px
    gauge_y = HEIGHT - 200  # 하단에서 200px 위 (살짝 조정)
    gauge_width = 14  # 더 얇게
    gauge_height = 100  # 높이
    time_now = pygame.time.get_ticks()
    # 동적으로 최대 게이지 가져오기 (악마의 주사위 효과 포함)
    current_max_gauge = get_max_gauge()
    
    #  전기 효과 강도 (게이지가 높을수록 강해짐)
    electric_intensity = displayed_gauge / current_max_gauge if displayed_gauge > 0 else 0
    # 캐릭터별 프레임 디자인
    if selected_character_type == "soldier":
        # 군사용 육각형 프레임 (더 견고하고 각진 디자인)
        hex_top = [
            (gauge_x + gauge_width // 2, gauge_y - 12),
            (gauge_x - 4, gauge_y - 2),
            (gauge_x - 4, gauge_y + 10),
            (gauge_x + gauge_width + 4, gauge_y + 10),
            (gauge_x + gauge_width + 4, gauge_y - 2),
        ]
        # 군복 올리브 그린 색상
        draw.polygon((60, 80, 40), hex_top)  # 어두운 올리브
        draw.polygon((120, 140, 80), hex_top, 3)  # 밝은 올리브 테두리
        
        # 군인 엠블럼 애니메이션 상단
        emblem_x = gauge_x + gauge_width // 2
        emblem_y = gauge_y - 35  # 좀 더 위에 배치
    else:
        # 기존 스매셔 프레임
        hex_top = [
            (gauge_x + gauge_width // 2, gauge_y - 10),
            (gauge_x - 3, gauge_y),
            (gauge_x - 3, gauge_y + 8),
            (gauge_x + gauge_width + 3, gauge_y + 8),
            (gauge_x + gauge_width + 3, gauge_y),
        ]
        draw.polygon((80, 90, 100), hex_top)
        draw.polygon((180, 190, 200), hex_top, 2)
        
        # 스매셔 엠블럼 애니메이션 상단
        emblem_x = gauge_x + gauge_width // 2
        emblem_y = gauge_y - 30
    
    # 애니메이션 효과
    pulse_scale = 1.0 + math.sin(time_now * 0.003) * 0.1  # 펄스 효과
    rotation_angle = time_now * 0.001  # 천천히 회전
    glow_intensity = abs(math.sin(time_now * 0.002))  # 빛나는 효과
    
    # 엠블럼 크기
    emblem_radius = 15
    
    # 캐릭터별 엠블럼 디자인
    if selected_character_type == "soldier":
        # === 군인 엠블럼 디자인 ===
        # 배경 원형 글로우 효과 (올리브 그린)
        for i in range(3):
            glow_radius = emblem_radius + (i + 1) * 2
            alpha = int(40 - i * 12) * glow_intensity  # 더 어두운 글로우
            glow_color = (80, 120, 60, alpha)  # 올리브 그린 글로우
            pygame.draw.circle(SCREEN, glow_color[:3], (emblem_x, emblem_y), int(glow_radius * pulse_scale))
        
        # 메인 엠블럼 원형 베이스 (군사용 어두운 올리브)
        base_color = (40, 60, 35)  # 어두운 올리브
        border_color = (120, 160, 90)  # 밝은 올리브
        pygame.draw.circle(SCREEN, base_color, (emblem_x, emblem_y), int(emblem_radius * pulse_scale))
        pygame.draw.circle(SCREEN, border_color, (emblem_x, emblem_y), int(emblem_radius * pulse_scale), 3)
        
        # 군인 심볼 - 별과 독수리 날개 모양
        # 중앙 별 그리기
        star_points = []
        star_radius = 8
        for i in range(10):
            angle = i * math.pi / 5 + rotation_angle
            radius = star_radius if i % 2 == 0 else star_radius * 0.4
            x = emblem_x + radius * math.cos(angle) * pulse_scale
            y = emblem_y + radius * math.sin(angle) * pulse_scale
            star_points.append((x, y))
        
        # 별 그리기 (금색)
        pygame.draw.polygon(SCREEN, (255, 215, 0), star_points)
        pygame.draw.polygon(SCREEN, (255, 255, 150), star_points, 1)
        
        # 독수리 날개 모양 (양쪽)
        wing_color = (200, 180, 100)
        wing_size = 6
        
        # 왼쪽 날개
        left_wing = [
            (emblem_x - wing_size, emblem_y - 3),
            (emblem_x - wing_size - 4, emblem_y - 1),
            (emblem_x - wing_size - 3, emblem_y + 2),
            (emblem_x - wing_size + 1, emblem_y + 1)
        ]
        pygame.draw.polygon(SCREEN, wing_color, left_wing)
        
        # 오른쪽 날개
        right_wing = [
            (emblem_x + wing_size, emblem_y - 3),
            (emblem_x + wing_size + 4, emblem_y - 1),
            (emblem_x + wing_size + 3, emblem_y + 2),
            (emblem_x + wing_size - 1, emblem_y + 1)
        ]
        pygame.draw.polygon(SCREEN, wing_color, right_wing)
        
        # 중앙 파워 코어 (군사용 금색)
        core_radius = 3
        core_color = (255, 255, 200)
        energy_color = (200, 180, 100)
        
        # 코어 글로우
        pygame.draw.circle(SCREEN, energy_color, (emblem_x, emblem_y), int(core_radius * 1.5 * pulse_scale))
        pygame.draw.circle(SCREEN, core_color, (emblem_x, emblem_y), int(core_radius * pulse_scale))
        
        # 전술적 레이더 스캔 효과 (게이지가 높을 때)
        if displayed_gauge > 250:
            scan_angle = (time_now * 0.005) % (math.pi * 2)
            scan_radius = emblem_radius + 5
            scan_end_x = emblem_x + math.cos(scan_angle) * scan_radius
            scan_end_y = emblem_y + math.sin(scan_angle) * scan_radius
            
            # 스캔 라인
            pygame.draw.line(SCREEN, (150, 200, 100), (emblem_x, emblem_y), (scan_end_x, scan_end_y), 2)
            
            # 스캔 포인트
            for i in range(3):
                point_angle = scan_angle + i * 0.3
                point_radius = emblem_radius - 2 + i * 2
                point_x = emblem_x + math.cos(point_angle) * point_radius
                point_y = emblem_y + math.sin(point_angle) * point_radius
                pygame.draw.circle(SCREEN, (100, 255, 100), (int(point_x), int(point_y)), 1)
                
    else:
        # === 기존 스매셔 엠블럼 디자인 ===
        # 배경 원형 글로우 효과
        for i in range(3):
            glow_radius = emblem_radius + (i + 1) * 2  # 3에서 2로 줄임
            alpha = int(60 - i * 20) * glow_intensity  # 알파값도 조정
            glow_color = (100, 150, 255, alpha)
            pygame.draw.circle(SCREEN, glow_color[:3], (emblem_x, emblem_y), int(glow_radius * pulse_scale))
        
        # 메인 엠블럼 원형 베이스
        base_color = (40, 50, 80)
        border_color = (150, 180, 255)
        pygame.draw.circle(SCREEN, base_color, (emblem_x, emblem_y), int(emblem_radius * pulse_scale))
        pygame.draw.circle(SCREEN, border_color, (emblem_x, emblem_y), int(emblem_radius * pulse_scale), 2)
        
        # 스매셔 심볼 - 번개 모양
        lightning_points = []
        
        # 번개 패턴 정의 (스매시의 파워를 상징)
        base_points = [
            (-8, -10),  # 상단 왼쪽
            (-2, -4),   # 중간 왼쪽
            (-5, 0),    # 중앙 왼쪽
            (2, -2),    # 중앙
            (-1, 2),    # 중앙 아래
            (5, 8),     # 하단 오른쪽
            (8, 10),    # 끝점
            (3, 6),     # 아래쪽 포인트
            (6, 2),     # 중간 오른쪽
            (0, 4),     # 중앙 복귀
            (3, 0),     # 상단 복귀
            (-3, 2),    # 왼쪽 복귀
            (0, -2),    # 중앙 상단
            (-8, -10)   # 시작점으로
        ]
        
        # 회전 및 스케일 적용
        for bx, by in base_points:
            # 회전 변환
            rot_x = bx * math.cos(rotation_angle) - by * math.sin(rotation_angle)
            rot_y = bx * math.sin(rotation_angle) + by * math.cos(rotation_angle)
            
            # 최종 위치
            final_x = emblem_x + rot_x * pulse_scale
            final_y = emblem_y + rot_y * pulse_scale
            lightning_points.append((final_x, final_y))
        
        # 번개 그리기
        if len(lightning_points) > 2:
            # 메인 번개 (밝은 파란색)
            pygame.draw.polygon(SCREEN, (100, 200, 255), lightning_points)
            # 번개 테두리 (더 밝은 색)
            pygame.draw.lines(SCREEN, (200, 230, 255), True, lightning_points, 2)
        
        # 중앙 파워 코어
        core_radius = 4
        core_color = (255, 255, 255)
        energy_color = (150, 200, 255)
        
        # 코어 글로우
        pygame.draw.circle(SCREEN, energy_color, (emblem_x, emblem_y), int(core_radius * 1.5 * pulse_scale))
        pygame.draw.circle(SCREEN, core_color, (emblem_x, emblem_y), int(core_radius * pulse_scale))
        
        # 전기 스파크 효과 (게이지가 높을 때)
        if displayed_gauge > 250:
            spark_count = min(3, int(displayed_gauge / 100))
            for i in range(spark_count):
                angle = (rotation_angle * 2 + i * 2.094) % (math.pi * 2)  # 120도 간격
                spark_length = emblem_radius + random.randint(5, 10)
                
                start_x = emblem_x + math.cos(angle) * core_radius
                start_y = emblem_y + math.sin(angle) * core_radius
                end_x = emblem_x + math.cos(angle) * spark_length
                end_y = emblem_y + math.sin(angle) * spark_length
                
                # 전기 번개 효과
                mid_x = (start_x + end_x) / 2 + random.randint(-3, 3)
                mid_y = (start_y + end_y) / 2 + random.randint(-3, 3)
                
                pygame.draw.lines(SCREEN, (200, 220, 255), False, 
                                [(start_x, start_y), (mid_x, mid_y), (end_x, end_y)], 1)
    
    
    # 캐릭터별 프레임 하단 디자인
    if selected_character_type == "soldier":
        # 군사용 육각형 프레임 하단 (더 견고한 디자인)
        hex_bottom = [
            (gauge_x - 4, gauge_y + gauge_height - 10),
            (gauge_x - 4, gauge_y + gauge_height + 2),
            (gauge_x + gauge_width // 2, gauge_y + gauge_height + 12),
            (gauge_x + gauge_width + 4, gauge_y + gauge_height + 2),
            (gauge_x + gauge_width + 4, gauge_y + gauge_height - 10),
        ]
        # 군복 올리브 그린 색상
        draw.polygon((60, 80, 40), hex_bottom)  # 어두운 올리브
        draw.polygon((120, 140, 80), hex_bottom, 3)  # 밝은 올리브 테두리
        
        # 군사용 메인 프레임 배경 (올리브 톤)
        main_rect = pygame.Rect(gauge_x - 2, gauge_y, gauge_width + 4, gauge_height)
        draw.rect((35, 45, 25), main_rect)  # 올리브 배경
        # 내부 홈 (음각 효과)
        inner_rect = pygame.Rect(gauge_x, gauge_y + 2, gauge_width, gauge_height - 4)
        draw.rect((25, 35, 15), inner_rect)  # 더 어두운 올리브
        
        # 군사용 사이드 라인 디테일 (전술적 느낌)
        for i in range(4):  # 4개 라인으로 더 세밀하게
            line_y = gauge_y + 15 + i * 22
            # 왼쪽 라인 (올리브 골드)
            draw.line((140, 120, 80), 
                            (gauge_x - 5, line_y), (gauge_x - 2, line_y), 1)
            # 오른쪽 라인
            draw.line((140, 120, 80), 
                            (gauge_x + gauge_width + 2, line_y), (gauge_x + gauge_width + 5, line_y), 1)
        
        # 센터 라인 (세로 중앙선) - 군사용 골드
        center_x = gauge_x + gauge_width // 2
        draw.line((100, 80, 50), 
                        (center_x, gauge_y + 5), (center_x, gauge_y + gauge_height - 5), 1)
    else:
        # 기존 스매셔 프레임 하단
        hex_bottom = [
            (gauge_x - 3, gauge_y + gauge_height - 8),
            (gauge_x - 3, gauge_y + gauge_height),
            (gauge_x + gauge_width // 2, gauge_y + gauge_height + 10),
            (gauge_x + gauge_width + 3, gauge_y + gauge_height),
            (gauge_x + gauge_width + 3, gauge_y + gauge_height - 8),
        ]
        draw.polygon((80, 90, 100), hex_bottom)
        draw.polygon((180, 190, 200), hex_bottom, 2)
        
        #  메인 프레임 배경
        # 어두운 메탈릭 배경
        main_rect = pygame.Rect(gauge_x - 2, gauge_y, gauge_width + 4, gauge_height)
        draw.rect((25, 28, 35), main_rect)
        # 내부 홈 (음각 효과)
        inner_rect = pygame.Rect(gauge_x, gauge_y + 2, gauge_width, gauge_height - 4)
        draw.rect((15, 18, 25), inner_rect)
        # 사이드 라인 디테일 (테크니컬한 느낌)
        for i in range(3):
            line_y = gauge_y + 20 + i * 30
            # 왼쪽 라인
            draw.line((100, 110, 120), 
                            (gauge_x - 5, line_y), (gauge_x - 2, line_y), 1)
            # 오른쪽 라인
            draw.line((100, 110, 120), 
                            (gauge_x + gauge_width + 2, line_y), (gauge_x + gauge_width + 5, line_y), 1)
        # 센터 라인 (세로 중앙선)
        center_x = gauge_x + gauge_width // 2
        draw.line((60, 65, 75), 
                        (center_x, gauge_y + 5), (center_x, gauge_y + gauge_height - 5), 1)
    #  게이지 채우기 - 전기/플라즈마 스타일
    if displayed_gauge > 0:
        fill_ratio = displayed_gauge / current_max_gauge
        fill_height = int((gauge_height - 4) * fill_ratio)
        
        # 무릎보호대 충전 애니메이션 효과
        charge_glow_intensity = 0
        if gauge_charge_animation_timer > 0:
            # 충전 애니메이션 강도 계산 (페이드 아웃 효과)
            charge_glow_intensity = gauge_charge_animation_timer / 30.0
            
        # 캐릭터별 게이지 색상
        if selected_character_type == "soldier":
            # === 군인 전용 게이지 색상 (올리브/골드 계열) ===
            if displayed_gauge < 150:
                # 레벨 1: 어두운 올리브
                base_color = (120, 140, 80)
                energy_color = (140, 160, 100)
            elif displayed_gauge < 250:
                # 레벨 2: 밝은 올리브
                base_color = (160, 180, 100)
                energy_color = (180, 200, 120)
            elif displayed_gauge < 350:
                # 레벨 3: 골드 올리브
                base_color = (200, 180, 100)
                energy_color = (220, 200, 120)
            else:
                # 레벨 4: 전술적 골드 (펄스 효과)
                pulse = abs(math.sin(time_now * 0.005))
                base_color = (
                    int(200 + pulse * 55),
                    int(180 + pulse * 35),
                    int(80 + pulse * 20)
                )
                energy_color = (255, 215, 100)
        else:
            # === 기존 스매셔 게이지 색상 (전기/플라즈마 계열) ===
            if displayed_gauge < 150:
                # 레벨 1: 차가운 청백색
                base_color = (180, 200, 220)
                energy_color = (200, 220, 240)
            elif displayed_gauge < 250:
                # 레벨 2: 전기 청색
                base_color = (100, 180, 255)
                energy_color = (150, 200, 255)
            elif displayed_gauge < 350:
                # 레벨 3: 강렬한 시안
                base_color = (0, 220, 255)
                energy_color = (100, 240, 255)
            else:
                # 레벨 4: 플라즈마 (청백색 + 보라)
                pulse = abs(math.sin(time_now * 0.005))
                base_color = (
                    int(100 + pulse * 100),
                    int(150 + pulse * 50),
                    255
                )
                energy_color = (200, 200, 255)
        
        # 무릎보호대 충전 효과가 활성화되면 황금빛 글로우 추가
        if charge_glow_intensity > 0:
            # 황금빛으로 색상 보정
            golden_blend = charge_glow_intensity
            base_color = (
                min(255, int(base_color[0] + golden_blend * 75)),
                min(255, int(base_color[1] + golden_blend * 55)),
                min(255, int(base_color[2] * (1 - golden_blend * 0.3)))
            )
            energy_color = (
                min(255, int(energy_color[0] + golden_blend * 75)),
                min(255, int(energy_color[1] + golden_blend * 55)),
                min(255, int(energy_color[2] * (1 - golden_blend * 0.3)))
            )
        # 메인 에너지 채우기
        fill_y = gauge_y + gauge_height - fill_height - 2
        # 3층 레이어 구조
        for layer in range(3):
            layer_alpha = 255 - layer * 50
            layer_width = gauge_width - 4 - layer * 2
            if layer_width > 0:
                for i in range(fill_height):
                    # 펄스 효과
                    pulse_offset = abs(math.sin((time_now * 0.003) + (i * 0.1)))
                    if layer == 0:  # 코어 레이어
                        color = energy_color
                    elif layer == 1:  # 미들 레이어
                        color = base_color
                    else:  # 외곽 레이어
                        color = tuple(int(c * 0.7) for c in base_color)
                    # 색상에 펄스 적용
                    final_color = tuple(min(255, int(c + pulse_offset * 20)) for c in color)
                    draw.line(final_color, (gauge_x + 2 + layer, fill_y + i),
                                   (gauge_x + 2 + layer_width, fill_y + i))
        #  전기 스파크 효과 (350 이상일 때)
        if displayed_gauge >= 350:
            spark_count = 2 if displayed_gauge < special_gauge_max else 4
            for _ in range(spark_count):
                spark_y = fill_y + random.randint(0, fill_height - 1)
                spark_x = gauge_x + random.randint(2, gauge_width - 2)
                spark_length = random.randint(3, 7)
                # 번개 모양
                points = []
                current_x = spark_x
                current_y = spark_y
                for i in range(3):
                    next_x = current_x + random.randint(-3, 3)
                    next_y = current_y + spark_length // 3
                    points.append((current_x, current_y))
                    points.append((next_x, next_y))
                    current_x = next_x
                    current_y = next_y
                if len(points) > 1:
                    pygame.draw.lines(SCREEN, WHITE, False, points, 1)
        # 상단 에너지 글로우
        if fill_ratio > 0.5:
            glow_height = 5
            for i in range(glow_height):
                alpha = 100 - i * 20
                glow_color = tuple(min(255, c + 50) for c in energy_color)
                draw.line(glow_color, (gauge_x + 2, fill_y - i),
                               (gauge_x + gauge_width - 2, fill_y - i))
    #  파워 준비 상태 표시 (전기 효과)
    if displayed_gauge >= 350:
        # 외곽 전기 아크
        if (time_now // 100) % 3 == 0:  # 간헐적으로
            # 상단 아크
            arc_start = (gauge_x - 5, gauge_y - 5)
            arc_end = (gauge_x + gauge_width + 5, gauge_y - 5)
            arc_mid = (gauge_x + gauge_width // 2, gauge_y - 8)
            pygame.draw.lines(SCREEN, (150, 200, 255), False, 
                            [arc_start, arc_mid, arc_end], 1)
            # 하단 아크
            arc_start = (gauge_x - 5, gauge_y + gauge_height + 5)
            arc_end = (gauge_x + gauge_width + 5, gauge_y + gauge_height + 5)
            arc_mid = (gauge_x + gauge_width // 2, gauge_y + gauge_height + 8)
            pygame.draw.lines(SCREEN, (150, 200, 255), False, 
                            [arc_start, arc_mid, arc_end], 1)
        # 코너 발광
        corner_glow = int(abs(math.sin(time_now * 0.004)) * 100 + 155)
        corner_color = (corner_glow, corner_glow, 255)
        # 상단 코너
        draw.circle(corner_color, (gauge_x, gauge_y), 3)
        draw.circle(corner_color, (gauge_x + gauge_width, gauge_y), 3)
        # 하단 코너
        draw.circle(corner_color, (gauge_x, gauge_y + gauge_height), 3)
        draw.circle(corner_color, (gauge_x + gauge_width, gauge_y + gauge_height), 3)
    # 무릎보호대 충전 애니메이션 - 황금빛 테두리 효과
    if gauge_charge_animation_timer > 0:
        # 충전 효과 강도
        glow_strength = gauge_charge_animation_timer / 30.0
        pulse_effect = abs(math.sin(pygame.time.get_ticks() * 0.01)) * glow_strength
        
        # 황금빛 외곽 글로우 (여러 겹)
        for i in range(3):
            glow_alpha = int((3 - i) * 85 * glow_strength)
            glow_size = 3 - i
            glow_color = (
                min(255, 255),
                min(255, 215 + i * 10),
                min(255, int(50 * (1 - pulse_effect)))
            )
            
            # 외곽 테두리 그리기
            glow_rect = pygame.Rect(
                gauge_x - glow_size,
                gauge_y - glow_size,
                gauge_width + glow_size * 2,
                gauge_height + glow_size * 2
            )
            pygame.draw.rect(SCREEN, glow_color, glow_rect, 2, border_radius=5)
        
        # 충전 파티클 효과
        if random.random() < 0.3 * glow_strength:
            # 랜덤 위치에 작은 별 파티클 생성
            particle_x = gauge_x + random.randint(-5, gauge_width + 5)
            particle_y = gauge_y + random.randint(-5, gauge_height + 5)
            particle_size = random.randint(2, 4)
            pygame.draw.circle(SCREEN, (255, 255, 100), (particle_x, particle_y), particle_size)
        
        # 상하단에 충전 빛줄기 효과
        if glow_strength > 0.3:
            # 상단 빛줄기
            beam_alpha = int(100 * glow_strength)
            beam_height = int(15 * pulse_effect)
            for i in range(beam_height):
                alpha_factor = 1 - (i / max(beam_height, 1))
                beam_color = (255, 230, int(100 * alpha_factor))
                pygame.draw.line(SCREEN, beam_color,
                               (gauge_x, gauge_y - i),
                               (gauge_x + gauge_width, gauge_y - i), 1)
            
            # 하단 빛줄기
            for i in range(beam_height):
                alpha_factor = 1 - (i / max(beam_height, 1))
                beam_color = (255, 230, int(100 * alpha_factor))
                pygame.draw.line(SCREEN, beam_color,
                               (gauge_x, gauge_y + gauge_height + i),
                               (gauge_x + gauge_width, gauge_y + gauge_height + i), 1)
    
    #  게이지바 수치 표시 (토큰볼 아래에 배치)
    gauge_text = f"{int(displayed_gauge)}/{current_max_gauge}"
    text_color = WHITE if displayed_gauge < current_max_gauge else (255, 255, 100)  # 만렙일 때는 노란색
    # 폰트 로드 (작은 크기)
    # 픽셀 폰트 (게이지)
    gauge_font = FontStyle.gauge()  # 16pt 픽셀 폰트
    gauge_text_surface = gauge_font.render(gauge_text, True, text_color)
    text_rect = gauge_text_surface.get_rect()
    # 토큰볼 아래쪽에 중앙 정렬 (token_y는 게이지바 아래 15px, 토큰볼 아래 추가로 15px)
    text_x = gauge_x + gauge_width // 2 - text_rect.width // 2
    text_y = gauge_y + gauge_height + 15 + 15  # 게이지바 아래 30픽셀 (토큰볼 아래)
    # 텍스트 배경 (반투명 검은 배경으로 가독성 향상)
    text_bg_rect = pygame.Rect(text_x - 2, text_y - 1, text_rect.width + 4, text_rect.height + 2)
    pygame.draw.rect(SCREEN, (0, 0, 0, 180), text_bg_rect, border_radius=3)
    draw.rect((100, 100, 100), text_bg_rect, 1, border_radius=3)
    # 텍스트 렌더링
    SCREEN.blit(gauge_text_surface, (text_x, text_y))
    #  통합 아이템 지속시간 게이지바 (거대화포션 & 레이저스코프)
    item_gauge_active = (long_boost_active and long_boost_timer > 0) or (predictor_active and predictor_timer > 0)
    if item_gauge_active:
        gauge_x = WIDTH - 75  # 필살기 게이지 왼쪽에 배치
        gauge_y = HEIGHT - 200  # 필살기 게이지와 같은 높이
        gauge_width = 14  # 플레이어 게이지와 동일한 폭
        gauge_height = 100
        #  육각형 프레임 상단 (플레이어 게이지와 동일)
        hex_top = [
            (gauge_x + gauge_width // 2, gauge_y - 10),
            (gauge_x - 3, gauge_y),
            (gauge_x - 3, gauge_y + 8),
            (gauge_x + gauge_width + 3, gauge_y + 8),
            (gauge_x + gauge_width + 3, gauge_y),
        ]
        draw.polygon((80, 90, 100), hex_top)
        draw.polygon((180, 190, 200), hex_top, 2)
        #  육각형 프레임 하단
        hex_bottom = [
            (gauge_x - 3, gauge_y + gauge_height - 8),
            (gauge_x - 3, gauge_y + gauge_height),
            (gauge_x + gauge_width // 2, gauge_y + gauge_height + 10),
            (gauge_x + gauge_width + 3, gauge_y + gauge_height),
            (gauge_x + gauge_width + 3, gauge_y + gauge_height - 8),
        ]
        draw.polygon((80, 90, 100), hex_bottom)
        draw.polygon((180, 190, 200), hex_bottom, 2)
        #  메인 프레임 배경
        main_rect = pygame.Rect(gauge_x - 2, gauge_y, gauge_width + 4, gauge_height)
        draw.rect((25, 28, 35), main_rect)
        # 내부 홈 (음각 효과) - 게이지 채우기 전에만 그리기
        inner_rect = pygame.Rect(gauge_x, gauge_y + 2, gauge_width, gauge_height - 4)
        draw.rect((15, 18, 25), inner_rect)
        # 사이드 라인 디테일
        for i in range(3):
            line_y = gauge_y + 20 + i * 30
            draw.line((100, 110, 120), 
                            (gauge_x - 5, line_y), (gauge_x - 2, line_y), 1)
            draw.line((100, 110, 120), 
                            (gauge_x + gauge_width + 2, line_y), (gauge_x + gauge_width + 5, line_y), 1)
        #  게이지 채우기 - 활성 아이템에 따라 색상 결정
        if long_boost_active and long_boost_timer > 0:
            # 거대화포션 활성화 시
            remaining_ratio = long_boost_timer / LONG_BOOST_DURATION
            fill_height = int((gauge_height - 4) * remaining_ratio)
            # 거대화포션 색상 (황금빛 -> 주황색)
            if remaining_ratio > 0.6:
                base_color = (255, 215, 0)  # 골드
                energy_color = (255, 235, 100)
            elif remaining_ratio > 0.3:
                base_color = (255, 165, 0)  # 주황색
                energy_color = (255, 195, 50)
            else:
                # 끝날 때 깜빡임 효과
                pulse = abs(math.sin(time_now * 0.01))
                base_color = (255, int(100 + pulse * 65), 0)
                energy_color = (255, int(150 + pulse * 50), 50)
        elif predictor_active and predictor_timer > 0:
            # 레이저스코프 활성화 시
            remaining_ratio = predictor_timer / 600  # 10초 기준 (60fps * 10초 = 600)
            fill_height = int((gauge_height - 4) * remaining_ratio)
            # 레이저스코프 색상 (빨간색 레이저)
            if remaining_ratio > 0.6:
                base_color = (255, 100, 100)  # 밝은 빨강
                energy_color = (255, 150, 150)
            elif remaining_ratio > 0.3:
                base_color = (255, 50, 50)  # 진한 빨강
                energy_color = (255, 100, 100)
            else:
                # 끝날 때 깜빡임
                pulse = abs(math.sin(time_now * 0.01))
                base_color = (255, int(50 * pulse), int(50 * pulse))
                energy_color = (255, int(100 * pulse), int(100 * pulse))
        else:
            fill_height = 0
        # 게이지 그리기 (fill_height가 0보다 클 때만)
        if fill_height > 0:
            fill_y = gauge_y + gauge_height - fill_height - 2
            # 3층 레이어 구조 (플레이어 게이지와 동일)
            for layer in range(3):
                layer_alpha = 255 - layer * 50
                layer_width = gauge_width - 4 - layer * 2
                if layer_width > 0:
                    layer_rect = pygame.Rect(gauge_x + 2 + layer, fill_y, layer_width, fill_height)
                    # 레이어별 색상 조정
                    layer_color = (
                        min(255, base_color[0] + layer * 20),
                        min(255, base_color[1] + layer * 20),
                        min(255, base_color[2] + layer * 20)
                    )
                    draw.rect(layer_color, layer_rect)
            #  특수 효과
            if long_boost_active and remaining_ratio > 0.1:
                # 거대화포션: 반짝임 효과
                if random.random() < 0.3:  # 30% 확률로 반짝임
                    sparkle_y = fill_y + random.randint(0, max(1, fill_height - 1))
                    sparkle_color = (255, 255, 200, 150)
                    draw.line(sparkle_color, (gauge_x + 2, sparkle_y),
                                   (gauge_x + gauge_width - 2, sparkle_y), 1)
            elif predictor_active and remaining_ratio > 0.1:
                # 레이저스코프: 스캔 효과 (정확한 범위 제한)
                if fill_height > 6:  # 최소 높이 확인 (여유 있게)
                    # 실제 채우기 영역 계산 (내부 홈 영역)
                    actual_fill_top = max(gauge_y + 2, fill_y)
                    actual_fill_bottom = min(gauge_y + gauge_height - 2, fill_y + fill_height)
                    actual_fill_height = actual_fill_bottom - actual_fill_top
                    if actual_fill_height > 0:
                        # 스캔 위치 계산 (실제 채우기 영역 내에서만 순환)
                        scan_offset = (time_now // 10) % actual_fill_height
                        scan_y = actual_fill_top + scan_offset
                        # 스캔 라인 그리기 (정확한 경계 체크)
                        if actual_fill_top <= scan_y < actual_fill_bottom:
                            scan_color = (255, 200, 200, 180)
                            draw.line(scan_color, (gauge_x + 2, scan_y),
                                           (gauge_x + gauge_width - 2, scan_y), 2)
    #  벽돌 설치 게이지 (플레이어 패들 바로 위)
    if wall_install_gauge_visible and wall_installing:
        # 설치 게이지 위치 (플레이어 패들 바로 위)
        install_gauge_x = PLAYER.centerx - 40  # 패들 중앙 기준 좌우 40픽셀
        install_gauge_y = PLAYER.top - 30  # 패들 위 30픽셀
        install_gauge_width = 80  # 패들 너비와 동일
        install_gauge_height = 8  # 얇은 게이지
        # 설치 게이지 배경 (회색)
        draw.rect((80, 80, 80), 
                         (install_gauge_x, install_gauge_y, install_gauge_width, install_gauge_height))
        # 설치 게이지 테두리 (갈색)
        draw.rect((139, 69, 19), 
                         (install_gauge_x, install_gauge_y, install_gauge_width, install_gauge_height), 2)
        # 설치 게이지 채우기 (남은 시간에 따라 증가)
        install_max_timer = HALF_SECOND_FRAMES  # 0.5초 (30프레임)
        progress_ratio = (install_max_timer - wall_install_timer) / install_max_timer
        fill_width = int(install_gauge_width * progress_ratio)
        # 갈색에서 노란색으로 그라데이션
        if progress_ratio < 0.5:
            gauge_color = (139, 69, 19)  # 갈색
        elif progress_ratio < 0.8:
            gauge_color = (160, 82, 45)  # 밝은 갈색
        else:
            gauge_color = YELLOW  # 노란색
        # 채워진 부분 그리기 (왼쪽에서부터)
        pygame.draw.rect(SCREEN, gauge_color, 
                         (install_gauge_x + 2, install_gauge_y + 2, fill_width - 4, install_gauge_height - 4))
        
        #  망치 아이콘 애니메이션 (게이지바 오른쪽)
        hammer_icon_x = install_gauge_x + install_gauge_width + 15  # 게이지바 오른쪽 15픽셀
        hammer_icon_y = install_gauge_y + install_gauge_height // 2  # 게이지바 중앙 높이
        hammer_circle_radius = 12  # 원형 배경 반지름
        
        # 원형 배경 (작업 중 표시)
        pygame.draw.circle(SCREEN, (50, 50, 50), (hammer_icon_x, hammer_icon_y), hammer_circle_radius)
        pygame.draw.circle(SCREEN, (100, 100, 100), (hammer_icon_x, hammer_icon_y), hammer_circle_radius, 2)
        
        # 망치 애니메이션 (뚝딱뚝딱) - 더 느리게
        hammer_frame = (HALF_SECOND_FRAMES - wall_install_timer) % 20  # 20프레임 주기로 천천히
        hammer_angle = 0
        
        if hammer_frame < 5:  # 올라가기 (5프레임)
            hammer_angle = -45  # 더 크게 들어올림
        elif hammer_frame < 8:  # 내려치기 (3프레임)
            hammer_angle = 35  # 더 크게 내려침
        elif hammer_frame >= 10 and hammer_frame < 15:  # 다시 올라가기 (5프레임)
            hammer_angle = -35  # 중간 정도로 들어올림
        elif hammer_frame >= 15 and hammer_frame < 18:  # 다시 내려치기 (3프레임)
            hammer_angle = 30  # 다시 내려침
        
        # 망치 그리기
        # 손잡이
        handle_length = 8
        handle_end_x = hammer_icon_x + int(handle_length * math.cos(math.radians(hammer_angle - 90)))
        handle_end_y = hammer_icon_y + int(handle_length * math.sin(math.radians(hammer_angle - 90)))
        pygame.draw.line(SCREEN, (101, 67, 33), (hammer_icon_x, hammer_icon_y), 
                        (handle_end_x, handle_end_y), 2)
        
        # 망치 머리
        head_width = 7
        head_height = 5
        
        # 망치 머리를 회전된 위치에 그리기
        head_points = []
        for dx, dy in [(-head_width//2, -head_height//2), (head_width//2, -head_height//2), 
                       (head_width//2, head_height//2), (-head_width//2, head_height//2)]:
            # 회전 변환
            rotated_x = dx * math.cos(math.radians(hammer_angle)) - dy * math.sin(math.radians(hammer_angle))
            rotated_y = dx * math.sin(math.radians(hammer_angle)) + dy * math.cos(math.radians(hammer_angle))
            head_points.append((handle_end_x + rotated_x, handle_end_y + rotated_y))
        
        pygame.draw.polygon(SCREEN, (160, 160, 160), head_points)  # 망치 머리 (밝은 회색)
        pygame.draw.polygon(SCREEN, (100, 100, 100), head_points, 1)  # 테두리
        
        # 타격 효과 (내려칠 때만)
        if hammer_frame == 7 or hammer_frame == 17:  # 망치가 내려친 직후
            # 작은 충격파 효과
            for i in range(2):
                spark_offset = random.randint(-3, 3)
                pygame.draw.circle(SCREEN, (255, 220, 100), 
                                 (hammer_icon_x + spark_offset, hammer_icon_y + 5), 2)
        
        # 못 그리기 (작업 대상)
        nail_x = hammer_icon_x
        nail_y = hammer_icon_y + 6
        pygame.draw.line(SCREEN, (80, 80, 80), (nail_x - 2, nail_y), (nail_x + 2, nail_y), 2)
        pygame.draw.circle(SCREEN, (100, 100, 100), (nail_x, nail_y - 1), 2)
    # 대쉬 전용 게이지바 제거 - 토큰볼을 게이지로 활용
    #  대쉬 토큰 표시 (플레이어 게이지바 하단에 고정)
    token_radius = 6  # 토큰 크기
    token_spacing = 16  # 토큰 간격
    #  정확한 최대 토큰 수 계산 (대쉬홀더 + 증폭 스킬)
    base_charges = 1  # 기본 1개
    holder_bonus = 1 if dashholder_obtained else 0  # 대쉬홀더 +1개
    amplification_bonus = academy.get_skill_bonus("dash_amplification")
    max_tokens = int(base_charges + holder_bonus + amplification_bonus)
    # 토큰 표시 시작 위치 (플레이어 게이지바 중앙 하단에 항상 고정)
    player_gauge_x = WIDTH - 40  # 플레이어 게이지바 X 위치
    player_gauge_width = 14  # 플레이어 게이지바 폭
    token_start_x = player_gauge_x + player_gauge_width // 2 - (max_tokens * token_spacing) // 2 + token_spacing // 2
    token_y = gauge_y + gauge_height + 15  # 게이지바 아래 15픽셀
    
    # 토큰 추가 강조 효과 확인
    token_emphasis = False
    emphasis_timer = 0
    if 'tutorial_bonus_token_message' in globals() and tutorial_bonus_token_message:
        current_time = pygame.time.get_ticks()
        elapsed_time = current_time - tutorial_bonus_token_timer
        if elapsed_time < 3000:  # 3초간 강조
            token_emphasis = True
            emphasis_timer = elapsed_time
    #  대쉬 토큰 표시 - 오른쪽부터 소진 / 왼쪽부터 충전
    # 최종 해결: token_states 리스트로 각 토큰 개별 추적
    global token_states
    if 'token_states' not in globals():
        token_states = [True] * rolling_charges + [False] * (max_tokens - rolling_charges)
    # 토큰 상태 배열 크기 조정
    if len(token_states) != max_tokens:
        # 현재 충전된 토큰 수 계산
        current_charged = sum(1 for state in token_states if state)
        # 새로운 토큰 상태 배열 생성
        if rolling_charges > 0:
            # 실제 충전된 토큰 수에 맞춰 재구성
            token_states = [True] * min(rolling_charges, max_tokens) + [False] * max(0, max_tokens - rolling_charges)
        else:
            # 토큰이 없으면 모두 비어있음
            token_states = [False] * max_tokens
    for i in range(max_tokens):
        token_x = token_start_x + i * token_spacing
        
        # 강조 효과 애니메이션 계산 (토큰 추가 시)
        emphasis_scale = 1.0
        emphasis_glow = 0
        if token_emphasis and i == 1:  # 두 번째 토큰(추가된 토큰) 강조
            # 펄스 효과
            pulse = abs(math.sin(emphasis_timer * 0.008))  # 0.008 = 약 125ms 주기
            emphasis_scale = 1.0 + pulse * 0.5  # 1.0 ~ 1.5 크기 변화
            emphasis_glow = int(pulse * 100)  # 글로우 강도
        
        # 토큰 상태에 따른 표시
        if i < len(token_states) and token_states[i]:
            # 사용 가능한 토큰 - 밝은 빨간색
            if token_emphasis and i == 1:
                # 강조된 토큰은 더 밝은 색상
                token_color = (255, 120 + emphasis_glow, 120 + emphasis_glow)
                glow_color = (255, 200 + int(emphasis_glow * 0.5), 200 + int(emphasis_glow * 0.5))
            else:
                token_color = (255, 80, 80)
                glow_color = (255, 150, 150)
            is_available = True
        else:
            # 사용된 토큰 - 충전 중
            # 충전 진행률 계산
            if rolling_charge_timer > 0:
                # 최대 충전 시간 계산
                dash_cooldown_bonus = academy.get_skill_bonus("dash_cooldown")
                cooldown_reduction = int(dash_cooldown_bonus * 60)
                if dashholder_obtained and rolling_charges >= 1:
                    max_charge_time = max(6, 60 - cooldown_reduction)  # 1초
                else:
                    max_charge_time = max(6, 90 - cooldown_reduction)  # 1.5초
                # 충전 진행률 (0.0 ~ 1.0)
                charge_progress = 1.0 - (rolling_charge_timer / max_charge_time)
                charge_progress = max(0, min(1, charge_progress))
                # 충전 중인 토큰 확인 (왼쪽부터 충전)
                # 왼쪽부터 첫 번째 비어있는 토큰만 충전
                is_charging = False
                for j in range(len(token_states)):
                    if not token_states[j]:  # 비어있는 토큰 발견
                        if j == i:  # 현재 토큰이 첫 번째 비어있는 토큰인 경우
                            is_charging = True
                        break  # 첫 번째 비어있는 토큰만 찾으면 종료
                if is_charging:
                    # 충전 중 - 빨간색이 차오르는 효과
                    base_empty_color = (60, 30, 30)  # 비어있는 상태
                    base_full_color = (255, 80, 80)  # 가득 찬 상태
                    # 충전 진행률에 따른 색상 보간
                    token_color = (
                        int(base_empty_color[0] + (base_full_color[0] - base_empty_color[0]) * charge_progress),
                        int(base_empty_color[1] + (base_full_color[1] - base_empty_color[1]) * charge_progress),
                        int(base_empty_color[2] + (base_full_color[2] - base_empty_color[2]) * charge_progress)
                    )
                    glow_color = (
                        int(100 + 155 * charge_progress),
                        int(50 + 100 * charge_progress),
                        int(50 + 100 * charge_progress)
                    )
                    is_available = False
                else:
                    # 아직 충전 차례가 아님 - 완전히 비어있는 상태 (어두운 회색)
                    token_color = (40, 20, 20)  # 더 어두운 색
                    glow_color = (50, 25, 25)  # 글로우도 최소화
                    is_available = False
                    charge_progress = 0  # 충전 진행률 0으로 설정
            else:
                # 충전 타이머 없음 - 완전히 비어있는 상태
                token_color = (60, 30, 30)
                glow_color = (80, 40, 40)
                is_available = False
        # 글로우 효과 (토큰이 사용 가능할 때만)
        if is_available:
            # 강조 효과가 있을 때 더 큰 글로우
            if token_emphasis and i == 1:
                # 다중 레이어 글로우 효과
                for layer in range(3):
                    glow_radius = int((token_radius * (3 + layer)) * emphasis_scale)
                    glow_alpha = int((80 - layer * 20) * (1 + emphasis_glow / 100))
                    glow_surface = pygame.Surface((glow_radius * 2, glow_radius * 2), pygame.SRCALPHA)
                    pygame.draw.circle(glow_surface, (*glow_color, min(255, glow_alpha)), 
                                     (glow_radius, glow_radius), glow_radius)
                    SCREEN.blit(glow_surface, (token_x - glow_radius, token_y - glow_radius))
            else:
                # 일반 글로우 효과
                glow_surface = pygame.Surface((token_radius * 4, token_radius * 4), pygame.SRCALPHA)
                pygame.draw.circle(glow_surface, (*glow_color, 60), 
                                 (token_radius * 2, token_radius * 2), token_radius * 2)
                SCREEN.blit(glow_surface, (token_x - token_radius * 2, token_y - token_radius * 2))
        # 충전 중인 토큰의 물 차오르는 효과
        if not is_available and 'charge_progress' in locals() and 'is_charging' in locals() and is_charging and charge_progress > 0:
            # 배경 원 (비어있는 상태)
            draw.circle((40, DEFAULT_RADIUS, DEFAULT_RADIUS), (int(token_x), int(token_y)), token_radius)
            # 아래에서 위로 차오르는 물 효과
            if charge_progress > 0:
                # 충전 높이 계산 (아래에서 위로)
                fill_height = int(token_radius * 2 * charge_progress)
                # 원형 내부에 차오르는 사각형 영역 클리핑
                # 원의 하단부터 시작
                fill_y_start = token_y + token_radius - fill_height
                # 물결 효과를 위한 sin 파동
                wave_offset = math.sin(pygame.time.get_ticks() * 0.005) * 1
                # 채워진 부분 그리기 (원 안에서만)
                for y in range(int(fill_y_start), int(token_y + token_radius)):
                    # 현재 y 위치에서 원의 너비 계산
                    dy = abs(y - token_y)
                    if dy <= token_radius:
                        # 원의 방정식: x² + y² = r²
                        dx = math.sqrt(token_radius * token_radius - dy * dy)
                        # 물결 효과 추가
                        wave = wave_offset * (1 - (y - fill_y_start) / fill_height) if fill_height > 0 else 0
                        # 그라데이션 색상 (아래가 더 진함)
                        gradient_ratio = (y - fill_y_start) / fill_height if fill_height > 0 else 0
                        color_r = int(token_color[0] * (0.7 + 0.3 * gradient_ratio))
                        color_g = int(token_color[1] * (0.7 + 0.3 * gradient_ratio))
                        color_b = int(token_color[2] * (0.7 + 0.3 * gradient_ratio))
                        # 수평선 그리기
                        draw.line((color_r, color_g, color_b),
                                       (token_x - dx + wave, y),
                                       (token_x + dx + wave, y))
            # 테두리
            draw.circle((100, 50, 50), (int(token_x), int(token_y)), token_radius, 1)
            # 충전 펄스 효과 (반짝임)
            if charge_progress > 0.5:
                pulse_alpha = int(50 + 50 * math.sin(pygame.time.get_ticks() * 0.01))
                pulse_surface = pygame.Surface((token_radius * 2 + 4, token_radius * 2 + 4), pygame.SRCALPHA)
                pygame.draw.circle(pulse_surface, (255, 100, 100, pulse_alpha),
                                 (token_radius + 2, token_radius + 2), token_radius + 1)
                SCREEN.blit(pulse_surface, (token_x - token_radius - 2, token_y - token_radius - 2))
        else:
            # 메인 토큰 원 (기본 상태 또는 강조 상태)
            actual_radius = int(token_radius * emphasis_scale) if (token_emphasis and i == 1) else token_radius
            draw.circle(token_color, (int(token_x), int(token_y)), actual_radius)
            
            # 토큰 테두리 (입체감)
            if token_emphasis and i == 1:
                # 강조된 토큰은 금색 테두리
                border_color = (255, 215, 0)  # 금색
                draw.circle(border_color, (int(token_x), int(token_y)), actual_radius, 2)
            else:
                border_color = (200, 200, 200) if is_available else (80, 80, 80)
                draw.circle(border_color, (int(token_x), int(token_y)), actual_radius, 1)
            
            # 하이라이트 효과 (작은 흰색 점)
            if is_available:
                if token_emphasis and i == 1:
                    # 강조된 토큰은 더 큰 하이라이트
                    highlight_x = token_x - actual_radius // 3
                    highlight_y = token_y - actual_radius // 3
                    draw.circle((255, 255, 200),  # 밝은 노란색 하이라이트
                                     (int(highlight_x), int(highlight_y)), int(actual_radius // 3))
                else:
                    highlight_x = token_x - token_radius // 3
                    highlight_y = token_y - token_radius // 3
                    draw.circle(WHITE, 
                                     (int(highlight_x), int(highlight_y)), token_radius // 4)
    
    # 위험감지센서 쿨타임 토큰 게이지볼 표시
    if danger_sensor_obtained:
        # 위험감지센서 토큰볼 위치 (기존 토큰볼 아래에 더 크게)
        sensor_token_radius = 8  # 기존 토큰(6)보다 큰 크기
        sensor_token_x = player_gauge_x + player_gauge_width // 2  # 플레이어 게이지바 중앙
        sensor_token_y = token_y + 20  # 기존 토큰볼 아래 20픽셀
        
        # 쿨타임 진행률 계산 (15초 쿨타임)
        sensor_cooldown = 15000  # 15초 in milliseconds
        current_time = pygame.time.get_ticks()
        
        # danger_sensor_last_activation_time 초기화
        if not hasattr(handle_ball, 'danger_sensor_last_activation_time'):
            handle_ball.danger_sensor_last_activation_time = 0
        
        time_since_activation = current_time - handle_ball.danger_sensor_last_activation_time
        sensor_charge_progress = min(1.0, time_since_activation / sensor_cooldown)
        
        # 보라색 테마 색상
        sensor_empty_color = (40, 20, 60)  # 어두운 보라색 (비어있는 상태)
        sensor_full_color = (150, 80, 200)  # 밝은 보라색 (충전된 상태)
        sensor_glow_color = (200, 150, 255)  # 연한 보라색 글로우
        
        # 쿨타임 완료 시 글로우 효과
        if sensor_charge_progress >= 1.0:
            # 펄스 글로우 효과
            pulse = abs(math.sin(pygame.time.get_ticks() * 0.003))
            for layer in range(3):
                glow_radius = sensor_token_radius * (2 + layer)
                glow_alpha = int((100 - layer * 25) * pulse)
                glow_surface = pygame.Surface((glow_radius * 2, glow_radius * 2), pygame.SRCALPHA)
                pygame.draw.circle(glow_surface, (*sensor_glow_color, min(255, glow_alpha)), 
                                 (glow_radius, glow_radius), glow_radius)
                SCREEN.blit(glow_surface, (sensor_token_x - glow_radius, sensor_token_y - glow_radius))
        
        # 물 차오르는 애니메이션 효과
        if sensor_charge_progress < 1.0:
            # 배경 원 (비어있는 상태)
            draw.circle(sensor_empty_color, (int(sensor_token_x), int(sensor_token_y)), sensor_token_radius)
            
            # 아래에서 위로 차오르는 물 효과
            if sensor_charge_progress > 0:
                fill_height = int(sensor_token_radius * 2 * sensor_charge_progress)
                fill_y_start = sensor_token_y + sensor_token_radius - fill_height
                
                # 물결 효과
                wave_offset = math.sin(pygame.time.get_ticks() * 0.004) * 1.5
                
                # 채워진 부분 그리기
                for y in range(int(fill_y_start), int(sensor_token_y + sensor_token_radius)):
                    dy = abs(y - sensor_token_y)
                    if dy <= sensor_token_radius:
                        dx = math.sqrt(sensor_token_radius * sensor_token_radius - dy * dy)
                        
                        # 물결 효과 추가
                        wave = wave_offset * (1 - (y - fill_y_start) / fill_height) if fill_height > 0 else 0
                        
                        # 그라데이션 색상
                        gradient_ratio = (y - fill_y_start) / fill_height if fill_height > 0 else 0
                        color_r = int(sensor_empty_color[0] + (sensor_full_color[0] - sensor_empty_color[0]) * sensor_charge_progress * (0.7 + 0.3 * gradient_ratio))
                        color_g = int(sensor_empty_color[1] + (sensor_full_color[1] - sensor_empty_color[1]) * sensor_charge_progress * (0.7 + 0.3 * gradient_ratio))
                        color_b = int(sensor_empty_color[2] + (sensor_full_color[2] - sensor_empty_color[2]) * sensor_charge_progress * (0.7 + 0.3 * gradient_ratio))
                        
                        # 수평선 그리기
                        draw.line((color_r, color_g, color_b),
                                       (sensor_token_x - dx + wave, y),
                                       (sensor_token_x + dx + wave, y))
            
            # 테두리
            draw.circle((100, 50, 150), (int(sensor_token_x), int(sensor_token_y)), sensor_token_radius, 1)
            
            # 충전 중 펄스 효과
            if sensor_charge_progress > 0.8:
                pulse_alpha = int(30 + 30 * math.sin(pygame.time.get_ticks() * 0.008))
                pulse_surface = pygame.Surface((sensor_token_radius * 2 + 6, sensor_token_radius * 2 + 6), pygame.SRCALPHA)
                pygame.draw.circle(pulse_surface, (150, 80, 200, pulse_alpha),
                                 (sensor_token_radius + 3, sensor_token_radius + 3), sensor_token_radius + 2)
                SCREEN.blit(pulse_surface, (sensor_token_x - sensor_token_radius - 3, sensor_token_y - sensor_token_radius - 3))
        else:
            # 충전 완료 상태 - 밝은 보라색
            draw.circle(sensor_full_color, (int(sensor_token_x), int(sensor_token_y)), sensor_token_radius)
            
            # 반짝이는 효과
            sparkle = abs(math.sin(pygame.time.get_ticks() * 0.005))
            if sparkle > 0.7:
                # 작은 별 효과
                star_points = []
                for i in range(8):
                    angle = i * math.pi / 4
                    if i % 2 == 0:
                        r = sensor_token_radius * 0.9
                    else:
                        r = sensor_token_radius * 0.5
                    x = sensor_token_x + r * math.cos(angle)
                    y = sensor_token_y + r * math.sin(angle)
                    star_points.append((x, y))
                pygame.draw.polygon(SCREEN, (255, 220, 255), star_points, 1)
            
            # 테두리 (더 밝은 보라색)
            draw.circle((220, 180, 255), (int(sensor_token_x), int(sensor_token_y)), sensor_token_radius, 2)
            
            # 하이라이트
            highlight_x = sensor_token_x - sensor_token_radius // 3
            highlight_y = sensor_token_y - sensor_token_radius // 3
            draw.circle((255, 240, 255), (int(highlight_x), int(highlight_y)), sensor_token_radius // 3)
        
        # 센서 아이콘 오버레이 (작은 센서 심볼)
        if sensor_charge_progress >= 1.0:
            # 센서 안테나 효과
            antenna_color = (255, 255, 255, 200)
            # 중앙 점
            draw.circle(WHITE, (int(sensor_token_x), int(sensor_token_y)), 2)
            # 전파 효과
            for i in range(3):
                wave_radius = 3 + i * 2
                wave_alpha = int(100 - i * 30)
                wave_surface = pygame.Surface((wave_radius * 2, wave_radius * 2), pygame.SRCALPHA)
                pygame.draw.circle(wave_surface, (255, 255, 255, wave_alpha), 
                                 (wave_radius, wave_radius), wave_radius, 1)
                SCREEN.blit(wave_surface, (sensor_token_x - wave_radius, sensor_token_y - wave_radius))
    
    #  악마의 주사위 게이지 표시
    from item_effects.devil_dice import is_devil_dice_active, get_devil_dice_duration_ratio
    if is_devil_dice_active():
        # 악마의 주사위 게이지 위치 (플레이어 게이지 왼쪽)
        devil_gauge_x = gauge_x - 35  # 플레이어 게이지 왼쪽에 위치
        devil_gauge_y = gauge_y
        devil_gauge_width = 12
        devil_gauge_height = 100
        
        # 게이지 지속시간 비율 가져오기
        duration_ratio = get_devil_dice_duration_ratio()
        
        # 악마의 뿔 장식 (게이지 상단)
        horn_color = (139, 0, 0)  # 다크레드
        # 왼쪽 뿔
        pygame.draw.lines(SCREEN, horn_color, False, [
            (devil_gauge_x - 5, devil_gauge_y - 5),
            (devil_gauge_x - 8, devil_gauge_y - 12),
            (devil_gauge_x - 10, devil_gauge_y - 15)
        ], 2)
        # 오른쪽 뿔
        pygame.draw.lines(SCREEN, horn_color, False, [
            (devil_gauge_x + devil_gauge_width + 5, devil_gauge_y - 5),
            (devil_gauge_x + devil_gauge_width + 8, devil_gauge_y - 12),
            (devil_gauge_x + devil_gauge_width + 10, devil_gauge_y - 15)
        ], 2)
        
        # 게이지 배경 (검은색)
        pygame.draw.rect(SCREEN, (20, 0, 0), 
                        (devil_gauge_x, devil_gauge_y, devil_gauge_width, devil_gauge_height))
        
        # 게이지 테두리 (악마의 붉은색)
        pygame.draw.rect(SCREEN, (200, 0, 0), 
                        (devil_gauge_x - 2, devil_gauge_y - 2, devil_gauge_width + 4, devil_gauge_height + 4), 2)
        
        # 게이지 채우기 (위에서 아래로 감소)
        if duration_ratio > 0:
            fill_height = int(devil_gauge_height * duration_ratio)
            fill_y = devil_gauge_y + (devil_gauge_height - fill_height)
            
            # 악마의 불꽃 그라데이션 효과
            for i in range(fill_height):
                intensity = 1.0 - (i / devil_gauge_height)
                flame_color = (
                    int(255 * intensity),
                    int(50 * intensity), 
                    int(50 * intensity)
                )
                pygame.draw.line(SCREEN, flame_color,
                               (devil_gauge_x, fill_y + i),
                               (devil_gauge_x + devil_gauge_width, fill_y + i))
        
        # 악마의 눈 효과 (게이지 중앙)
        eye_y = devil_gauge_y + devil_gauge_height // 2
        eye_glow = int(abs(math.sin(time_now * 0.005)) * 155 + 100)
        # 왼쪽 눈
        pygame.draw.circle(SCREEN, (eye_glow, 0, 0), 
                         (devil_gauge_x - 3, eye_y), 2)
        # 오른쪽 눈
        pygame.draw.circle(SCREEN, (eye_glow, 0, 0), 
                         (devil_gauge_x + devil_gauge_width + 3, eye_y), 2)
        
        # 펄스 효과 (게이지 주변)
        if duration_ratio > 0.3:  # 30% 이상일 때만
            pulse_alpha = int(30 + 30 * math.sin(time_now * 0.008))
            pulse_rect = pygame.Rect(devil_gauge_x - 4, devil_gauge_y - 4, 
                                    devil_gauge_width + 8, devil_gauge_height + 8)
            pulse_surface = pygame.Surface((devil_gauge_width + 8, devil_gauge_height + 8), pygame.SRCALPHA)
            pygame.draw.rect(pulse_surface, (139, 0, 0, pulse_alpha), 
                           (0, 0, devil_gauge_width + 8, devil_gauge_height + 8), 3)
            SCREEN.blit(pulse_surface, (devil_gauge_x - 4, devil_gauge_y - 4))
        
        # 게이지 아래 "666" 표시 (악마의 숫자)
        devil_font = FontStyle.gauge()  # 14pt 폰트
        devil_text = "666" if duration_ratio > 0.5 else f"{int(duration_ratio * 100)}%"
        text_color = (255, 50, 50) if duration_ratio > 0.5 else (150, 50, 50)
        devil_text_surface = devil_font.render(devil_text, True, text_color)
        text_rect = devil_text_surface.get_rect()
        text_x = devil_gauge_x + devil_gauge_width // 2 - text_rect.width // 2
        text_y = devil_gauge_y + devil_gauge_height + 5
        SCREEN.blit(devil_text_surface, (text_x, text_y))
    
    # 패시브 아이템 아이콘 표시 - 폐기된 기능 (우측 하단 슬롯 제거)
    # passive_icon_y = token_y + 25  # 토큰 아래 25픽셀
    # passive_icon_size = 24  # 아이콘 크기
    # passive_icon_spacing = 30  # 아이콘 간격
    # passive_icons = []
    # 
    # # 획득한 패시브 아이템 확인
    # if bulkup_obtained:
    #     passive_icons.append(bulkup_icon)
    # if sensor_obtained:
    #     passive_icons.append(sensor_icon)
    # if dashholder_obtained:
    #     passive_icons.append(dashholder_icon)
    # if items.dowsing_pendulum_obtained:
    #     # 다우징펜들럼도 패시브 아이템이지만 슬롯에 표시하지 않음
    #     pass
    # 
    # # 아이콘 표시
    # if passive_icons:
    #     # 중앙 정렬을 위한 시작 위치 계산
    #     total_width = len(passive_icons) * passive_icon_spacing - (passive_icon_spacing - passive_icon_size)
    #     icon_start_x = player_gauge_x + player_gauge_width // 2 - total_width // 2
    #     
    #     for i, icon in enumerate(passive_icons):
    #         icon_x = icon_start_x + i * passive_icon_spacing
    #         if icon:
    #             SCREEN.blit(icon, (icon_x, passive_icon_y))
def draw_crocodile_boss(boss_x=0, boss_y=0, ball_x=0, ball_y=0):
    """ 스테이지 2 악어장군 - 공을 추적하는 눈동자"""
    # 기본 악어 이미지 생성
    crocodile_surface = pygame.Surface((BOSS_IMG_WIDTH, BOSS_IMG_HEIGHT), pygame.SRCALPHA)
    # 기존 이미지가 있으면 사용, 없으면 기본 그래픽 생성
    try:
        crocodile_surface.blit(BOSS_IMG_STAGE2, (0, 0))
    except:
        # 기본 악어 몸체 (녹색)
        pygame.draw.rect(crocodile_surface, (34, 139, 34), (10, DEFAULT_RADIUS, BOSS_IMG_WIDTH-DEFAULT_RADIUS, BOSS_IMG_HEIGHT-40), border_radius=15)
        pygame.draw.rect(crocodile_surface, (0, 100, 0), (10, DEFAULT_RADIUS, BOSS_IMG_WIDTH-DEFAULT_RADIUS, BOSS_IMG_HEIGHT-40), 3, border_radius=15)
    # 눈 위치 설정 (악어 이미지의 대략적인 눈 위치)
    left_eye_x = BOSS_IMG_WIDTH // 2 - 30
    right_eye_x = BOSS_IMG_WIDTH // 2 + 30
    eye_y = BOSS_IMG_HEIGHT // 2 - 5
    # 눈 크기 (더 크게 조정)
    eye_radius = 18
    pupil_radius = 8
    # 공과 눈의 각도 계산
    def calculate_pupil_position(eye_x, eye_y):
        # 보스 패들의 실제 화면상 위치 계산
        actual_eye_x = boss_x + eye_x - BOSS_IMG_WIDTH // 2
        actual_eye_y = boss_y + eye_y - BOSS_IMG_HEIGHT // 2
        # 공과의 각도 계산
        dx = ball_x - actual_eye_x
        dy = ball_y - actual_eye_y
        distance = math.sqrt(dx**2 + dy**2)
        if distance > 0:
            # 눈동자가 움직일 수 있는 최대 거리
            max_distance = eye_radius - pupil_radius - 2
            # 방향 벡터 정규화
            dx_norm = dx / distance
            dy_norm = dy / distance
            # 눈동자 위치 계산 (눈 안에서만 움직이도록 제한)
            pupil_offset_x = dx_norm * min(max_distance, distance * 0.1)
            pupil_offset_y = dy_norm * min(max_distance, distance * 0.1)
            return pupil_offset_x, pupil_offset_y
        return 0, 0
    # 왼쪽 눈 그리기
    pygame.draw.circle(crocodile_surface, WHITE, (left_eye_x, eye_y), eye_radius)
    pygame.draw.circle(crocodile_surface, (50, 50, 50), (left_eye_x, eye_y), eye_radius, 2)
    # 왼쪽 눈동자
    left_pupil_offset_x, left_pupil_offset_y = calculate_pupil_position(left_eye_x, eye_y)
    pygame.draw.circle(crocodile_surface, BLACK, 
                      (int(left_eye_x + left_pupil_offset_x), 
                       int(eye_y + left_pupil_offset_y)), pupil_radius)
    # 눈동자 하이라이트
    pygame.draw.circle(crocodile_surface, WHITE, 
                      (int(left_eye_x + left_pupil_offset_x - 2), 
                       int(eye_y + left_pupil_offset_y - 2)), 2)
    # 오른쪽 눈 그리기
    pygame.draw.circle(crocodile_surface, WHITE, (right_eye_x, eye_y), eye_radius)
    pygame.draw.circle(crocodile_surface, (50, 50, 50), (right_eye_x, eye_y), eye_radius, 2)
    # 오른쪽 눈동자
    right_pupil_offset_x, right_pupil_offset_y = calculate_pupil_position(right_eye_x, eye_y)
    pygame.draw.circle(crocodile_surface, BLACK, 
                      (int(right_eye_x + right_pupil_offset_x), 
                       int(eye_y + right_pupil_offset_y)), pupil_radius)
    # 눈동자 하이라이트
    pygame.draw.circle(crocodile_surface, WHITE, 
                      (int(right_eye_x + right_pupil_offset_x - 2), 
                       int(eye_y + right_pupil_offset_y - 2)), 2)
    # 악어 특유의 세로 동공 효과 추가
    for eye_x, pupil_x, pupil_y in [(left_eye_x, left_pupil_offset_x, left_pupil_offset_y), 
                                      (right_eye_x, right_pupil_offset_x, right_pupil_offset_y)]:
        pygame.draw.ellipse(crocodile_surface, BLACK,
                           (int(eye_x + pupil_x - 2), 
                            int(eye_y + pupil_y - pupil_radius),
                            4, pupil_radius * 2))
    return crocodile_surface
def draw_aircraft_carrier_boss(boss_speed=0, boss_x=0):
    """️ 스테이지 6 울트라 배틀크루저 - 최강의 전함 보스 패들"""
    import random
    global laser_cannon_angle, laser_charging, laser_cannon_active, laser_charge_start
    global shield_antenna_active, stage6_boss_hit_timer, stage6_boss_hit_flash
    #  소닉 스타일 피격 효과 타이머 업데이트
    if stage6_boss_hit_timer > 0:
        stage6_boss_hit_timer -= 1
        # 깜빡임 효과 (매 4프레임마다 on/off)
        stage6_boss_hit_flash = (stage6_boss_hit_timer // 4) % 2 == 0
        if stage6_boss_hit_timer <= 0:
            stage6_boss_hit_flash = False
    carrier_width = 220
    carrier_height = 85
    # 배틀크루저 표면 생성
    carrier_surface = pygame.Surface((carrier_width, carrier_height), pygame.SRCALPHA)
    # 체력에 따른 손상 정도 계산
    damage_ratio = 1.0 - (boss_current_health / boss_max_health)
    time_now = pygame.time.get_ticks()
    #  체력 기반 에너지 쉴드 효과 (제거)
    # 파란색 테두리가 나타나지 않도록 주석 처리
    # if boss_current_health > 10:
    #     # 외곽 에너지 쉴드 (체력이 높을수록 강함)
    #     shield_alpha = int(20 + (boss_current_health / boss_max_health) * 30)
    #     shield_color = (100, 150, 255, shield_alpha)
    #     for i in range(3):
    #         pygame.draw.rect(carrier_surface, shield_color, 
    #                        (3-i, 3-i, carrier_width-6+i*2, carrier_height-6+i*2), 1)
    # === 메인 선체 (5단계 레이어드 구조로 입체감 강화) ===
    #  소닉 스타일 피격 효과 적용 (붉은색 오버레이)
    def apply_hit_effect(color):
        if stage6_boss_hit_flash:
            # 붉은색으로 강하게 변환 (소닉 스타일)
            r, g, b = color
            return (min(255, r + 120), max(0, g - 30), max(0, b - 30))
        return color
    # 최하부 그림자 레이어
    shadow_color = apply_hit_effect((35, 40, 45))
    pygame.draw.rect(carrier_surface, shadow_color, (6, 48, carrier_width-12, 34))
    # 하부 선체 (진한 금속색 + 그라데이션 효과)
    hull_base_color = apply_hit_effect((65, 75, 85) if damage_ratio < 0.7 else (55, 60, 70))
    pygame.draw.rect(carrier_surface, hull_base_color, (8, 45, carrier_width-16, 32))
    # 하부 하이라이트
    pygame.draw.line(carrier_surface, apply_hit_effect((75, 85, 95)), (8, 46), (carrier_width-8, 46), 1)
    # 중하부 전환 레이어
    trans_color = apply_hit_effect((72, 82, 95) if damage_ratio < 0.6 else (62, 70, 78))
    pygame.draw.rect(carrier_surface, trans_color, (10, 40, carrier_width-20, 28))
    # 중부 선체 (조금 밝은 색)
    hull_mid_color = apply_hit_effect((80, 90, 105) if damage_ratio < 0.5 else (70, 75, 85))
    pygame.draw.rect(carrier_surface, hull_mid_color, (12, 35, carrier_width-24, 25))
    # 중부 하이라이트
    pygame.draw.line(carrier_surface, apply_hit_effect((90, 100, 115)), (12, 36), (carrier_width-12, 36), 1)
    # 상부 선체 (가장 밝은 색 + 메탈릭 효과)
    hull_top_color = apply_hit_effect((95, 110, 125) if damage_ratio < 0.3 else (85, 95, 110))
    pygame.draw.rect(carrier_surface, hull_top_color, (16, 25, carrier_width-32, 20))
    # 상부 메탈릭 하이라이트
    pygame.draw.line(carrier_surface, (115, 130, 145), (16, 26), (carrier_width-16, 26), 1)
    pygame.draw.line(carrier_surface, (105, 120, 135), (16, 28), (carrier_width-16, 28), 1)
    # === 배틀크루저 특유의 고급 장갑판 시스템 ===
    # 반응형 장갑판 패널들 (체력에 따라 색상 변화)
    panel_base = (110, 125, 140) if boss_current_health > 10 else (90, 100, 115)
    panel_glow = (130, 160, 200) if boss_current_health > 12 else (110, 135, 160)
    for i in range(8):  # 더 많은 패널
        panel_x = 15 + i * 25
        if panel_x < carrier_width - 35:
            # 패널 외곽 (3D 효과)
            pygame.draw.rect(carrier_surface, (70, 80, 90), (panel_x-1, 27, 23, 17))
            pygame.draw.rect(carrier_surface, panel_base, (panel_x, 28, 21, 15))
            pygame.draw.rect(carrier_surface, panel_glow, (panel_x, 28, 21, 15), 1)
            # 패널 내부 고급 디테일
            # 에너지 라인 (펄스 효과)
            pulse = abs(math.sin(time_now * 0.003 + i * 0.5))
            line_color = (int(120 + pulse * 30), int(130 + pulse * 40), int(145 + pulse * 50))
            pygame.draw.line(carrier_surface, line_color, 
                           (panel_x + 2, 30), (panel_x + 19, 30), 1)
            pygame.draw.line(carrier_surface, line_color, 
                           (panel_x + 2, 35), (panel_x + 19, 35), 1)
            pygame.draw.line(carrier_surface, line_color, 
                           (panel_x + 2, 40), (panel_x + 19, 40), 1)
            # 중앙 에너지 코어
            core_x = panel_x + 10
            core_y = 35
            pygame.draw.circle(carrier_surface, panel_glow, (core_x, core_y), 2)
            if boss_current_health > 8:
                pygame.draw.circle(carrier_surface, (180, 210, 255), (core_x, core_y), 1)
    # === 중앙 커맨드 센터 ===
    # 함선 중앙의 메인 구조물
    center_x = carrier_width // 2
    center_y = 42
    
    # 중앙 돔 구조 (커맨드 센터)
    # 외부 링
    pygame.draw.circle(carrier_surface, apply_hit_effect((70, 80, 95)), (center_x, center_y), 15, 2)
    pygame.draw.circle(carrier_surface, apply_hit_effect((90, 100, 115)), (center_x, center_y), 12, 1)
    
    # 중앙 돔
    pygame.draw.circle(carrier_surface, apply_hit_effect((100, 110, 125)), (center_x, center_y), 10)
    pygame.draw.circle(carrier_surface, apply_hit_effect((120, 130, 145)), (center_x, center_y), 8)
    pygame.draw.circle(carrier_surface, apply_hit_effect((140, 150, 165)), (center_x, center_y), 6)
    
    # 에너지 코어 (펄싱 효과 - 매우 밝게)
    core_pulse = abs(math.sin(time_now * 0.003))
    # 노란색-흰색 코어로 변경 (더 눈에 띄게)
    core_color = (min(255, int(230 + core_pulse * 25)), 
                  min(255, int(200 + core_pulse * 50)), 
                  int(100 + core_pulse * 100))
    pygame.draw.circle(carrier_surface, core_color, (center_x, center_y), 6)
    pygame.draw.circle(carrier_surface, (255, 255, 200), (center_x, center_y), 4)
    pygame.draw.circle(carrier_surface, (255, 255, 255), (center_x, center_y), 2)
    
    # 방사형 에너지 라인 (8방향)
    for angle in range(0, 360, 45):
        rad = math.radians(angle)
        line_start_x = center_x + int(math.cos(rad) * 6)
        line_start_y = center_y + int(math.sin(rad) * 6)
        line_end_x = center_x + int(math.cos(rad) * 12)
        line_end_y = center_y + int(math.sin(rad) * 12)
        
        line_color = apply_hit_effect((110, 120, 135))
        pygame.draw.line(carrier_surface, line_color, 
                        (line_start_x, line_start_y), 
                        (line_end_x, line_end_y), 1)
    
    # 커맨드 센터 주변 소형 모듈들
    module_positions = [
        (center_x - 20, center_y - 8),
        (center_x + 20, center_y - 8),
        (center_x - 20, center_y + 8),
        (center_x + 20, center_y + 8)
    ]
    
    for mx, my in module_positions:
        # 소형 모듈
        pygame.draw.rect(carrier_surface, apply_hit_effect((90, 100, 115)), 
                        (mx - 4, my - 3, 8, 6))
        pygame.draw.rect(carrier_surface, apply_hit_effect((110, 120, 135)), 
                        (mx - 3, my - 2, 6, 4))
        # 모듈 창문
        pygame.draw.rect(carrier_surface, (150, 180, 210), (mx - 2, my - 1, 4, 2))
    
    # 연결 통로 (센터와 모듈 연결)
    for mx, my in module_positions:
        pygame.draw.line(carrier_surface, apply_hit_effect((100, 110, 125)), 
                        (center_x, center_y), (mx, my), 2)
        pygame.draw.line(carrier_surface, apply_hit_effect((120, 130, 145)), 
                        (center_x, center_y), (mx, my), 1)
    # === 야마토 캐논급 주포 터렛 시스템 ===
    # 듀얼 배럴 주포 터렛 (더 강력한 느낌)
    # 중앙 터렛 제거 (커맨드 센터와 겹침 방지)
    turret_positions = [(30, 38), (65, 36), (135, 38), (170, 38)]
    for idx, (tx, ty) in enumerate(turret_positions):
        if tx < carrier_width - 25:
            # 터렛 베이스 (다층 구조)
            pygame.draw.circle(carrier_surface, (50, 60, 70), (tx, ty), 10)
            pygame.draw.circle(carrier_surface, (70, 80, 90), (tx, ty), 8)
            pygame.draw.circle(carrier_surface, (90, 100, 110), (tx, ty), 6)
            # 듀얼 포신 (쌍발)
            gun_angle = math.sin(time_now * 0.00001 + tx * 0.01) * 2  # 극도로 느린 움직임 (100배 느리게, 각도도 작게)
            for barrel_offset in [-2, 2]:  # 두 개의 포신
                barrel_x = tx + barrel_offset
                gun_end_x = barrel_x + 15 * math.cos(math.radians(gun_angle))
                gun_end_y = ty + 15 * math.sin(math.radians(gun_angle)) + barrel_offset
                # 포신 그라데이션 (굵기 변화)
                pygame.draw.line(carrier_surface, (40, 50, 60), 
                               (barrel_x, ty), (gun_end_x, gun_end_y), 4)
                pygame.draw.line(carrier_surface, (60, 70, 80), 
                               (barrel_x, ty), (gun_end_x-2, gun_end_y), 3)
                pygame.draw.line(carrier_surface, (80, 90, 100), 
                               (barrel_x, ty), (gun_end_x-4, gun_end_y), 2)
                # 포구 플래시 제거 (사용자 요청 - 주황색 빛 제거)
                # if boss_current_health > 8 and random.random() < 0.1:
                #     flash_color = (255, 200, 100)
                #     pygame.draw.circle(carrier_surface, flash_color, 
                #                      (int(gun_end_x), int(gun_end_y)), 3)
            # 터렛 중앙 에너지 코어
            pygame.draw.circle(carrier_surface, (150, 180, 210), (tx, ty), 3)
            pygame.draw.circle(carrier_surface, (180, 210, 240), (tx-1, ty-1), 1)
    # === 브릿지 구조 ===
    # 간단한 브릿지 본체
    bridge_x = carrier_width - 75
    # 브릿지 본체
    bridge_color = apply_hit_effect((85, 95, 110) if boss_current_health > 5 else (75, 85, 100))
    pygame.draw.rect(carrier_surface, bridge_color, (bridge_x, 15, 50, 25))
    # 브릿지 상층부
    pygame.draw.rect(carrier_surface, apply_hit_effect((105, 115, 130)), (bridge_x + 5, 10, 40, 15))
    
    # === 우주선 창문 시스템 ===
    # 상층 파노라마 창문들 (작은 창문 6개)
    for i in range(6):
        window_x = bridge_x + 6 + i * 6
        # 창문 프레임
        pygame.draw.rect(carrier_surface, apply_hit_effect((120, 130, 145)), 
                        (window_x, 12, 5, 4), 1)
        # 창문 내부 빛 (밝은 파란색-흰색)
