def show_tutorial_dash_dialogue():
    """튜토리얼 대쉬 연습 대화"""
    clock = pygame.time.Clock()
    
    # 폰트 설정
    font_large = FontStyle.subtitle()  # 32pt 화자 이름용
    font_medium = FontStyle.body()    # 24pt 대사용
    font_small = FontStyle.small()   # 18pt 안내용
    
    # 색상 정의
    BOSS_COLOR = (255, 100, 100)  # 조교 텍스트 색상 (빨간색)
    PLAYER_COLOR = (100, 200, 255)  # 플레이어 텍스트 색상 (파란색)
    
    # 대화 시퀀스 (간단한 튜플 형식)
    dialogues = [
        ("조교", "하지만 이 모든 한계는 극복이 가능하지"),
        ("조교", "지금부터 대쉬를 익혀볼 건데"),
        ("조교", "핑파이터에서 가장 유용한 기술 중 하나이다"),
        ("조교", "대쉬란 먼 거리를 짧은시간에 순간적으로 이동하는 기술"),
        ("조교", "원하는 방향 ← → 키를 누른 상태로"),
        ("조교", " ↓ 키를 누르면"),
        ("조교", "해당 방향으로 대쉬가 발동하며 빠르게 이동한다"),
        ("조교", "지금부터 여러가지 대쉬기술을 익혀보겠다"),
        ("조교", " 대쉬 동작 실시 !"),
        ("플레이어", "실시!")
    ]
    
    # 실제 게임 필드에서 시연할 위치 변수 (시연 시에만 사용)
    demo_boss = pygame.Rect(WIDTH // 2 - 40, 120, 80, 20)  # 조교 실제 위치
    demo_player = pygame.Rect(WIDTH // 2 - 40, HEIGHT - 140, 80, 20)  # 플레이어 위치
    demo_ball = pygame.Rect(WIDTH // 2 - 10, HEIGHT // 2 - 10, 20, 20)  # 공 위치
    
    # 현재 게임 화면을 그대로 캡처 (기존 게임 상태를 보존)
    background = SCREEN.copy()
    
    # 대쉬 시연을 위한 변수
    last_dash_direction = None
    dash_sound_played = {"LEFT": False, "RIGHT": False}
    
    # 각 대화를 순차적으로 표시
    for dialogue_index, dialogue in enumerate(dialogues):
        speaker = dialogue[0]
        target_text = dialogue[1]
        speaker_color = BOSS_COLOR if speaker == "조교" else PLAYER_COLOR
        
        # 타이핑 효과 변수
        displayed_text = ""
        text_complete = False
        text_animation_timer = 0
        
        # 8번 대사에서 대쉬 사운드 초기화 및 시연 완료 추적
        if dialogue_index == 7:
            dash_sound_played = {"LEFT": False, "RIGHT": False}
            last_dash_direction = None
            demo_complete = False  # 시연이 완료되었는지 추적
            demo_start_time = None  # 시연 시작 시간 추적
        
        running = True
        while running:
            # 이벤트 처리
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    return False
                if event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_8:
                        # 8번키로 튜토리얼 챕터 스킵
                        print("🎮 8번 키: 대쉬 대화 중 챕터 스킵 요청")
                        return "skip_chapter"  # 특별한 반환값으로 챕터 스킵 신호
                    elif event.key == pygame.K_SPACE:
                        # 대쉬 시연 중에는 스페이스바 무시
                        if dialogue_index == 7 and text_complete:
                            # 시연이 시작된 지 6초가 지났는지 확인 (왼쪽+오른쪽 1회 사이클)
                            if 'demo_state' in locals() and 'demo_complete' in locals():
                                elapsed_time = pygame.time.get_ticks() - demo_state['start_time']
                                if elapsed_time >= 6000:  # 6초 (왼쪽 대쉬 + 대기 + 오른쪽 대쉬 + 대기)
                                    running = False  # 시연이 완료되면 다음 대화로
                                else:
                                    pass  # 시연 중이면 스페이스바 무시
                            else:
                                pass  # demo_state가 아직 생성되지 않았으면 무시
                        elif text_complete:
                            running = False  # 다른 대화에서는 정상 동작
                        else:
                            # 즉시 전체 텍스트 표시
                            displayed_text = target_text
                            text_complete = True
                    elif event.key == pygame.K_ESCAPE:
                        # 대화 스킵
                        return True
            
            # 대화 텍스트 애니메이션
            if len(displayed_text) < len(target_text):
                text_animation_timer += 1
                if text_animation_timer % 2 == 0:  # 텍스트 타이핑 속도
                    displayed_text += target_text[len(displayed_text)]
            else:
                text_complete = True
            
            # 화면 그리기 - 8번 대사일 때는 실제 게임 필드 표시
            if dialogue_index == 7 and text_complete:
                # 게임 필드 배경 그리기
                SCREEN.fill((20, 30, 60))  # 어두운 파란 배경
                
                # 중앙선 그리기
                pygame.draw.line(SCREEN, (100, 100, 100), (0, HEIGHT // 2), (WIDTH, HEIGHT // 2), 2)
                
                # 중앙 원 그리기
                pygame.draw.circle(SCREEN, (100, 100, 100), (WIDTH // 2, HEIGHT // 2), 80, 2)
                
                # 플레이어 패들 이미지 그리기 (아래쪽 고정)
                try:
                    # 실제 플레이어 이미지 사용
                    if 'PLAYER_IMG' in globals() and PLAYER_IMG:
                        # 캐릭터 타입에 따라 다른 이미지 사용
                        if selected_character_type == "soldier" and 'SOLDIER_PADDLE_IMG' in globals():
                            player_demo_img = pygame.transform.scale(SOLDIER_PADDLE_IMG, (80, 32))
                        else:
                            # 플레이어 이미지 크기 조절 (원본이 250x100이므로 축소)
                            player_demo_img = pygame.transform.scale(PLAYER_IMG, (80, 32))
                        player_rect = player_demo_img.get_rect(center=demo_player.center)
                        SCREEN.blit(player_demo_img, player_rect)
                    else:
                        # 이미지가 없을 경우 기본 사각형
                        pygame.draw.rect(SCREEN, (100, 150, 255), demo_player, 0, 5)
                        pygame.draw.rect(SCREEN, (150, 200, 255), demo_player, 2, 5)
                except:
                    # 이미지 로드 실패 시 기본 사각형
                    pygame.draw.rect(SCREEN, (100, 150, 255), demo_player, 0, 5)
                    pygame.draw.rect(SCREEN, (150, 200, 255), demo_player, 2, 5)
                
                # 공 그리기 (중앙 고정)
                pygame.draw.circle(SCREEN, (255, 255, 100), demo_ball.center, 10)
                pygame.draw.circle(SCREEN, (255, 255, 255), demo_ball.center, 10, 2)
            else:
                SCREEN.blit(background, (0, 0))
            
            # 텍스트 배경 (검은색 반투명)
            text_bg_height = 80
            text_bg = pygame.Surface((WIDTH, text_bg_height), pygame.SRCALPHA)
            text_bg.fill((0, 0, 0, 180))
            text_y_position = HEIGHT - 150
            SCREEN.blit(text_bg, (0, text_y_position))
            
            # 화자 이름과 대화 텍스트 처리
            full_text = f"[{speaker}] {displayed_text}"
            text_surface = font_medium.render(full_text, True, speaker_color)
            text_rect = text_surface.get_rect(center=(WIDTH // 2, text_y_position + text_bg_height // 2))
            
            # 텍스트 그림자 효과
            shadow_surface = font_medium.render(full_text, True, (0, 0, 0))
            shadow_rect = text_rect.copy()
            shadow_rect.x += 2
            shadow_rect.y += 2
            SCREEN.blit(shadow_surface, shadow_rect)
            
            # 실제 텍스트
            SCREEN.blit(text_surface, text_rect)
            
            # 8번 대사에서 조교가 대쉬 시연 (실제 게임 필드에서)
            if dialogue_index == 7 and text_complete:  # "해당 방향으로 대쉬가 발동하며 빠르게 이동한다"
                # 대쉬 시연 상태 변수
                if 'demo_state' not in locals():
                    demo_state = {
                        'start_time': pygame.time.get_ticks(),
                        'boss_x': WIDTH // 2,
                        'direction': 0,  # 0: 대기, -1: 왼쪽, 1: 오른쪽
                        'dash_start': 0,
                        'dash_duration': 200,  # 대쉬 지속 시간 (ms)
                        'dash_speed': 800,  # 대쉬 속도 (픽셀/초)
                        'last_direction_change': 0,
                        'dash_sound_played': False,
                        'last_dash_direction': 0,  # 마지막 대쉬 방향 기록
                        'direction_change_time': 0  # 방향 전환 시간 기록
                    }
                
                current_time = pygame.time.get_ticks()
                elapsed = current_time - demo_state['start_time']
                boss_demo_y = 120  # 실제 조교 위치 (상단)
                
                # 3초 주기로 대쉬 방향 전환 (왼쪽 -> 대기 -> 오른쪽 -> 대기)
                cycle_phase = (elapsed // 1500) % 4
                
                # 대쉬 방향 및 타이밍 결정
                if cycle_phase == 0:  # 왼쪽 대쉬 준비
                    if demo_state['direction'] != -1:
                        demo_state['direction'] = -1
                        demo_state['direction_change_time'] = current_time  # 방향 전환 시간 기록
                        demo_state['last_dash_direction'] = -1  # 마지막 대쉬 방향 기록
                        demo_state['dash_start'] = current_time
                        demo_state['dash_sound_played'] = False
                        demo_state['boss_x'] = WIDTH // 2  # 중앙에서 시작
                elif cycle_phase == 1:  # 대기
                    demo_state['direction'] = 0
                    # 위치 유지 (이동 없음)
                elif cycle_phase == 2:  # 오른쪽 대쉬 준비
                    if demo_state['direction'] != 1:
                        demo_state['direction'] = 1
                        demo_state['direction_change_time'] = current_time  # 방향 전환 시간 기록
                        demo_state['last_dash_direction'] = 1  # 마지막 대쉬 방향 기록
                        demo_state['dash_start'] = current_time
                        demo_state['dash_sound_played'] = False
                        demo_state['boss_x'] = WIDTH // 2  # 중앙에서 시작
                else:  # 대기
                    demo_state['direction'] = 0
                    # 위치 유지 (이동 없음)
                
                # 대쉬 중일 때 위치 업데이트
                if demo_state['direction'] != 0:
                    dash_elapsed = current_time - demo_state['dash_start']
                    
                    # 대쉬 사운드 재생
                    if not demo_state['dash_sound_played']:
                        if 'SOUND_DASH' in globals():
                            play_sound_with_volume(SOUND_DASH)
                        demo_state['dash_sound_played'] = True
                    
                    if dash_elapsed < demo_state['dash_duration']:
                        # 대쉬 진행 중
                        dash_progress = dash_elapsed / demo_state['dash_duration']
                        max_dash_distance = 180  # 최대 대쉬 거리 제한
                        dash_distance = min(max_dash_distance, demo_state['dash_speed'] * (dash_elapsed / 1000.0))
                        
                        if demo_state['direction'] == -1:  # 왼쪽 대쉬
                            demo_state['boss_x'] = WIDTH // 2 - dash_distance
                        else:  # 오른쪽 대쉬
                            demo_state['boss_x'] = WIDTH // 2 + dash_distance
                
                # 조교 패들 위치 제한
                demo_state['boss_x'] = max(100, min(WIDTH - 100, demo_state['boss_x']))
                
                # 조교 이미지 로드 및 표시
                try:
                    boss_img_path = resource_path("boss_tutorial.png")
                    boss_img = pygame.image.load(boss_img_path)
                    boss_img = pygame.transform.scale(boss_img, (80, 100))  # 크기 조정
                    boss_rect = boss_img.get_rect(center=(demo_state['boss_x'], boss_demo_y))
                    SCREEN.blit(boss_img, boss_rect)
                except:
                    # 이미지 로드 실패 시 대체 표시
                    demo_boss.centerx = demo_state['boss_x']
                    demo_boss.centery = boss_demo_y
                    pygame.draw.rect(SCREEN, (255, 100, 100), demo_boss, 0, 5)
                    pygame.draw.rect(SCREEN, (255, 150, 150), demo_boss, 2, 5)
                
                # 대쉬 중일 때 이펙트
                if demo_state['direction'] != 0:
                    dash_elapsed = current_time - demo_state['dash_start']
                    if dash_elapsed < demo_state['dash_duration']:
                        # 대쉬 잔상 효과
                        for i in range(5):
                            alpha = 100 - i * 20
                            if demo_state['direction'] == -1:
                                ghost_x = demo_state['boss_x'] + i * 30
                            else:
                                ghost_x = demo_state['boss_x'] - i * 30
                            
                            # 조교 이미지로 잔상 효과 생성
                            try:
                                boss_img_path = resource_path("boss_tutorial.png")
                                boss_ghost_img = pygame.image.load(boss_img_path)
                                boss_ghost_img = pygame.transform.scale(boss_ghost_img, (80, 100))
                                boss_ghost_img.set_alpha(alpha)
                                ghost_rect = boss_ghost_img.get_rect(center=(ghost_x, boss_demo_y))
                                SCREEN.blit(boss_ghost_img, ghost_rect)
                            except:
                                # 이미지 로드 실패 시 대체 잔상
                                ghost_surface = pygame.Surface((80, 20), pygame.SRCALPHA)
                                ghost_surface.fill((255, 100, 100, alpha))
                                SCREEN.blit(ghost_surface, (ghost_x - 40, boss_demo_y - 10))
                        
                        # 대쉬 이동선 효과
                        line_color = (255, 200, 100)
                        if demo_state['direction'] == -1:
                            pygame.draw.line(SCREEN, line_color, 
                                           (demo_state['boss_x'] + 40, boss_demo_y),
                                           (demo_state['boss_x'] + 150, boss_demo_y), 3)
                            # 방향 표시
                            arrow_text = "◀◀ DASH!"
                            arrow_surface = font_small.render(arrow_text, True, YELLOW)
                            arrow_rect = arrow_surface.get_rect(center=(demo_state['boss_x'], boss_demo_y - 40))
                            SCREEN.blit(arrow_surface, arrow_rect)
                        else:
                            pygame.draw.line(SCREEN, line_color, 
                                           (demo_state['boss_x'] - 40, boss_demo_y),
                                           (demo_state['boss_x'] - 150, boss_demo_y), 3)
                            # 방향 표시
                            arrow_text = "DASH! ▶▶"
                            arrow_surface = font_small.render(arrow_text, True, YELLOW)
                            arrow_rect = arrow_surface.get_rect(center=(demo_state['boss_x'], boss_demo_y - 40))
                            SCREEN.blit(arrow_surface, arrow_rect)
                
                # 키 조합 표시 (대쉬 후에도 유지, 방향 전환 시 잠시 숨김)
                if 'demo_state' in locals() and demo_state['last_dash_direction'] != 0:
                    # 방향 전환 후 300ms 동안은 표시하지 않음
                    time_since_change = current_time - demo_state['direction_change_time']
                    if time_since_change > 300:  # 300ms 후부터 표시
                        if demo_state['last_dash_direction'] == -1:
                            key_combo_text = "← + ↓"
                        else:
                            key_combo_text = "→ + ↓"
                        
                        key_combo_font = FontStyle.subtitle()  # 큰 폰트 사용
                        key_combo_surface = key_combo_font.render(key_combo_text, True, CYAN)
                        key_combo_rect = key_combo_surface.get_rect(center=(WIDTH // 2, HEIGHT - 200))
                        
                        # 배경 박스
                        bg_rect = key_combo_rect.inflate(40, 20)
                        pygame.draw.rect(SCREEN, (0, 0, 0, 180), bg_rect, 0, 10)
                        pygame.draw.rect(SCREEN, CYAN, bg_rect, 3, 10)
                        
                        SCREEN.blit(key_combo_surface, key_combo_rect)
            
            # 스페이스바 안내 (하단 우측)
            if text_complete:
                # 대쉬 시연 중에는 다른 메시지 표시
                if dialogue_index == 7 and 'demo_state' in locals():
                    elapsed_time = pygame.time.get_ticks() - demo_state['start_time']
                    if elapsed_time < 6000:  # 시연 진행 중
                        instruction = "조교 시범 중..."
                        text_color = YELLOW  # 노란색으로 표시
                    else:  # 시연 완료
                        instruction = "SPACE - 계속"
                        text_color = CYAN
                else:
                    instruction = "SPACE - 계속" if dialogue_index < len(dialogues) - 1 else "SPACE - 시작"
                    text_color = CYAN
                    
                inst_surface = font_small.render(instruction, True, text_color)
                inst_rect = inst_surface.get_rect(bottomright=(WIDTH - 20, HEIGHT - 20))
                
                # 깜빡임 효과 (시연 중이 아닐 때만)
                if dialogue_index != 7 or 'demo_state' not in locals() or pygame.time.get_ticks() - demo_state['start_time'] >= 6000:
                    if pygame.time.get_ticks() % 1000 < 500:
                        SCREEN.blit(inst_surface, inst_rect)
                else:
                    # 시연 중에는 항상 표시
                    SCREEN.blit(inst_surface, inst_rect)
            
            pygame.display.flip()
            clock.tick(60)
    
    return True

def draw_tutorial_ui():
    """튜토리얼 UI 표시 (타격 카운터 및 안내 메시지)"""
    global tutorial_gauge_tutorial_shown, tutorial_speed_dialogue_shown
    global tutorial_player_hit_count, tutorial_displayed_hit_count
    global tutorial_current_chapter
    
    # 튜토리얼 진행도 바 표시 (사용자 요청으로 제거)
    # if current_stage == 50:
    #     draw_tutorial_progress_bar()
    
    # Chapter 1에서 게이지 튜토리얼 이후, 속도 튜토리얼 전에만 표시
    if current_stage == 50 and tutorial_current_chapter == 1 and tutorial_gauge_tutorial_shown and not tutorial_speed_dialogue_shown:
        # 점진적 애니메이션 업데이트
        if tutorial_displayed_hit_count < tutorial_player_hit_count:
            # 부드러운 애니메이션 속도 (프레임당 0.05 증가)
            tutorial_displayed_hit_count = min(tutorial_displayed_hit_count + 0.05, tutorial_player_hit_count)
        # 폰트 설정
        font_large = FontStyle.body()      # 24pt - 숫자용 (작게 변경)
        font_medium = FontStyle.small()    # 18pt
        font_small = FontStyle.tiny()      # 16pt
        
        # 오른쪽 상단 위치 (더 작고 미니멀하게)
        ui_x = WIDTH - 100
        ui_y = 50
        
        # 미니멀한 반투명 배경 (크기 조정)
        bg_width = 180
        bg_height = 90  # 세로 길이 줄임 (120 -> 90)
        bg_x = ui_x - bg_width // 2
        bg_y = ui_y - 15
        
        # 반투명 배경 (매우 은은하게)
        bg_surf = pygame.Surface((bg_width, bg_height), pygame.SRCALPHA)
        pygame.draw.rect(bg_surf, (20, 25, 40, 120), (0, 0, bg_width, bg_height), border_radius=8)
        pygame.draw.rect(bg_surf, (100, 255, 255, 40), (0, 0, bg_width, bg_height), border_radius=8, width=1)
        SCREEN.blit(bg_surf, (bg_x, bg_y))
        
        # 컴팩트한 원형 진행도
        circle_radius = 22
        circle_center_x = ui_x - 50
        circle_center_y = ui_y + 10
        
        # 배경 원 (매우 은은하게)
        pygame.draw.circle(SCREEN, (40, 45, 60, 180), (circle_center_x, circle_center_y), circle_radius, 2)
        
        # 진행도 원호 그리기 (애니메이션 값 사용)
        if tutorial_displayed_hit_count > 0:
            import math
            progress = tutorial_displayed_hit_count / 6
            # 시작 각도 -90도 (12시 방향)
            start_angle = -math.pi / 2
            # 진행도에 따른 종료 각도
            end_angle = start_angle + (2 * math.pi * progress)
            
            # 아크를 작은 선분들로 그리기
            num_segments = max(2, int(36 * progress))  # 더 부드럽게 표시
            for i in range(num_segments):
                angle1 = start_angle + (end_angle - start_angle) * (i / num_segments)
                angle2 = start_angle + (end_angle - start_angle) * ((i + 1) / num_segments)
                
                x1 = circle_center_x + circle_radius * math.cos(angle1)
                y1 = circle_center_y + circle_radius * math.sin(angle1)
                x2 = circle_center_x + circle_radius * math.cos(angle2)
                y2 = circle_center_y + circle_radius * math.sin(angle2)
                
                # 진행도 색상 (실제 hit count 기준)
                if tutorial_player_hit_count < 3:
                    color = (120, 150, 180)  # 은은한 회색-파랑
                elif tutorial_player_hit_count < 6:
                    color = (100, 200, 255)  # 밝은 파랑
                else:
                    color = (0, 255, 100)  # 완료 시 초록색
                
                pygame.draw.line(SCREEN, color, (x1, y1), (x2, y2), 3)
        
        # 숫자 표시 (실제 값으로)
        counter_text = f"{tutorial_player_hit_count}/6"
        counter_surface = font_large.render(counter_text, True, (255, 255, 255))
        counter_rect = counter_surface.get_rect(center=(circle_center_x, circle_center_y))
        SCREEN.blit(counter_surface, counter_rect)
        
        # 탁구채 아이콘 그리기 (원형 진행도 오른쪽에)
        paddle_x = circle_center_x + circle_radius + 25
        paddle_y = circle_center_y
        
        # 애니메이션 각도 계산 (진행도에 따라 회전)
        import math
        paddle_angle = -15 + (tutorial_displayed_hit_count * 10)  # -15도에서 시작, 진행도에 따라 회전
        
        # 탁구채 그리기 (간단한 도형으로)
        paddle_surf = pygame.Surface((40, 50), pygame.SRCALPHA)
        
        # 탁구채 헤드 (타원형)
        paddle_color = (255, 100, 50) if tutorial_player_hit_count >= 3 else (200, 200, 200)
        pygame.draw.ellipse(paddle_surf, paddle_color, (5, 0, 30, 35))
        pygame.draw.ellipse(paddle_surf, (255, 255, 255, 50), (8, 3, 24, 29), 2)  # 하이라이트
        
        # 탁구채 손잡이
        handle_color = (100, 50, 30)
        pygame.draw.rect(paddle_surf, handle_color, (17, 30, 6, 20))
        
        # 진행도에 따른 반짝임 효과
        if tutorial_displayed_hit_count < tutorial_player_hit_count:
            # 애니메이션 중일 때 반짝임
            glow_alpha = int(128 + 127 * math.sin(pygame.time.get_ticks() * 0.01))
            glow_surf = pygame.Surface((40, 50), pygame.SRCALPHA)
            pygame.draw.ellipse(glow_surf, (255, 255, 100, glow_alpha // 2), (2, -3, 36, 41))
            paddle_surf.blit(glow_surf, (0, 0))
        
        # 회전 적용
        rotated_paddle = pygame.transform.rotate(paddle_surf, paddle_angle)
        
        # 진행도에 따른 위치 조정 (위아래 움직임)
        bounce_offset = int(5 * math.sin(tutorial_displayed_hit_count * math.pi))
        paddle_rect = rotated_paddle.get_rect(center=(paddle_x, paddle_y + bounce_offset))
        SCREEN.blit(rotated_paddle, paddle_rect)
        
        # 진행 상태 메시지 (탁구채 아래에)
        if tutorial_player_hit_count < 3:
            hint_text = "각도 연습"
            hint_color = (150, 150, 150)
        elif tutorial_player_hit_count < 6:
            hint_text = "잘하고 있어요!"
            hint_color = (100, 200, 255)
            # 칭찬 메시지에 작은 반짝임 효과
            if pygame.time.get_ticks() % 1000 < 500:
                hint_color = (150, 220, 255)
        else:
            hint_text = "완료!"
            hint_color = (0, 255, 100)
            # 완료 시 강조 효과
            if pygame.time.get_ticks() % 800 < 400:
                pygame.draw.circle(SCREEN, (0, 255, 100, 50), (circle_center_x, circle_center_y), circle_radius + 5, 2)
        
        # 축하 이펙트 추가
        global tutorial_hit_counter_celebration, tutorial_hit_counter_celebration_timer
        if tutorial_hit_counter_celebration:
            current_time = pygame.time.get_ticks()
            celebration_duration = current_time - tutorial_hit_counter_celebration_timer
            
            # 2초간 축하 이펙트 표시
            if celebration_duration < 2000:
                # 맥동 효과
                pulse = 1.0 + 0.3 * math.sin(celebration_duration * 0.01)
                pulse_radius = int(circle_radius * pulse)
                
                # 무지개 색상 효과
                rainbow_colors = [
                    (255, 0, 0), (255, 127, 0), (255, 255, 0),
                    (0, 255, 0), (0, 0, 255), (75, 0, 130), (238, 130, 238)
                ]
                color_index = (celebration_duration // 100) % len(rainbow_colors)
                celebration_color = rainbow_colors[color_index]
                
                # 반짝이는 원 그리기
                pygame.draw.circle(SCREEN, celebration_color + (100,), 
                                 (circle_center_x, circle_center_y), pulse_radius, 3)
                
                # 별 이펙트
                star_count = 8
                for i in range(star_count):
                    angle = (2 * math.pi * i / star_count) + (celebration_duration * 0.002)
                    star_distance = pulse_radius + 15 + 10 * math.sin(celebration_duration * 0.005 + i)
                    star_x = circle_center_x + int(star_distance * math.cos(angle))
                    star_y = circle_center_y + int(star_distance * math.sin(angle))
                    star_size = 3 + int(2 * math.sin(celebration_duration * 0.01 + i))
                    pygame.draw.circle(SCREEN, (255, 255, 100), (star_x, star_y), star_size)
            else:
                # 2초 후 축하 이펙트 종료
                tutorial_hit_counter_celebration = False
        
        # 텍스트를 탁구채 아래에 배치 (위치 조정)
        hint_surface = font_medium.render(hint_text, True, hint_color)
        hint_rect = hint_surface.get_rect(centerx=paddle_x, top=paddle_y + 25)  # 30 -> 25로 조정
        SCREEN.blit(hint_surface, hint_rect)

def draw_tutorial_drive_counter():
    """튜토리얼 드라이브 카운터 UI 표시 - 챕터 2 스타일 (우측 상단, 컴팩트)"""
    import math  # 함수 시작시 import
    global tutorial_drive_counter_active, tutorial_drive_count, tutorial_displayed_drive_count
    global tutorial_left_drive_count, tutorial_right_drive_count
    global tutorial_displayed_left_drive_count, tutorial_displayed_right_drive_count
    
    # 드라이브 카운터가 활성화되었을 때만 표시
    if not tutorial_drive_counter_active or current_stage != 50:
        return
    
    # 점진적 애니메이션 업데이트
    if tutorial_displayed_left_drive_count < tutorial_left_drive_count:
        tutorial_displayed_left_drive_count = min(tutorial_displayed_left_drive_count + 0.05, tutorial_left_drive_count)
    if tutorial_displayed_right_drive_count < tutorial_right_drive_count:
        tutorial_displayed_right_drive_count = min(tutorial_displayed_right_drive_count + 0.05, tutorial_right_drive_count)
    tutorial_displayed_drive_count = tutorial_displayed_left_drive_count + tutorial_displayed_right_drive_count
    
    # 폰트 설정
    font_large = FontStyle.body()      # 24pt
    font_medium = FontStyle.small()    # 18pt
    
    # 화면 우측 상단에 위치 (챕터 2와 동일한 위치)
    ui_x = WIDTH - 120
    ui_y = 50
    
    # 컴팩트한 배경 박스 크기 (챕터 2와 유사)
    bg_width = 220
    bg_height = 90  # 2개 미션이므로 더 작게
    bg_x = ui_x - bg_width // 2
    bg_y = ui_y - 15
    
    # 반투명 배경 (은은하게)
    bg_surf = pygame.Surface((bg_width, bg_height), pygame.SRCALPHA)
    pygame.draw.rect(bg_surf, (20, 25, 40, 120), (0, 0, bg_width, bg_height), border_radius=8)
    pygame.draw.rect(bg_surf, (255, 100, 100, 40), (0, 0, bg_width, bg_height), border_radius=8, width=1)
    SCREEN.blit(bg_surf, (bg_x, bg_y))
    
    # 미션 데이터
    missions = [
        {"name": "왼쪽 드라이브", "count": tutorial_left_drive_count, "max": 2, "color": (255, 150, 100)},
        {"name": "오른쪽 드라이브", "count": tutorial_right_drive_count, "max": 2, "color": (100, 200, 255)}
    ]
    
    # 각 미션을 세로로 배치 (컴팩트하게)
    mission_y = bg_y + 10
    for i, mission in enumerate(missions):
        mission_x = bg_x + 15
        
        # 미션 이름
        name_color = (200, 200, 200)
        if mission["count"] >= mission["max"]:
            name_color = (100, 255, 100)  # 완료시 녹색
        
        name_surface = font_medium.render(mission["name"], True, name_color)
        SCREEN.blit(name_surface, (mission_x, mission_y))
        
        # 카운터 텍스트 (오른쪽에 배치)
        counter_text = f"{mission['count']}/{mission['max']}"
        counter_color = (100, 255, 100) if mission["count"] >= mission["max"] else (255, 255, 255)
        counter_surface = font_medium.render(counter_text, True, counter_color)
        counter_rect = counter_surface.get_rect(right=bg_x + bg_width - 40, centery=mission_y + 10)
        SCREEN.blit(counter_surface, counter_rect)
        
        # 완료 체크마크 (OK 텍스트로 대체)
        if mission["count"] >= mission["max"]:
            check_surface = font_large.render("OK", True, (0, 255, 0))
            check_rect = check_surface.get_rect(right=bg_x + bg_width - 10, centery=mission_y + 10)
            SCREEN.blit(check_surface, check_rect)
        
        # 진행 바 (미션 이름 아래에 작게)
        bar_y = mission_y + 22
        bar_width = bg_width - 30
        bar_height = 6
        bar_x = bg_x + 15
        
        # 진행 바 배경
        pygame.draw.rect(SCREEN, (60, 60, 60), (bar_x, bar_y, bar_width, bar_height))
        
        # 진행 바
        if mission["count"] > 0:
            progress_width = int((mission["count"] / mission["max"]) * bar_width)
            progress_color = (0, 200, 0) if mission["count"] >= mission["max"] else mission["color"]
            pygame.draw.rect(SCREEN, progress_color, (bar_x, bar_y, progress_width, bar_height))
        
        # 진행 바 테두리
        pygame.draw.rect(SCREEN, (100, 100, 100), (bar_x, bar_y, bar_width, bar_height), 1)
        
        mission_y += 40  # 다음 미션 위치 (더 컴팩트하게)
    
    # 전체 진행 상태 메시지 (박스 아래, 작게) - 챕터 2와 동일한 스타일
    total_count = tutorial_left_drive_count + tutorial_right_drive_count
    if total_count == 0:
        hint_text = "드라이브 연습"
        hint_color = (150, 150, 150)
    elif total_count == 1:
        hint_text = "잘하고 있어요!"
        hint_color = (255, 200, 100)
    elif total_count == 2:
        hint_text = "훌륭해요!"
        hint_color = (255, 200, 100)
        # 칭찬 메시지에 반짝임 효과
        if pygame.time.get_ticks() % 1000 < 500:
            hint_color = (255, 230, 150)
    elif total_count == 3:
        hint_text = "거의 다 왔어요!"
        hint_color = (100, 255, 255)
    else:
        hint_text = "미션 완료!"
        hint_color = (0, 255, 200)
        # 완료 시 강한 반짝임
        if pygame.time.get_ticks() % 600 < 300:
            hint_color = (100, 255, 255)
    
    hint_surface = font_medium.render(hint_text, True, hint_color)
    hint_rect = hint_surface.get_rect(centerx=ui_x, top=bg_y + bg_height + 5)
    SCREEN.blit(hint_surface, hint_rect)
    
    # 축하 이펙트 추가
    global tutorial_drive_counter_celebration, tutorial_drive_counter_celebration_timer
    if tutorial_drive_counter_celebration:
        current_time = pygame.time.get_ticks()
        celebration_duration = current_time - tutorial_drive_counter_celebration_timer
        
        # 2초간 축하 이펙트 표시
        if celebration_duration < 2000:
            # 박스 주변에 반짝이는 테두리 효과
            pulse = 1.0 + 0.2 * math.sin(celebration_duration * 0.01)
            
            # 무지개 색상 효과
            rainbow_colors = [
                (255, 0, 0), (255, 127, 0), (255, 255, 0),
                (0, 255, 0), (0, 0, 255), (75, 0, 130), (238, 130, 238)
            ]
            color_index = (celebration_duration // 100) % len(rainbow_colors)
            celebration_color = rainbow_colors[color_index]
            
            # 반짝이는 테두리
            pygame.draw.rect(SCREEN, celebration_color, 
                           (bg_x - 10 - int(5 * pulse), bg_y - 10 - int(5 * pulse), 
                            bg_width + int(10 * pulse), bg_height + int(10 * pulse)), 3)
            
            # 별 이펙트
            star_count = 6
            for i in range(star_count):
                angle = (2 * math.pi * i / star_count) + (celebration_duration * 0.002)
                star_distance = 30 + 10 * math.sin(celebration_duration * 0.005 + i)
                star_x = bg_x + bg_width // 2 + int(star_distance * math.cos(angle))
                star_y = bg_y + bg_height // 2 + int(star_distance * math.sin(angle))
                star_size = 3 + int(2 * math.sin(celebration_duration * 0.01 + i))
                pygame.draw.circle(SCREEN, (255, 255, 100), (star_x, star_y), star_size)
        else:
            # 2초 후 축하 이펙트 종료
            tutorial_drive_counter_celebration = False

def draw_tutorial_dash_counter():
    """튜토리얼 대쉬 카운터 UI 표시 (하프대쉬, 대쉬, 연속대쉬)"""
    global tutorial_dash_counter_active, tutorial_dash_count, tutorial_half_dash_count, tutorial_consecutive_dash_count
    global tutorial_displayed_dash_count
    
    # 대쉬 카운터가 활성화되었을 때만 표시
    if not tutorial_dash_counter_active or current_stage != 50:
        return
    
    # 점진적 애니메이션 업데이트 (전체 진행도 계산)
    total_progress = tutorial_half_dash_count + tutorial_dash_count + tutorial_consecutive_dash_count
    if tutorial_displayed_dash_count < total_progress:
        # 부드러운 애니메이션 속도 (프레임당 0.05 증가)
        tutorial_displayed_dash_count = min(tutorial_displayed_dash_count + 0.05, total_progress)
    
    # 폰트 설정
    font_large = FontStyle.body()      # 24pt - 숫자용
    font_medium = FontStyle.small()    # 18pt
    font_small = FontStyle.small()     # 작은 텍스트용
    
    # 오른쪽 상단 위치
    ui_x = WIDTH - 120
    ui_y = 50
    
    # 더 큰 반투명 배경 (3개 미션을 위해)
    bg_width = 220
    bg_height = 120
    bg_x = ui_x - bg_width // 2
    bg_y = ui_y - 15
    
    # 반투명 배경 (은은하게)
    bg_surf = pygame.Surface((bg_width, bg_height), pygame.SRCALPHA)
    pygame.draw.rect(bg_surf, (20, 25, 40, 120), (0, 0, bg_width, bg_height), border_radius=8)
    pygame.draw.rect(bg_surf, (100, 255, 255, 40), (0, 0, bg_width, bg_height), border_radius=8, width=1)
    SCREEN.blit(bg_surf, (bg_x, bg_y))
    
    # 3개의 미션 표시
    missions = [
        {"name": "하프대쉬", "count": tutorial_half_dash_count, "max": 2, "color": (255, 150, 100)},
        {"name": "대쉬", "count": tutorial_dash_count, "max": 2, "color": (100, 200, 255)},
        {"name": "연속대쉬", "count": tutorial_consecutive_dash_count, "max": 1, "color": (255, 215, 0)}
    ]
    
    # 각 미션을 세로로 배치
    mission_y = bg_y + 10
    for i, mission in enumerate(missions):
        mission_x = bg_x + 15
        
        # 미션 이름
        name_surface = font_medium.render(mission["name"], True, (200, 200, 200))
        SCREEN.blit(name_surface, (mission_x, mission_y))
        
        # 진행도 바 배경
        bar_x = mission_x + 80
        bar_y = mission_y + 3
        bar_width = 80
        bar_height = 16
        
        # 배경 바
        pygame.draw.rect(SCREEN, (40, 40, 50), (bar_x, bar_y, bar_width, bar_height), border_radius=8)
        
        # 진행도 바
        if mission["count"] > 0:
            progress_width = int(bar_width * (mission["count"] / mission["max"]))
            pygame.draw.rect(SCREEN, mission["color"], (bar_x, bar_y, progress_width, bar_height), border_radius=8)
        
        # 테두리
        pygame.draw.rect(SCREEN, (100, 100, 120), (bar_x, bar_y, bar_width, bar_height), 1, border_radius=8)
        
        # 카운터 텍스트
        counter_text = f"{mission['count']}/{mission['max']}"
        counter_surface = font_small.render(counter_text, True, (255, 255, 255))
        counter_rect = counter_surface.get_rect(center=(bar_x + bar_width // 2, bar_y + bar_height // 2))
        SCREEN.blit(counter_surface, counter_rect)
        
        # 완료 체크 표시
        if mission["count"] >= mission["max"]:
            check_x = bar_x + bar_width + 10
            check_y = bar_y + bar_height // 2
            # 체크마크 그리기
            pygame.draw.lines(SCREEN, (0, 255, 100), False, 
                            [(check_x, check_y), (check_x + 5, check_y + 5), (check_x + 12, check_y - 5)], 2)
        
        # 다음 미션 위치
        mission_y += 35
    
    # 전체 진행 상태 메시지
    total_completed = 0
    if tutorial_half_dash_count >= 2:
        total_completed += 1
    if tutorial_dash_count >= 2:
        total_completed += 1
    if tutorial_consecutive_dash_count >= 1:
        total_completed += 1
    
    if total_completed == 0:
        hint_text = "대쉬 미션 시작!"
        hint_color = (150, 150, 150)
    elif total_completed == 1:
        hint_text = "잘하고 있어요!"
        hint_color = (255, 200, 100)
    elif total_completed == 2:
        hint_text = "거의 다 왔어요!"
        hint_color = (100, 255, 255)
    else:
        hint_text = "미션 완료!"
        hint_color = (0, 255, 200)
    
    # 축하 이펙트 추가
    global tutorial_dash_counter_celebration, tutorial_dash_counter_celebration_timer
    if tutorial_dash_counter_celebration:
        current_time = pygame.time.get_ticks()
        celebration_duration = current_time - tutorial_dash_counter_celebration_timer
        
        # 2초간 축하 이펙트 표시
        if celebration_duration < 2000:
            import math
            # 맥동 효과
            pulse = 1.0 + 0.3 * math.sin(celebration_duration * 0.01)
            
            # 무지개 색상 효과
            rainbow_colors = [
                (255, 0, 0), (255, 127, 0), (255, 255, 0),
                (0, 255, 0), (0, 0, 255), (75, 0, 130), (238, 130, 238)
            ]
            color_index = (celebration_duration // 100) % len(rainbow_colors)
            celebration_color = rainbow_colors[color_index]
            
            # 반짝이는 테두리
            pygame.draw.rect(SCREEN, celebration_color, (bg_x - 2, bg_y - 2, bg_width + 4, bg_height + 4), 2, border_radius=8)
            
            # 별 이펙트 (배경 주변)
            star_count = 6
            for i in range(star_count):
                angle = (2 * math.pi * i / star_count) + (celebration_duration * 0.002)
                star_x = ui_x + int(60 * math.cos(angle))
                star_y = ui_y + 50 + int(40 * math.sin(angle))
                star_size = 3 + int(2 * math.sin(celebration_duration * 0.01 + i))
                pygame.draw.circle(SCREEN, (255, 255, 100), (star_x, star_y), star_size)
        else:
            # 2초 후 축하 이펙트 종료
            tutorial_dash_counter_celebration = False
    
    # 힌트 텍스트 표시
    hint_surface = font_medium.render(hint_text, True, hint_color)
    hint_rect = hint_surface.get_rect(centerx=ui_x, top=bg_y + bg_height + 5)
    SCREEN.blit(hint_surface, hint_rect)

def draw_tutorial_drive_counter():
    """튜토리얼 드라이브 카운터 UI 표시 - 챕터 2 스타일 (우측 상단, 컴팩트)"""
    import math  # 함수 시작시 import
    global tutorial_drive_counter_active, tutorial_drive_count, tutorial_displayed_drive_count
    global tutorial_left_drive_count, tutorial_right_drive_count
    global tutorial_displayed_left_drive_count, tutorial_displayed_right_drive_count
    
    # 드라이브 카운터가 활성화되었을 때만 표시
    if not tutorial_drive_counter_active or current_stage != 50:
        return
    
    # 점진적 애니메이션 업데이트
    if tutorial_displayed_left_drive_count < tutorial_left_drive_count:
        tutorial_displayed_left_drive_count = min(tutorial_displayed_left_drive_count + 0.05, tutorial_left_drive_count)
    if tutorial_displayed_right_drive_count < tutorial_right_drive_count:
        tutorial_displayed_right_drive_count = min(tutorial_displayed_right_drive_count + 0.05, tutorial_right_drive_count)
    tutorial_displayed_drive_count = tutorial_displayed_left_drive_count + tutorial_displayed_right_drive_count
    
    # 폰트 설정
    font_large = FontStyle.body()      # 24pt
    font_medium = FontStyle.small()    # 18pt
    
    # 화면 우측 상단에 위치 (챕터 2와 동일한 위치)
    ui_x = WIDTH - 120
    ui_y = 50
    
    # 컴팩트한 배경 박스 크기 (챕터 2와 유사)
    bg_width = 220
    bg_height = 90  # 2개 미션이므로 더 작게
    bg_x = ui_x - bg_width // 2
    bg_y = ui_y - 15
    
    # 반투명 배경 (은은하게)
    bg_surf = pygame.Surface((bg_width, bg_height), pygame.SRCALPHA)
    pygame.draw.rect(bg_surf, (20, 25, 40, 120), (0, 0, bg_width, bg_height), border_radius=8)
    pygame.draw.rect(bg_surf, (255, 100, 100, 40), (0, 0, bg_width, bg_height), border_radius=8, width=1)
    SCREEN.blit(bg_surf, (bg_x, bg_y))
    
    # 미션 데이터
    missions = [
        {"name": "왼쪽 드라이브", "count": tutorial_left_drive_count, "max": 2, "color": (255, 150, 100)},
        {"name": "오른쪽 드라이브", "count": tutorial_right_drive_count, "max": 2, "color": (100, 200, 255)}
    ]
    
    # 각 미션을 세로로 배치 (컴팩트하게)
    mission_y = bg_y + 10
    for i, mission in enumerate(missions):
        mission_x = bg_x + 15
        
        # 미션 이름
        name_color = (200, 200, 200)
        if mission["count"] >= mission["max"]:
            name_color = (100, 255, 100)  # 완료시 녹색
        
        name_surface = font_medium.render(mission["name"], True, name_color)
        SCREEN.blit(name_surface, (mission_x, mission_y))
        
        # 카운터 텍스트 (오른쪽에 배치)
        counter_text = f"{mission['count']}/{mission['max']}"
        counter_color = (100, 255, 100) if mission["count"] >= mission["max"] else (255, 255, 255)
        counter_surface = font_medium.render(counter_text, True, counter_color)
        counter_rect = counter_surface.get_rect(right=bg_x + bg_width - 40, centery=mission_y + 10)
        SCREEN.blit(counter_surface, counter_rect)
        
        # 완료 체크마크 (OK 텍스트로 대체)
        if mission["count"] >= mission["max"]:
            check_surface = font_large.render("OK", True, (0, 255, 0))
            check_rect = check_surface.get_rect(right=bg_x + bg_width - 10, centery=mission_y + 10)
            SCREEN.blit(check_surface, check_rect)
        
        # 진행 바 (미션 이름 아래에 작게)
        bar_y = mission_y + 22
        bar_width = bg_width - 30
        bar_height = 6
        bar_x = bg_x + 15
        
        # 진행 바 배경
        pygame.draw.rect(SCREEN, (60, 60, 60), (bar_x, bar_y, bar_width, bar_height))
        
        # 진행 바
        if mission["count"] > 0:
            progress_width = int((mission["count"] / mission["max"]) * bar_width)
            progress_color = (0, 200, 0) if mission["count"] >= mission["max"] else mission["color"]
            pygame.draw.rect(SCREEN, progress_color, (bar_x, bar_y, progress_width, bar_height))
        
        # 진행 바 테두리
        pygame.draw.rect(SCREEN, (100, 100, 100), (bar_x, bar_y, bar_width, bar_height), 1)
        
        mission_y += 40  # 다음 미션 위치 (더 컴팩트하게)
    
    # 전체 진행 상태 메시지 (박스 아래, 작게) - 챕터 2와 동일한 스타일
    total_count = tutorial_left_drive_count + tutorial_right_drive_count
    if total_count == 0:
        hint_text = "드라이브 연습"
        hint_color = (150, 150, 150)
    elif total_count == 1:
        hint_text = "잘하고 있어요!"
        hint_color = (255, 200, 100)
    elif total_count == 2:
        hint_text = "훌륭해요!"
        hint_color = (255, 200, 100)
        # 칭찬 메시지에 반짝임 효과
        if pygame.time.get_ticks() % 1000 < 500:
            hint_color = (255, 230, 150)
    elif total_count == 3:
        hint_text = "거의 다 왔어요!"
        hint_color = (100, 255, 255)
    else:
        hint_text = "미션 완료!"
        hint_color = (0, 255, 200)
        # 완료 시 강한 반짝임
        if pygame.time.get_ticks() % 600 < 300:
            hint_color = (100, 255, 255)
    
    # 힌트 텍스트 표시
    hint_surface = font_medium.render(hint_text, True, hint_color)
    hint_rect = hint_surface.get_rect(centerx=ui_x, top=bg_y + bg_height + 5)
    SCREEN.blit(hint_surface, hint_rect)

def show_chapter_title(chapter_num, title, subtitle=None):
    """챕터 타이틀 표시 (페이드 효과 포함)"""
    print(f"🎬 show_chapter_title 호출: Chapter {chapter_num} - {title}")
    clock = pygame.time.Clock()
    
    # 폰트 설정
    font_chapter = FontStyle.title()     # 48pt 챕터용
    font_title = FontStyle.subtitle()    # 32pt 타이틀용
    font_subtitle = FontStyle.body()     # 24pt 서브타이틀용
    
    # 화면을 검은색으로 페이드 아웃
    for alpha in range(255, 0, -16):  # 페이드 아웃
        SCREEN.fill((0, 0, 0))
        overlay = pygame.Surface((WIDTH, HEIGHT))
        overlay.set_alpha(255 - alpha)
        overlay.fill((0, 0, 0))
        SCREEN.blit(overlay, (0, 0))
        pygame.display.flip()
        clock.tick(60)
    
    # 검은 화면에 챕터 타이틀 표시
    display_duration = 120  # 2초
    fade_in_duration = 30   # 0.5초
    fade_out_duration = 30  # 0.5초
    
    for frame in range(display_duration):
        SCREEN.fill((0, 0, 0))
        
        # 페이드 인/아웃 알파 계산
        if frame < fade_in_duration:
            alpha = int((frame / fade_in_duration) * 255)
        elif frame >= display_duration - fade_out_duration:
            alpha = int(((display_duration - frame) / fade_out_duration) * 255)
        else:
            alpha = 255
        
        # Chapter 텍스트
        chapter_text = f"Chapter {chapter_num}"
        chapter_surface = font_chapter.render(chapter_text, True, (200, 200, 200))
        chapter_surface.set_alpha(alpha)
        chapter_rect = chapter_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2 - 50))
        SCREEN.blit(chapter_surface, chapter_rect)
        
        # 타이틀 텍스트
        title_surface = font_title.render(title, True, CYAN)
        title_surface.set_alpha(alpha)
        title_rect = title_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2 + 20))
        SCREEN.blit(title_surface, title_rect)
        
        # 서브타이틀 (있을 경우)
        if subtitle:
            subtitle_surface = font_subtitle.render(subtitle, True, (150, 150, 150))
            subtitle_surface.set_alpha(alpha)
            subtitle_rect = subtitle_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2 + 70))
            SCREEN.blit(subtitle_surface, subtitle_rect)
        
        pygame.display.flip()
        clock.tick(60)
        
        # ESC 키로 스킵 가능
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                return False
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    frame = display_duration  # 스킵
                    break  # 루프 즉시 종료
    
    # 페이드 아웃 (챕터 화면이 서서히 사라짐)
    SCREEN.fill((0, 0, 0))
    pygame.display.flip()
    
    print(f"[OK] Chapter {chapter_num} - {title} display complete")
    return True

