    # 스톱워치 보정/락 상태 (스마트폰)
    global stopwatch_forced_upward, stopwatch_upward_lock_timer
    # 스톱워치 보정/락 상태 (스마트폰)
    global stopwatch_forced_upward, stopwatch_upward_lock_timer
    # 스톱워치 보정/락 상태 (스마트폰)
    global stopwatch_forced_upward, stopwatch_upward_lock_timer
    # 롤링 관련 변수들
